injectStyles() {
    if (document.getElementById('liquid-morph-styles')) return;

    const styles = document.createElement('style');
    styles.id = 'liquid-morph-styles';
    styles.textContent = `
      .liquid-morph-overlay {
        position: fixed;
        top: 0;
