public async Task<int> CountMboxMessagesAsync(string mboxFilePath, IProgress<MboxParsingProgress>? progress = null)
    {
        return await Task.Run(() =>
        {
            if (!File.Exists(mboxFilePath))
            {
                throw new FileNotFoundException($"MBOX file not found: {mboxFilePath}");
            }

            var fileInfo = new FileInfo(mboxFilePath);
            var fileSizeInMB = fileInfo.Length / 1024.0 / 1024.0;

            progress?.Report(new MboxParsingProgress 
            { 
                Message = $"Counting messages in MBOX file ({fileSizeInMB:F2} MB)", 
                MessageCount = 0,
                FileSizeMB = fileSizeInMB
            });

            using var stream = File.OpenRead(mboxFilePath);
            var parser = new MimeParser(stream, MimeFormat.Mbox);

            int messageCount = 0;
            while (!parser.IsEndOfStream)
            {
                var message = parser.ParseMessage();
                if (message != null)
                {
                    messageCount++;
                    if (messageCount % 100 == 0)
                    {
                        progress?.Report(new MboxParsingProgress 
                        { 
                            Message = $"Counted {messageCount} messages...", 
                            MessageCount = messageCount,
                            FileSizeMB = fileSizeInMB
                        });
                    }
                }
            }

            progress?.Report(new MboxParsingProgress 
            { 
                Message = $"Finished counting. Total messages: {messageCount}", 
                MessageCount = messageCount,
                FileSizeMB = fileSizeInMB,
                IsCompleted = true
            });

            return messageCount;
        });
    }

def load_user_list(self, file_path):
        """从文件加载用户列表"""
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                if file_path.endswith('.json'):
                    return json.load(f)
                else:
                    # 假设是文本文件，每行一个UID
                    return [line.strip() for line in f if line.strip()]
        except Exception as e:
            print(f"加载用户列表失败: {e}")
            return []

def scrape_multiple_users(self, user_list, max_pages=5, delay=10):
        """批量抓取多个用户"""
        results = {}
        total_users = len(user_list)

        for i, uid in enumerate(user_list, 1):
            print(f"\n正在处理第 {i}/{total_users} 个用户: {uid}")

            try:
                result = self.scraper.scrape_user_weibos(uid, max_pages=max_pages)

                if result:
                    results[uid] = {
                        'success': True,
                        'user_info': result['user_info'],
                        'weibo_count': len(result['weibos']),
                        'output_dir': result['output_dir'],
                        'scrape_time': datetime.now().isoformat()
                    }
                    print(f"✅ 成功抓取用户 {result['user_info']['screen_name']}")
                else:
                    results[uid] = {
                        'success': False,
                        'error': 'Failed to scrape',
                        'scrape_time': datetime.now().isoformat()
                    }
                    print(f"❌ 抓取用户 {uid} 失败")

            except Exception as e:
                results[uid] = {
                    'success': False,
                    'error': str(e),
                    'scrape_time': datetime.now().isoformat()
                }
                print(f"❌ 抓取用户 {uid} 出现异常: {e}")

            # 添加延时避免被封
            if i < total_users:
                print(f"等待 {delay} 秒后继续...")
                time.sleep(delay)

        return results

def get_uid_from_url(weibo_url):
    """从微博链接中提取UID"""
    try:
        # 处理不同格式的微博链接
        if 'weibo.com/u/' in weibo_url:
            # https://weibo.com/u/1234567890
            uid = weibo_url.split('/u/')[1].split('?')[0].split('/')[0]
            return uid
        elif 'weibo.com/' in weibo_url and '/u/' not in weibo_url:
            # https://weibo.com/username 需要进一步解析
            return get_uid_from_username_url(weibo_url)
        elif 'm.weibo.cn/u/' in weibo_url:
            # https://m.weibo.cn/u/1234567890
            uid = weibo_url.split('/u/')[1].split('?')[0].split('/')[0]
            return uid
        else:
            print("不支持的链接格式")
            return None
    except Exception as e:
        print(f"解析链接失败: {e}")
        return None

def get_uid_from_username_url(weibo_url):
    """从用户名链接获取UID"""
    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
        }

        response = requests.get(weibo_url, headers=headers, allow_redirects=True)

        # 查找UID
        uid_pattern = r'"oid":"(\d+)"'
        match = re.search(uid_pattern, response.text)
        if match:
            return match.group(1)

        # 尝试其他模式
        uid_pattern2 = r'CONFIG\[\'oid\'\]=\'(\d+)\''
        match2 = re.search(uid_pattern2, response.text)
        if match2:
            return match2.group(1)

        # 从重定向URL中获取
        if '/u/' in response.url:
            return get_uid_from_url(response.url)

        print("无法从页面中提取UID")
        return None

    except Exception as e:
        print(f"请求失败: {e}")
        return None

def search_user_by_keyword(keyword):
    """通过关键词搜索用户"""
    try:
        search_url = f"https://m.weibo.cn/api/container/getIndex"
        params = {
            'containerid': f'100103type=1&q={keyword}',
            'page_type': 'searchall'
        }

        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'Referer': 'https://m.weibo.cn'
        }

        response = requests.get(search_url, params=params, headers=headers)
        data = response.json()

        if data.get('ok') == 1:
            cards = data.get('data', {}).get('cards', [])
            users = []

            for card in cards:
                if card.get('card_type') == 10:  # 用户卡片
                    card_group = card.get('card_group', [])
                    for group in card_group:
                        if group.get('card_type') == 10:
                            user = group.get('user', {})
                            users.append({
                                'uid': user.get('id'),
                                'screen_name': user.get('screen_name'),
                                'description': user.get('description', ''),
                                'followers_count': user.get('followers_count', 0),
                                'verified': user.get('verified', False)
                            })

            return users
        else:
            print("搜索失败")
            return []

    except Exception as e:
        print(f"搜索用户失败: {e}")
        return []

def main():
    """主函数"""
    print("=== 微博用户UID获取工具 ===")
    print("1. 从微博链接获取UID")
    print("2. 通过用户名搜索")

    choice = input("请选择操作方式 (1/2): ").strip()

    if choice == '1':
        weibo_url = input("请输入微博用户链接: ").strip()
        if weibo_url:
            uid = get_uid_from_url(weibo_url)
            if uid:
                print(f"提取到的UID: {uid}")
            else:
                print("无法提取UID")
        else:
            print("链接不能为空")

    elif choice == '2':
        keyword = input("请输入用户名关键词: ").strip()
        if keyword:
            print("正在搜索用户...")
            users = search_user_by_keyword(keyword)

            if users:
                print(f"\n找到 {len(users)} 个用户:")
                for i, user in enumerate(users, 1):
                    print(f"{i}. {user['screen_name']} (UID: {user['uid']})")
