def save_to_csv(self, data, filename):
        """保存数据到CSV文件"""
        try:
            df = pd.DataFrame(data)
            df.to_csv(filename, index=False, encoding='utf-8-sig')
            self.logger.info(f"数据已保存到 {filename}")
        except Exception as e:
            self.logger.error(f"保存CSV文件失败: {e}")

def save_to_json(self, data, filename):
        """保存数据到JSON文件"""
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            self.logger.info(f"数据已保存到 {filename}")
        except Exception as e:
            self.logger.error(f"保存JSON文件失败: {e}")

def __init__(self, headless=True):
        self.setup_logging()
        self.setup_driver(headless)

def get_user_profile(self, uid):
        """获取用户资料"""
        try:
            profile_url = f"https://m.weibo.cn/u/{uid}"
            self.driver.get(profile_url)
            time.sleep(3)

            # 获取用户基本信息
            user_info = {}

            try:
                # 用户名
                username_elem = self.wait.until(
                    EC.presence_of_element_located((By.CSS_SELECTOR, ".m-text-cut"))
                )
                user_info['username'] = username_elem.text
            except:
                user_info['username'] = ''

            try:
                # 粉丝数、关注数、微博数
                stats_elems = self.driver.find_elements(By.CSS_SELECTOR, ".m-item-box .m-box-center .m-font-num")
                if len(stats_elems) >= 3:
                    user_info['weibo_count'] = stats_elems[0].text
                    user_info['following_count'] = stats_elems[1].text
                    user_info['followers_count'] = stats_elems[2].text
            except:
                user_info['weibo_count'] = '0'
                user_info['following_count'] = '0'
                user_info['followers_count'] = '0'

            try:
                # 简介
                desc_elem = self.driver.find_element(By.CSS_SELECTOR, ".m-text-box")
                user_info['description'] = desc_elem.text
            except:
                user_info['description'] = ''

            user_info['uid'] = uid
            user_info['profile_url'] = profile_url

            return user_info

        except Exception as e:
            self.logger.error(f"获取用户资料失败: {e}")
            return None

def extract_weibo_data(self):
        """提取页面上的微博数据"""
        weibos = []

        try:
            # 查找所有微博卡片
            weibo_cards = self.driver.find_elements(By.CSS_SELECTOR, ".m-item-box")

            for i, card in enumerate(weibo_cards):
                try:
                    weibo_data = {}

                    # 微博文本内容
                    try:
                        text_elem = card.find_element(By.CSS_SELECTOR, ".m-text")
                        weibo_data['text'] = text_elem.text
                    except:
                        weibo_data['text'] = ''

                    # 发布时间
                    try:
                        time_elem = card.find_element(By.CSS_SELECTOR, ".m-font-gray")
                        weibo_data['created_at'] = time_elem.text
                    except:
                        weibo_data['created_at'] = ''

                    # 互动数据（点赞、评论、转发）
                    try:
                        action_elems = card.find_elements(By.CSS_SELECTOR, ".m-font-gray")
                        weibo_data['interactions'] = []
                        for elem in action_elems:
                            if elem.text and any(keyword in elem.text for keyword in ['赞', '评论', '转发']):
                                weibo_data['interactions'].append(elem.text)
                    except:
                        weibo_data['interactions'] = []

                    # 图片链接
                    try:
                        img_elems = card.find_elements(By.CSS_SELECTOR, "img")
                        weibo_data['images'] = [img.get_attribute('src') for img in img_elems if img.get_attribute('src')]
                    except:
                        weibo_data['images'] = []

                    # 微博链接
                    try:
                        link_elem = card.find_element(By.CSS_SELECTOR, "a")
                        weibo_data['link'] = link_elem.get_attribute('href')
                    except:
                        weibo_data['link'] = ''

                    weibo_data['index'] = i
                    weibos.append(weibo_data)

                except Exception as e:
                    self.logger.error(f"提取第 {i} 条微博数据失败: {e}")
                    continue

            return weibos

        except Exception as e:
            self.logger.error(f"提取微博数据失败: {e}")
            return []

def close(self):
        """关闭浏览器"""
        if hasattr(self, 'driver'):
            self.driver.quit()

def main():
    """主函数"""
    scraper = None
    try:
        # 询问是否使用无头模式
        headless_input = input("是否使用无头模式？(y/n, 默认y): ").strip().lower()
        headless = headless_input != 'n'

        scraper = WeiboSeleniumScraper(headless=headless)

        # 获取用户输入
        uid = input("请输入要抓取的微博用户UID: ").strip()
        if not uid:
            print("UID不能为空")
            return

        try:
            max_scrolls = int(input("请输入滚动次数（默认10次）: ").strip() or "10")
        except ValueError:
            max_scrolls = 10

        # 询问是否需要登录
        need_login = input("是否需要登录？(y/n, 默认n): ").strip().lower() == 'y'
        login_info = None
        if need_login:
            username = input("请输入用户名: ").strip()
            password = input("请输入密码: ").strip()
            if username and password:
                login_info = {'username': username, 'password': password}

        # 开始抓取
        result = scraper.scrape_user_weibos(uid, max_scrolls, login_info)

        if result:
            # 保存数据
            output_dir = scraper.save_data(result)
            print(f"\n抓取完成！")
            print(f"用户: {result['user_info']['username']}")
            print(f"获取微博数: {len(result['weibos'])}")
            print(f"数据保存在: {output_dir}")
        else:
            print("抓取失败")

    except KeyboardInterrupt:
        print("\n用户中断操作")
    except Exception as e:
        print(f"发生错误: {e}")
    finally:
        if scraper:
            scraper.close()

def to_html(self, include_details: bool = False) -> str:
        """Convert the entry to HTML format

        Args:
            include_details: Whether to include the details section with metadata
        """
        html_content = []

        # Photo name as H2
        html_content.append(f'<h2>{html.escape(self.filename)}</h2>')

        # Details section as H3 (only if include_details is True)
        if include_details:
            html_content.append('<h3>Details</h3>')
            html_content.append('<ul>')

            # Add metadata items to list
            if self.filepath:
                html_content.append(f'<li><strong>File Path:</strong> {html.escape(self.filepath)}</li>')

            if self.photo_date:
                html_content.append(f'<li><strong>Photo Date:</strong> {html.escape(self.photo_date)}</li>')

            if self.location:
                html_content.append(f'<li><strong>Location:</strong> {html.escape(self.location)}</li>')

            if self.camera:
                html_content.append(f'<li><strong>Camera:</strong> {html.escape(self.camera)}</li>')

            if self.settings:
                html_content.append(f'<li><strong>Settings:</strong> {html.escape(self.settings)}</li>')

            if self.model:
                html_content.append(f'<li><strong>Model:</strong> {html.escape(self.model)}</li>')

            if self.prompt_style:
                html_content.append(f'<li><strong>Prompt Style:</strong> {html.escape(self.prompt_style)}</li>')

            if self.timestamp:
                html_content.append(f'<li><strong>Generated:</strong> {html.escape(self.timestamp)}</li>')

            html_content.append('</ul>')

        # Description as H4
        html_content.append('<h4>Description</h4>')

        if self.description:
            # Convert line breaks to HTML and escape content
            description_html = html.escape(self.description).replace('\n', '<br>\n')
            html_content.append(f'<p>{description_html}</p>')
        else:
            html_content.append('<p><em>No description available</em></p>')

        return '\n'.join(html_content)

def __init__(self, input_file: Path):
        self.input_file = input_file
        self.entries: List[DescriptionEntry] = []

def _parse_section(self, section: str) -> Optional[DescriptionEntry]:
        """Parse a single section into a DescriptionEntry"""
        entry = DescriptionEntry()
        lines = section.split('\n')

        description_started = False
        description_lines = []

        for line in lines:
            line = line.strip()
            if not line:
                continue

            # Check if we've reached the description
            if line.startswith('Description:'):
                description_started = True
                desc_text = line[12:].strip()  # Remove 'Description: '
                if desc_text:
                    description_lines.append(desc_text)
                continue

            # If we're in description mode, collect all remaining lines
            if description_started:
                if line.startswith('Timestamp:'):
                    # End of description, parse timestamp
                    entry.timestamp = line[10:].strip()
                    break
                else:
                    description_lines.append(line)
                continue

            # Parse metadata fields
            if line.startswith('File:'):
                entry.filename = line[5:].strip()
            elif line.startswith('Path:'):
                entry.filepath = line[5:].strip()
            elif line.startswith('Photo Date:'):
                entry.photo_date = line[11:].strip()
            elif line.startswith('Location:'):
                entry.location = line[9:].strip()
            elif line.startswith('Camera:'):
                entry.camera = line[7:].strip()
            elif line.startswith('Settings:'):
                entry.settings = line[9:].strip()
            elif line.startswith('Model:'):
                entry.model = line[6:].strip()
            elif line.startswith('Prompt Style:'):
                entry.prompt_style = line[13:].strip()
            elif line.startswith('Timestamp:'):
                entry.timestamp = line[10:].strip()

        # Join description lines
        entry.description = '\n'.join(description_lines).strip()

        return entry

