            setTimeout(enforceSkipButtonVisibility, 100);
            setTimeout(enforceSkipButtonVisibility, 500);

            console.log('[DEBUG] Mode toggle changed, enforcing skip button visibility');
        }

// Initialize all label page functionality
function initializeLabelPage() {
    console.log('[DEBUG] Initializing label page functionality');

    // Load classes
    loadClasses();

    // Setup sidebar controls
    setupSidebarControls();

    // Setup mode toggle
    setupModeToggle();

    // Run skip button enforcement immediately
    enforceSkipButtonVisibility();

    // Then run periodically every second
    setInterval(enforceSkipButtonVisibility, 1000);

    console.log('[DEBUG] Label page initialization complete');
}

// Initialize the application
async function initApp() {
    try {
        console.log("[DEBUG] Starting application initialization");

        // Initialize application state
        initAppState();

        // Set up user role information
        initUserRole();

        // Initialize user roles from API
        await initializeUserRoles();

        // Setup UI based on user role
        await setupBasedOnRole();

        // Load batches from CosmosDB for selection
        try {
            await loadBatches();
        } catch (error) {
            console.error("[ERROR] Failed to load batches:", error);
            showMessage("Failed to load batches. Check console for details.", "error");
        }

        // Load available classes
        try {
            await loadClasses();
        } catch (error) {
            console.error("[ERROR] Failed to load classes:", error);
            showMessage("Failed to load classes. Check console for details.", "error");
        }

        // Initialize modular filter manager after classes are loaded
        try {
            const filterModule = await import('./modules/filter-manager.js');
            if (filterModule.initFilterManager) {
                filterModule.initFilterManager();
                console.log("[DEBUG] Filter manager module initialized");

                // Store filter manager functions globally for access
                window.modules = window.modules || {};
                window.modules.filterManager = {
                    openFilterDialog: filterModule.openFilterDialog,
                    closeFilterDialog: filterModule.closeFilterDialog,
                    applyFilters: filterModule.applyFilters,
                    resetFilters: filterModule.resetFilters,
                    refreshClassFilterOptions: filterModule.refreshClassFilterOptions,
                    setupFilterEventHandlers: filterModule.setupFilterEventHandlers
                };

                // Refresh class options now that classes are loaded
                if (filterModule.refreshClassFilterOptions) {
                    setTimeout(() => {
                        filterModule.refreshClassFilterOptions();
                    }, 100); // Small delay to ensure DOM is ready
                }
            }
        } catch (error) {
            console.error("[DEBUG] Error loading filter manager module:", error);
        }

        // Setup event handlers
        setupEventHandlers();
        setupNotesDialogHandlers();
        setupFilterDialogHandlers();

        // Initialize canvas with error handling
        try {
            initCanvas();
        } catch (error) {
            console.error("[ERROR] Failed to initialize canvas:", error);
        }

        // Flag to track the first image load
        window.AppState.isFirstImageLoad = true;

        // Initialize validation module
        import('./validation.js').then(({ initValidation }) => {
            if (initValidation) {
                initValidation();
                console.log("[DEBUG] Legacy validation module initialized");
            }
        }).catch(error => {
            console.warn("[DEBUG] Legacy validation module not found, using modular version");
        });

        // Initialize UI manager
        if (window.modules?.uiManager?.initializeUI) {
            window.modules.uiManager.initializeUI();
        }

        // Initialize theme
        if (window.modules?.uiDisplay?.initializeTheme) {
            window.modules.uiDisplay.initializeTheme();
        }

        console.log("[DEBUG] Application initialization completed successfully");

    } catch (error) {
        console.error("Error initializing app:", error);
        showMessage("Error initializing application. See console for details.", "error");
    }
}

