/**
 * Pan canvas by specified amount
 */
function panCanvas(deltaX, deltaY) {
    const AppState = getAppState();
    const canvas = AppState.fabricCanvas;

    if (!canvas) return;

    const vpt = canvas.viewportTransform;
    vpt[4] += deltaX;
    vpt[5] += deltaY;
    canvas.setViewportTransform(vpt);
}

