/**
 * Convert Fabric.js objects to COCO format
 */
function convertFabricToCoco(annotations) {
    const AppState = getAppState();

    console.log("[DEBUG] Converting Fabric.js annotations to COCO format");

    // Always create valid COCO structure, even for empty annotations
    if (!annotations) {
        annotations = [];
    }
    if (!Array.isArray(annotations)) {
        console.warn("[DEBUG] Invalid annotations format, using empty array");
        annotations = [];
    }

    try {
        // Create COCO structure with all required metadata fields
        const coco = {
            info: {
                description: "Facade Studio Annotations",
                version: "1.0",
                year: new Date().getFullYear(),
                date_created: new Date().toISOString()
            },
            images: [],
            annotations: [],
            categories: AppState.classes || [],
            // Add required metadata fields like the working example
            BatchID: AppState.currentBatch,
            ImageID: AppState.currentImageId,
            id: AppState.currentImageId,
            Status: "Labelled",
            admin_metadata: {
                Validation_User: "",
                Validation_Date: "",
                Validation_Action: "",
                Notes: ""
            }
        };

        // Add current image info if available
        if (AppState.currentImageId && AppState.currentImagePath) {
            coco.images.push({
                id: AppState.currentImageId,
                file_name: AppState.currentImagePath,
                width: AppState.originalImageWidth || AppState.currentImage?.width || 0,
                height: AppState.originalImageHeight || AppState.currentImage?.height || 0
            });
        }

        // Convert each annotation
        annotations.forEach((obj, index) => {
            if (obj.type !== 'polygon') {
                console.warn(`[DEBUG] Skipping non-polygon object at index ${index}`);
                return;
            }

            const className = obj.customData?.class || obj.class || 'unknown';

            // Find category ID
            const category = AppState.classes?.find(cat => cat.name === className);
            const categoryId = category?.id || 1;

            // Get polygon points - PRIORITY: Use stored imagePoints if available
            let imagePoints = [];

            if (obj.customData?.imagePoints && Array.isArray(obj.customData.imagePoints)) {
                // Use stored image points directly (already in image coordinates)
                imagePoints = obj.customData.imagePoints;
                console.log(`[DEBUG] Using stored imagePoints for ${className}:`, imagePoints);
            } else if (obj.points && Array.isArray(obj.points)) {
                // Fallback: Convert current polygon points to image coordinates
                console.log(`[DEBUG] Converting canvas points to image coordinates for ${className}`);
                imagePoints = obj.points.map(point => {
                    // Calculate absolute canvas coordinates
                    const canvasX = obj.left + point.x;
                    const canvasY = obj.top + point.y;

                    // Convert to image coordinates using current scale
                    return {
                        x: AppState.currentScale ? canvasX / AppState.currentScale : canvasX,
                        y: AppState.currentScale ? canvasY / AppState.currentScale : canvasY
                    };
                });
                console.log(`[DEBUG] Converted canvas points to image points:`, imagePoints);
            } else {
                console.warn(`[DEBUG] No valid points found for annotation ${index}`);
                return;
            }

            if (imagePoints.length < 3) {
                console.warn(`[DEBUG] Not enough points for annotation ${index}: ${imagePoints.length}`);
                return;
            }

            // Convert to flat array for segmentation
            const segmentation = [
                imagePoints.reduce((flat, point) => {
                    flat.push(point.x, point.y);
                    return flat;
                }, [])
            ];

            // Calculate bounding box [x, y, width, height]
            const xs = imagePoints.map(p => p.x);
            const ys = imagePoints.map(p => p.y);
            const minX = Math.min(...xs);
            const minY = Math.min(...ys);
            const maxX = Math.max(...xs);
            const maxY = Math.max(...ys);
            const bbox = [minX, minY, maxX - minX, maxY - minY];

            // Calculate area (approximate)
            const area = (maxX - minX) * (maxY - minY);

            // Create annotation object
            const annotation = {
                id: obj.customData?.cocoId || obj.id || index + 1,
                image_id: AppState.currentImageId || 1,
                category_id: categoryId,
                segmentation: segmentation,
                area: area,
                bbox: bbox,
                iscrowd: 0,
                objectId: obj.customData?.objectId || `obj-${Date.now()}-${index}`,
                created: obj.customData?.created || new Date().toISOString(),
                modified: obj.customData?.modified || new Date().toISOString()
            };

            console.log(`[DEBUG] Created COCO annotation for ${className}:`, {
                points: imagePoints.length,
                bbox: bbox,
                area: area
            });

            // Add to annotations array
            coco.annotations.push(annotation);
        });

        console.log(`[DEBUG] Converted ${coco.annotations.length} annotations to COCO format`);
        return coco;

    } catch (error) {
        console.error("[DEBUG] Error converting to COCO format:", error);
        showMessage("Error converting annotations", "error");
        return null;
    }
}

