/**
 * Convert polygon points to different coordinate systems
 */
function convertCoordinates(points, fromSystem, toSystem, imageWidth, imageHeight, canvasWidth, canvasHeight) {
    if (!points || !Array.isArray(points)) {
        return [];
    }

    return points.map(point => {
        let x = point.x;
        let y = point.y;

        // Convert from source system to normalized (0-1)
        if (fromSystem === 'image') {
            x = x / imageWidth;
            y = y / imageHeight;
        } else if (fromSystem === 'canvas') {
            x = x / canvasWidth;
            y = y / canvasHeight;
        }
        // 'normalized' stays as is

        // Convert from normalized to target system
        if (toSystem === 'image') {
            x = x * imageWidth;
            y = y * imageHeight;
        } else if (toSystem === 'canvas') {
            x = x * canvasWidth;
            y = y * canvasHeight;
        }
        // 'normalized' stays as is

        return { x, y };
    });
}

