/**
 * Create event processor for specific event types
 */
function createEventProcessor(eventType, handler) {
    return {
        type: eventType,
        handler: handler,
        process: function(event) {
            if (event.type === this.type) {
                this.handler(event);
                return true;
            }
            return false;
        }
    };
}

