/**
 * Get CSS class for status
 */
function getStatusClass(status) {
    switch (status?.toLowerCase()) {
        case 'completed': 
        case 'approved': 
            return 'status-completed';
        case 'in progress': 
        case 'pending': 
            return 'status-in-progress';
        case 'reviewed': 
            return 'status-reviewed';
        case 'rejected': 
            return 'status-rejected';
        default: 
            return 'status-default';
    }
}

