private Mock<HttpRequest> CreateMockHttpRequestWithBody(string body)
    {
        var request = new Mock<HttpRequest>();
        var headers = new HeaderDictionary();
        headers.Add("x-api-key", "umuthi-dev-api-key"); // Valid API key for tests

        request.Setup(r => r.Headers).Returns(headers);
        request.Setup(r => r.Body).Returns(new MemoryStream(Encoding.UTF8.GetBytes(body)));

        return request;
    }

/**
 * Ensures that the Assets sheet exists with proper headers.
 * @return {Sheet} The Assets sheet instance.
 */
function ensureAssetsSheetExists() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var assetsSheet = ss.getSheetByName(ASSETS_SHEET_NAME);
  if (!assetsSheet) {
    assetsSheet = ss.insertSheet(ASSETS_SHEET_NAME);
    assetsSheet.appendRow(["Project ID", "File ID", "File Name", "Upload Date"]);
  }
  return assetsSheet;
}

/**
 * Triggered when the user changes selection in the spreadsheet.
 * Opens the asset dialog when selecting a cell in the asset column.
 *
 * @param {GoogleAppsScript.Events.SheetsOnSelectionChange} e Event object.
 */
function onSelectionChange(e) {
  var sheet = e.range.getSheet();
  if (!loadConfig()) return;
  if (sheet.getName() !== CONTENT_SHEET_NAME) return;
  try {
    getHeaderIndexes(sheet);
  } catch (err) {
    return;
  }

  var row = e.range.getRow();
  if (row < 3) return; // skip headers
  if (e.range.getColumn() !== ASSET_ACTION_COL_IDX) return;

  var cellValue = e.range.getValue();
  var rowIdentifier = getRowIdentifier(sheet, row);
  if (cellValue === "Assign Asset") {
    showAssignAssetDialog(rowIdentifier, row);
  }
}

def is_multithreading_supported() -> bool:
    """
    Check if WebAssembly multithreading is supported in the current environment.

    Returns:
        bool: True if WebAssembly multithreading is supported, False otherwise.
    """
    try:
        import js
        return (hasattr(js.WebAssembly, 'Feature') and 
                js.WebAssembly.Feature.threads and 
                hasattr(js.window, 'SharedArrayBuffer'))
    except ImportError:
        try:
            import emscripten
            return bool(emscripten.run_script_int(
                "typeof WebAssembly.Feature !== 'undefined' && "
                "WebAssembly.Feature.threads && "
                "typeof SharedArrayBuffer !== 'undefined' ? 1 : 0"
            ))
        except ImportError:
            return False

def enable_multithreading() -> bool:
    """
    Enable multithreading for WebAssembly if available.

    Returns:
        bool: True if multithreading was enabled, False otherwise.
    """
    if not is_multithreading_supported():
        return False

    try:
        import js
        js.globalThis.NEURENIX_MULTITHREADING_ENABLED = True
        return True
    except ImportError:
        try:
            import emscripten
            emscripten.run_script("globalThis.NEURENIX_MULTITHREADING_ENABLED = true;")
            return True
        except ImportError:
            return False

def get_num_workers() -> int:
    """
    Get the number of available worker threads.

    Returns:
        int: Number of available worker threads, or 1 if multithreading is not supported.
    """
    if not is_multithreading_supported():
        return 1

    try:
        import js
        return max(1, js.navigator.hardwareConcurrency)
    except (ImportError, AttributeError):
        try:
            import emscripten
            return max(1, int(emscripten.run_script_int("navigator.hardwareConcurrency || 1")))
        except (ImportError, ValueError):
            return 1

def _worker_loop(self):
        """
        Worker thread loop.
        """
        while True:
            task_id, func, args, kwargs = self.task_queue.get()

            try:
                result = func(*args, **kwargs)
                self.result_queue.put((task_id, result, None))
            except Exception as e:
                self.result_queue.put((task_id, None, e))

            self.task_queue.task_done()

def parallel_matmul(a: Tensor, b: Tensor) -> Tensor:
    """
    Perform matrix multiplication using multiple threads if available.

    Args:
        a: First tensor
        b: Second tensor

    Returns:
        Tensor: Result of matrix multiplication
    """
    if not is_multithreading_supported() or a.device.device_type != DeviceType.WEBGPU:
        return a @ b

    try:
        from neurenix.binding import wasm_parallel_matmul
        return wasm_parallel_matmul(a, b)
    except (ImportError, AttributeError):
        return a @ b

def parallel_map(func: Callable, tensors: List[Tensor]) -> List[Tensor]:
    """
    Apply a function to each tensor in parallel.

    Args:
        func: Function to apply
        tensors: List of tensors to process

    Returns:
        List of processed tensors
    """
    if not is_multithreading_supported():
        return [func(tensor) for tensor in tensors]

    try:
        pool = ThreadPool()
        return pool.map(func, tensors)
    except Exception:
        return [func(tensor) for tensor in tensors]

def parallel_batch_processing(model: Module, batches: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """
    Process multiple batches in parallel using a model.

    Args:
        model: Model to use for processing
        batches: List of input batches

    Returns:
        List of model outputs
    """
    if not is_multithreading_supported():
        return [model(batch) for batch in batches]

    try:
        pool = ThreadPool()
        return pool.map(model, batches)
    except Exception:
        return [model(batch) for batch in batches]

bool is_multithreading_supported() {
#ifdef __EMSCRIPTEN_PTHREADS__
    return true;
#else
    return false;
#endif
}

bool enable_multithreading() {
#ifdef __EMSCRIPTEN_PTHREADS__
    return true;
#else
    return false;
#endif
}

size_t get_num_workers() {
#ifdef __EMSCRIPTEN_PTHREADS__
    return 4;
#else
    return std::thread::hardware_concurrency();
#endif
}

ThreadPool(size_t num_threads)
        : stop_(false)
    {
        for (size_t i = 0; i < num_threads; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::function<void()> task;

                    {
                        std::unique_lock<std::mutex> lock(queue_mutex_);
                        condition_.wait(lock, [this] { 
                            return stop_ || !tasks_.empty(); 
                        });

                        if (stop_ && tasks_.empty()) {
                            return;
                        }

                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }

                    task();
                }
            });
        }
    }

~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            stop_ = true;
        }

        condition_.notify_all();

        for (std::thread& worker : workers_) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

auto enqueue(F&& f, Args&&... args) 
        -> std::future<typename std::result_of<F(Args...)>::type>
    {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> result = task->get_future();

        {
            std::unique_lock<std::mutex> lock(queue_mutex_);

            if (stop_) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }

            tasks_.emplace([task]() { (*task)(); });
        }

        condition_.notify_one();
        return result;
    }

MultithreadedBackend::~MultithreadedBackend() {
    cleanup();
}

bool MultithreadedBackend::initialize() {
    if (initialized_) {
        return true;
    }

    if (!is_multithreading_supported()) {
        return false;
    }

    try {
        num_threads_ = get_num_workers();
        thread_pool_ = new ThreadPool(num_threads_);
        initialized_ = true;
        return true;
    } catch (const std::exception& e) {
        std::cerr << "Multithreaded backend initialization error: " << e.what() << std::endl;
        cleanup();
        return false;
    }
}

void MultithreadedBackend::cleanup() {
    if (!initialized_) {
        return;
    }

    if (thread_pool_ != nullptr) {
        delete static_cast<ThreadPool*>(thread_pool_);
        thread_pool_ = nullptr;
    }

    initialized_ = false;
}

void MultithreadedBackend::set_precision(MultithreadedPrecision precision) {
    precision_ = precision;
}

MultithreadedPrecision MultithreadedBackend::get_precision() const {
    return precision_;
}

Tensor MultithreadedBackend::parallel_matmul(const Tensor& a, const Tensor& b) {
    if (!initialized_) {
        throw std::runtime_error("Multithreaded backend is not initialized");
    }


    return a.matmul(b);
}

Tensor MultithreadedBackend::parallel_conv2d(
    const Tensor& input,
    const Tensor& weight,
    const Tensor* bias,
    const std::pair<size_t, size_t>& stride,
    const std::pair<size_t, size_t>& padding,
    const std::pair<size_t, size_t>& dilation,
    size_t groups
) {
    if (!initialized_) {
        throw std::runtime_error("Multithreaded backend is not initialized");
    }


    return input;
}

std::vector<Tensor> MultithreadedBackend::parallel_map(
    std::function<Tensor(const Tensor&)> func,
    const std::vector<Tensor>& tensors
) {
    if (!initialized_) {
        throw std::runtime_error("Multithreaded backend is not initialized");
    }

    if (tensors.empty()) {
        return {};
    }

    if (tensors.size() == 1) {
        return {func(tensors[0])};
    }

    std::vector<Tensor> results(tensors.size());
    std::vector<std::future<Tensor>> futures;

    ThreadPool* pool = static_cast<ThreadPool*>(thread_pool_);

    for (size_t i = 0; i < tensors.size(); ++i) {
        futures.push_back(pool->enqueue(func, tensors[i]));
    }

    for (size_t i = 0; i < futures.size(); ++i) {
        results[i] = futures[i].get();
    }

    return results;
}

std::vector<Tensor> MultithreadedBackend::parallel_batch_processing(
    const std::shared_ptr<Model>& model,
    const std::vector<Tensor>& batches
) {
    if (!initialized_) {
        throw std::runtime_error("Multithreaded backend is not initialized");
    }

    if (batches.empty()) {
        return {};
    }

    if (batches.size() == 1) {
        return {model->forward(batches[0])};
    }

    std::vector<Tensor> results(batches.size());
    std::vector<std::future<Tensor>> futures;

    ThreadPool* pool = static_cast<ThreadPool*>(thread_pool_);

    for (size_t i = 0; i < batches.size(); ++i) {
        futures.push_back(pool->enqueue([model](const Tensor& batch) {
            return model->forward(batch);
        }, batches[i]));
    }

    for (size_t i = 0; i < futures.size(); ++i) {
        results[i] = futures[i].get();
    }

    return results;
}

// SEO Expert Portfolio - Interactive JavaScript

function() {

    // Mobile Navigation Toggle
    const navToggle = document.getElementById('nav-toggle');
    const navMenu = document.getElementById('nav-menu');

    if (navToggle && navMenu) {
        navToggle.addEventListener('click', function() {
            navMenu.classList.toggle('active');
            navToggle.classList.toggle('active');

            // Update aria-expanded for accessibility
            const isExpanded = navMenu.classList.contains('active');
            navToggle.setAttribute('aria-expanded', isExpanded);

            // Prevent body scroll when menu is open
            document.body.style.overflow = isExpanded ? 'hidden' : '';
        });

        // Close menu when clicking outside
        document.addEventListener('click', function(e) {
            if (!navToggle.contains(e.target) && !navMenu.contains(e.target)) {
                navMenu.classList.remove('active');
                navToggle.classList.remove('active');
                navToggle.setAttribute('aria-expanded', 'false');
                document.body.style.overflow = '';
            }
        });

        // Close menu when clicking on nav links
        const navLinks = navMenu.querySelectorAll('.nav-link');
        navLinks.forEach(link => {
            link.addEventListener('click', function() {
                navMenu.classList.remove('active');
                navToggle.classList.remove('active');
                navToggle.setAttribute('aria-expanded', 'false');
                document.body.style.overflow = '';
            });
        });
    }

    // Smooth Scrolling for Internal Links
    const internalLinks = document.querySelectorAll('a[href^="#"]');
    internalLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const targetId = this.getAttribute('href').substring(1);
            const targetElement = document.getElementById(targetId);

            if (targetElement) {
                const headerHeight = document.querySelector('.header').offsetHeight;
                const targetPosition = targetElement.offsetTop - headerHeight;

                window.scrollTo({
                    top: targetPosition,
                    behavior: 'smooth'
                });
            }
        });
    });

    // Header Scroll Effect
    const header = document.querySelector('.header');
    if (header) {
        let lastScrollY = window.scrollY;

        window.addEventListener('scroll', function() {
            const currentScrollY = window.scrollY;

            // Add/remove scrolled class for styling
            if (currentScrollY > 50) {
                header.classList.add('scrolled');
            } else {
                header.classList.remove('scrolled');
            }

            // Hide/show header on scroll (optional)
            if (currentScrollY > lastScrollY && currentScrollY > 100) {
                header.style.transform = 'translateY(-100%)';
            } else {
                header.style.transform = 'translateY(0)';
            }

            lastScrollY = currentScrollY;
        });
    }

    // Intersection Observer for Animations
    const observerOptions = {
        threshold: 0.1,
        rootMargin: '0px 0px -50px 0px'
    };

    const observer = new IntersectionObserver(function(entries) {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('fade-in-up');
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Observe elements for animation
    const animatedElements = document.querySelectorAll('.service-card, .result-card, .section-header');
    animatedElements.forEach(element => {
        observer.observe(element);
    });

    // Counter Animation for Stats
    function animateCounter(element, start, end, duration) {
        let startTimestamp = null;
        const step = (timestamp) => {
            if (!startTimestamp) startTimestamp = timestamp;
            const progress = Math.min((timestamp - startTimestamp) / duration, 1);
            const current = Math.floor(progress * (end - start) + start);
            element.textContent = current + (element.dataset.suffix || '');
            if (progress < 1) {
                window.requestAnimationFrame(step);
            }
        };
        window.requestAnimationFrame(step);
    }

    // Animate counters when they come into view
    const statNumbers = document.querySelectorAll('.stat-number, .metric-number');
    const statsObserver = new IntersectionObserver(function(entries) {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const element = entry.target;
                const text = element.textContent;
                const number = parseInt(text.replace(/[^\d]/g, ''));
                const suffix = text.replace(/[\d]/g, '');

                element.dataset.suffix = suffix;
                animateCounter(element, 0, number, 2000);
                statsObserver.unobserve(element);
            }
        });
    }, observerOptions);

    statNumbers.forEach(stat => {
        statsObserver.observe(stat);
    });

    // Form Validation (for future contact forms)
    function validateEmail(email) {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(email);
    }

    function validateForm(form) {
        const inputs = form.querySelectorAll('input[required], textarea[required]');
        let isValid = true;

        inputs.forEach(input => {
            const value = input.value.trim();
            const errorElement = input.nextElementSibling;

            // Remove existing error messages
            if (errorElement && errorElement.classList.contains('error-message')) {
                errorElement.remove();
            }

            input.classList.remove('error');

            // Validate based on input type
            if (!value) {
                showError(input, 'This field is required');
                isValid = false;
            } else if (input.type === 'email' && !validateEmail(value)) {
                showError(input, 'Please enter a valid email address');
                isValid = false;
            }
        });

        return isValid;
    }

    function showError(input, message) {
        input.classList.add('error');
        const errorElement = document.createElement('span');
        errorElement.classList.add('error-message');
        errorElement.textContent = message;
        errorElement.style.color = '#dc2626';
        errorElement.style.fontSize = '0.875rem';
        errorElement.style.marginTop = '0.25rem';
        errorElement.style.display = 'block';
        input.parentNode.insertBefore(errorElement, input.nextSibling);
    }

    // Handle form submissions
    const forms = document.querySelectorAll('form');
    forms.forEach(form => {
        form.addEventListener('submit', function(e) {
            e.preventDefault();

            if (validateForm(this)) {
                // Form is valid, proceed with submission
                showSuccessMessage(this);
            }
        });
    });

    function showSuccessMessage(form) {
        const successMessage = document.createElement('div');
        successMessage.classList.add('success-message');
        successMessage.innerHTML = `
            <p style="color: #059669; background: #d1fae5; padding: 1rem; border-radius: 8px; margin-top: 1rem;">
                ✓ Thank you! Your message has been sent successfully. I'll get back to you within 24 hours.
            </p>
        `;
        form.appendChild(successMessage);
        form.reset();

        // Remove success message after 5 seconds
        setTimeout(() => {
            successMessage.remove();
        }, 5000);
    }

    // Keyboard Navigation Support
    document.addEventListener('keydown', function(e) {
        // Close mobile menu with Escape key
        if (e.key === 'Escape' && navMenu && navMenu.classList.contains('active')) {
            navMenu.classList.remove('active');
            navToggle.classList.remove('active');
            navToggle.setAttribute('aria-expanded', 'false');
            document.body.style.overflow = '';
            navToggle.focus();
        }
    });

    // Performance: Lazy Loading for Images (when added)
    if ('IntersectionObserver' in window) {
        const imageObserver = new IntersectionObserver(function(entries) {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const img = entry.target;
                    img.src = img.dataset.src;
                    img.classList.remove('lazy');
                    imageObserver.unobserve(img);
                }
            });
        });

        const lazyImages = document.querySelectorAll('img[data-src]');
        lazyImages.forEach(img => {
            imageObserver.observe(img);
        });
    }

    // Service Worker Registration (for PWA capabilities)
    if ('serviceWorker' in navigator) {
        window.addEventListener('load', function() {
            navigator.serviceWorker.register('/sw.js')
                .then(function(registration) {
                    console.log('ServiceWorker registration successful');
                })
                .catch(function(err) {
                    console.log('ServiceWorker registration failed');
                });
        });
    }

    // Google Analytics (GA4) - Replace with actual tracking ID
    function initializeGA() {
        // gtag('config', 'GA_TRACKING_ID');
        console.log('Analytics initialized');
    }

    // Track button clicks for analytics
    const trackingButtons = document.querySelectorAll('.btn, .nav-link');
    trackingButtons.forEach(button => {
        button.addEventListener('click', function() {
            const buttonText = this.textContent.trim();
            const buttonType = this.classList.contains('btn-primary') ? 'primary' : 'secondary';

            // Send event to analytics
            if (typeof gtag !== 'undefined') {
                gtag('event', 'click', {
                    event_category: 'Button',
                    event_label: buttonText,
                    custom_parameter: buttonType
                });
            }

            console.log(`Button clicked: ${buttonText} (${buttonType})`);
        });
    });

    // Contact Information Click Tracking
    const contactLinks = document.querySelectorAll('a[href^="tel:"], a[href^="mailto:"]');
    contactLinks.forEach(link => {
        link.addEventListener('click', function() {
            const type = this.href.startsWith('tel:') ? 'phone' : 'email';

            if (typeof gtag !== 'undefined') {
                gtag('event', 'contact', {
                    event_category: 'Contact',
                    event_label: type,
                    value: 1
                });
            }

            console.log(`Contact method used: ${type}`);
        });
    });

    // Scroll to Top Functionality
    const scrollToTopBtn = document.createElement('button');
    scrollToTopBtn.innerHTML = '↑';
    scrollToTopBtn.setAttribute('aria-label', 'Scroll to top');
    scrollToTopBtn.classList.add('scroll-to-top');
    scrollToTopBtn.style.cssText = `
        position: fixed;
        bottom: 2rem;
        right: 2rem;
        background: #2563eb;
        color: white;
        border: none;
        border-radius: 50%;
        width: 50px;
        height: 50px;
        cursor: pointer;
        font-size: 1.25rem;
        opacity: 0;
        visibility: hidden;
        transition: all 0.3s ease;
        z-index: 1000;
        box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
    `;

    document.body.appendChild(scrollToTopBtn);

    // Show/hide scroll to top button
    window.addEventListener('scroll', function() {
        if (window.scrollY > 300) {
            scrollToTopBtn.style.opacity = '1';
            scrollToTopBtn.style.visibility = 'visible';
        } else {
            scrollToTopBtn.style.opacity = '0';
            scrollToTopBtn.style.visibility = 'hidden';
        }
    });

    scrollToTopBtn.addEventListener('click', function() {
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    });

    // Initialize all functionality
    initializeGA();

    console.log('SEO Expert Portfolio initialized successfully!');
}

