def parse_arguments():
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(description="NOVAXA Bot Webhook Configuration")

    parser.add_argument("--token", help="Bot token or token ID from token manager")
    parser.add_argument("--url", help="Render URL (e.g., https://novaxa-bot.onrender.com)")
    parser.add_argument("--chat-id", help="Chat ID to send test message to")

    if token_manager_available:
        parser.add_argument("--use-manager", action="store_true", 
                          help="Use token manager instead of direct token")

    return parser.parse_args()

def get_token_from_manager(token_id):
    """Get token from token manager."""
    if not token_manager_available:
        print("❌ Token manager not available. Please install the security module.")
        return None

    try:
        master_key = os.environ.get("NOVAXA_MASTER_KEY")
        if not master_key:
            print("NOVAXA_MASTER_KEY not set in environment.")
            master_key = getpass.getpass("Enter master key: ")

        token_manager = TokenManager(master_key=master_key)

        if token_id == "active":
            token = token_manager.get_token()
            if not token:
                print("❌ No active token found.")
                return None
            return token
        else:
            token = token_manager.get_token(token_id)
            if not token:
                print(f"❌ Token with ID {token_id} not found.")
                return None
            return token

    except Exception as e:
        print(f"❌ Error getting token from manager: {e}")
        return None

def check_webhook_status(token):
    """Check the current webhook status."""
    print("\n🔍 Checking current webhook status...")
    url = f"https://api.telegram.org/bot{token}/getWebhookInfo"

    try:
        response = requests.get(url)
        webhook_info = response.json()

        if webhook_info.get("ok") and webhook_info.get("result"):
            result = webhook_info["result"]
            if result.get("url"):
                print(f"✅ Current webhook URL: {result['url']}")
                print(f"📊 Pending updates: {result.get('pending_update_count', 0)}")
                if result.get("last_error_date"):
                    print(f"❌ Last error: {result.get('last_error_message', 'Unknown error')}")
                    print(f"⏰ Last error date: {result.get('last_error_date')}")
                return result.get("url")
            else:
                print("ℹ️ No webhook URL set. Bot is in polling mode.")
                return None
        else:
            print(f"❌ Error: {webhook_info.get('description', 'Unknown error')}")
            return None

    except Exception as e:
        print(f"❌ Error checking webhook status: {e}")
        return None

def set_webhook(token, webhook_url):
    """Set the webhook URL."""
    print(f"\n🔧 Setting webhook to: {webhook_url}")

    if not webhook_url.endswith("/webhook"):
        webhook_url = webhook_url.rstrip("/") + "/webhook"
        print(f"ℹ️ Added /webhook to URL: {webhook_url}")

    url = f"https://api.telegram.org/bot{token}/setWebhook"
    params = {
        "url": webhook_url,
        "drop_pending_updates": True
    }

    try:
        response = requests.post(url, params=params)
        result = response.json()

        if result.get("ok"):
            print(f"✅ Webhook successfully set to: {webhook_url}")
            return True
        else:
            print(f"❌ Error setting webhook: {result.get('description', 'Unknown error')}")
            return False

    except Exception as e:
        print(f"❌ Error setting webhook: {e}")
        return False

def send_test_message(token, chat_id=None):
    """Send a test message to verify the bot is working."""
    if not chat_id:
        print("\n⚠️ No chat ID provided. Skipping test message.")
        return False

    print(f"\n📤 Sending test message to chat ID: {chat_id}")
    url = f"https://api.telegram.org/bot{token}/sendMessage"
    params = {
        "chat_id": chat_id,
        "text": "🎉 NOVAXA Bot webhook has been configured successfully! 🎉\n\nThis is a test message to verify the bot is working.",
        "parse_mode": "HTML"
    }

    try:
        response = requests.post(url, params=params)
        result = response.json()

        if result.get("ok"):
            print(f"✅ Test message sent successfully to chat ID: {chat_id}")
            return True
        else:
            print(f"❌ Error sending message: {result.get('description', 'Unknown error')}")
            return False

    except Exception as e:
        print(f"❌ Error sending message: {e}")
        return False

def is_owner(user_id: int) -> bool:
    """Check if a user is the owner."""
    return user_id == OWNER_ID and ip_protection.verify_owner(user_id)

def format_output(title, data, is_error=False):
    """Format output with colors for Termux."""
    RESET = "\033[0m"
    GREEN = "\033[32m"
    RED = "\033[31m"
    YELLOW = "\033[33m"
    BLUE = "\033[34m"
    BOLD = "\033[1m"

    color = RED if is_error else GREEN

    print(f"\n{BOLD}{color}=== {title} ==={RESET}\n")

    if isinstance(data, str):
        print(data)
    elif isinstance(data, list):
        for item in data:
            print(item)
    elif isinstance(data, dict):
        for key, value in data.items():
            print(f"{YELLOW}{key}{RESET}: {value}")

    print()

def main():
    """Main function."""
    parser = setup_parser()
    args = parser.parse_args()

    if not args.command:
        parser.print_help()
        return

    try:
        master_key = get_master_key()
        token_manager = TokenManager(master_key=master_key)

        if args.command == "list":
            tokens = token_manager.get_tokens()

            if not tokens:
                format_output("Tokens", "No tokens found.")
                return

            header = f"{'ID':<10} {'Name':<20} {'Status':<10} {'Created':<12}"
            separator = "-" * 55
            rows = [header, separator]

            for token in tokens:
                status = "ACTIVE" if token["active"] else token["status"].upper()
                created = token["created"][:10]
                rows.append(f"{token['id']:<10} {token['name']:<20} {status:<10} {created:<12}")

            format_output("Tokens", rows)

        elif args.command == "add":
            token_id = token_manager.add_token(args.token, args.name, args.owner)
            format_output("Token Added", f"Token added with ID: {token_id}")
            print(f"Use './manage_tokens.py activate {token_id}' to activate this token.")

        elif args.command == "activate":
            if token_manager.activate_token(args.token_id):
                format_output("Token Activated", f"Token {args.token_id} activated.")
                print("Please restart the bot to apply the new token.")
            else:
                format_output("Error", f"Failed to activate token {args.token_id}.", True)

        elif args.command == "deactivate":
            if token_manager.deactivate_token(args.token_id):
                format_output("Token Deactivated", f"Token {args.token_id} deactivated.")
            else: 
                format_output("Error", f"Failed to deactivate token {args.token_id}.", True)

        elif args.command == "delete":
            confirm = input(f"Are you sure you want to delete token {args.token_id}? (y/n): ")
            if confirm.lower() == "y":
                if token_manager.delete_token(args.token_id):
                    format_output("Token Deleted", f"Token {args.token_id} deleted.")
                else:
                    format_output("Error", f"Failed to delete token {args.token_id}.", True)
            else:
                format_output("Cancelled", "Deletion cancelled.")

        elif args.command == "rotate":
            if token_manager.rotate_token(args.token_id, args.new_token):
                format_output("Token Rotated", f"Token {args.token_id} rotated to new value.")
                print("Please restart the bot to apply the new token.")
            else:
                format_output("Error", f"Failed to rotate token {args.token_id}.", True)

        elif args.command == "active":
            token_id = token_manager.active_token_id

            if not token_id:
                format_output("Active Token", "No active token.")
                return

            tokens = token_manager.get_tokens()
            active_token = next((t for t in tokens if t["id"] == token_id), None)

            if active_token:
                format_output("Active Token", {
                    "ID": active_token["id"],
                    "Name": active_token["name"],
                    "Created": active_token["created"][:10],
                    "Status": "ACTIVE"
                })
            else:
                format_output("Error", "No active token information available.", True)

    except Exception as e:
        format_output("Error", f"An error occurred: {str(e)}", True)
        sys.exit(1)

def _load_tokens(self):
        """Load tokens from file."""
        try:
            if os.path.exists(self.token_file):
                with open(self.token_file, "r") as f:
                    data = json.load(f)
                    self.tokens = data.get("tokens", {})
                    self.active_token_id = data.get("active_token_id")
                    logger.info(f"Loaded {len(self.tokens)} tokens from configuration")
            else:
                logger.info("No tokens configuration file found, using defaults")
                self._save_tokens()
        except Exception as e:
            logger.error(f"Error loading tokens: {e}")

def _save_tokens(self):
        """Save tokens to file."""
        try:
            data = {
                "tokens": self.tokens,
                "active_token_id": self.active_token_id,
                "last_updated": datetime.now().isoformat(),
            }

            with open(self.token_file, "w") as f:
                json.dump(data, f, indent=2)

            logger.info("Tokens configuration saved")
        except Exception as e:
            logger.error(f"Error saving tokens: {e}")

def _encrypt(self, text: str) -> str:
        """Encrypt text using the master key."""
        if not self.master_key:
            logger.warning("No master key set, using plaintext")
            return text

        try:
            key = hashlib.sha256(self.master_key.encode()).digest()
            return base64.b64encode(
                hmac.new(key, text.encode(), hashlib.sha256).digest() +
                text.encode()
            ).decode()
        except Exception as e:
            logger.error(f"Error encrypting text: {e}")
            return text

def _decrypt(self, encrypted_text: str) -> str:
        """Decrypt text using the master key."""
        if not self.master_key:
            logger.warning("No master key set, using plaintext")
            return encrypted_text

        try:
            data = base64.b64decode(encrypted_text.encode())
            text = data[32:].decode()
            return text
        except Exception as e:
            logger.error(f"Error decrypting text: {e}")
            return encrypted_text

def log_event(self, event_type: str, details: Dict = None, user_id: int = None):
        """Log a security event."""
        timestamp = datetime.now()

        event = {
            "timestamp": timestamp.isoformat(),
            "type": event_type,
            "details": details or {},
            "user_id": user_id,
        }

        self.logs.append(event)
        if len(self.logs) > self.max_logs:
            self.logs.pop(0)

        log_message = f"Security event: {event_type}"
        if user_id:
            log_message += f" (User: {user_id})"

        logger.info(log_message)

        try:
            with open(self.log_file, "a") as f:
                f.write(json.dumps(event) + "\n")
        except Exception as e:
            logger.error(f"Error writing to security log file: {e}")

def get_recent_events(self, count: int = 10, event_type: str = None, user_id: int = None) -> List[Dict]:
        """Get recent security events."""
        filtered_events = self.logs

        if event_type:
            filtered_events = [event for event in filtered_events if event["type"] == event_type]

        if user_id:
            filtered_events = [event for event in filtered_events if event["user_id"] == user_id]

        filtered_events.sort(key=lambda x: x["timestamp"], reverse=True)

        return filtered_events[:count]

