def _validate_api_key_format(self, api_key: str) -> bool:
        """Validate API key format.

        Args:
            api_key: API key string

        Returns:
            True if format is valid, False otherwise
        """
        if not api_key or not isinstance(api_key, str):
            return False

        # Check length bounds
        if len(api_key) < 10 or len(api_key) > 512:
            return False

        # Check for null bytes and control characters
        if "\x00" in api_key or any(ord(c) < 32 for c in api_key):
            return False

        # Basic format check for our API key format: sk_service_keyid_secret
        if api_key.startswith("sk_"):
            parts = api_key.split("_")
            if len(parts) >= 4:
                return True

        # Allow other formats but they must be printable ASCII
        return all(32 <= ord(c) <= 126 for c in api_key)

def get_effective_limits(
        self, service: Optional[str] = None, endpoint: Optional[str] = None
    ) -> Dict[str, int]:
        """Get effective rate limits for a service/endpoint combination."""
        multiplier = self.service_multipliers.get(service, 1.0) if service else 1.0

        # Check for endpoint-specific overrides
        if endpoint and endpoint in self.endpoint_overrides:
            overrides = self.endpoint_overrides[endpoint]
            return {
                "requests_per_minute": int(
                    overrides.get("requests_per_minute", self.requests_per_minute)
                    * multiplier
                ),
                "requests_per_hour": int(
                    overrides.get("requests_per_hour", self.requests_per_hour)
                    * multiplier
                ),
                "requests_per_day": int(
                    overrides.get("requests_per_day", self.requests_per_day)
                    * multiplier
                ),
                "burst_size": int(
                    overrides.get("burst_size", self.burst_size) * multiplier
                ),
            }

        return {
            "requests_per_minute": int(self.requests_per_minute * multiplier),
            "requests_per_hour": int(self.requests_per_hour * multiplier),
            "requests_per_day": int(self.requests_per_day * multiplier),
            "burst_size": int(self.burst_size * multiplier),
        }

def _calculate_request_cost(self, endpoint: str, method: str) -> int:
        """Calculate the cost of a request based on endpoint and method."""
        # Base cost by method
        method_costs = {
            "GET": 1,
            "POST": 2,
            "PUT": 2,
            "PATCH": 1,
            "DELETE": 1,
        }

        base_cost = method_costs.get(method, 1)

        # Endpoint-specific cost multipliers
        high_cost_endpoints = {
            "/api/ai/chat": 3,
            "/api/ai/generate": 5,
            "/api/search/flights": 2,
            "/api/search/hotels": 2,
            "/api/bookings": 3,
        }

        for pattern, multiplier in high_cost_endpoints.items():
            if endpoint.startswith(pattern):
                return base_cost * multiplier

        return base_cost

def _create_rate_limit_response(
        self, result: RateLimitResult, context: Dict[str, Any]
    ) -> Response:
        """Create a comprehensive 429 response."""
        retry_after = result.retry_after_seconds

        # Create user-friendly error message
        if result.limit_type == "minute":
            message = (
                f"Rate limit exceeded: {result.limit_value} requests per minute "
                f"allowed. Try again in {retry_after} seconds."
            )
        elif result.limit_type == "hour":
            message = (
                f"Hourly rate limit exceeded: {result.limit_value} requests per hour "
                f"allowed. Resets in {retry_after // 60} minutes."
            )
        elif result.limit_type == "day":
            message = (
                f"Daily rate limit exceeded: {result.limit_value} requests per day "
                f"allowed. Resets in {retry_after // 3600} hours."
            )
        elif result.limit_type == "burst":
            message = (
                f"Burst limit exceeded. Please slow down your requests. "
                f"Try again in {retry_after} seconds."
            )
        else:
            message = f"Rate limit exceeded. Try again in {retry_after} seconds."

        # Create comprehensive headers (RFC 6585 compliant)
        headers = {
            "Retry-After": str(retry_after),
            "X-RateLimit-Limit": str(result.limit_value),
            "X-RateLimit-Remaining": "0",
            "X-RateLimit-Reset": str(int(result.reset_time.timestamp())),
            "X-RateLimit-Reset-After": str(retry_after),
            "X-RateLimit-Scope": result.limit_type,
            "X-RateLimit-Policy": f"{result.limit_value};w={result.limit_type}",
        }

        # Add algorithm-specific headers
        if result.algorithm == "token_bucket" and result.tokens_remaining is not None:
            headers["X-RateLimit-Tokens-Remaining"] = str(int(result.tokens_remaining))

        # Add service context if available
        if context.get("service"):
            headers["X-RateLimit-Service"] = context["service"]

        return Response(
            content=json.dumps(
                {
                    "error": "rate_limit_exceeded",
                    "message": message,
                    "retry_after": retry_after,
                    "limit": result.limit_value,
                    "scope": result.limit_type,
                    "reset_time": result.reset_time.isoformat(),
                }
            ),
            status_code=HTTP_429_TOO_MANY_REQUESTS,
            headers=headers,
            media_type="application/json",
        )

def _add_rate_limit_headers(
        self, response: Response, result: RateLimitResult, context: Dict[str, Any]
    ):
        """Add comprehensive rate limit headers to successful responses."""
        headers = {
            "X-RateLimit-Limit": str(result.limit_value),
            "X-RateLimit-Remaining": str(result.remaining),
            "X-RateLimit-Reset": str(int(result.reset_time.timestamp())),
            "X-RateLimit-Scope": result.limit_type,
            "X-RateLimit-Policy": f"{result.limit_value};w={result.limit_type}",
        }

        # Add algorithm-specific headers
        if result.algorithm == "token_bucket" and result.tokens_remaining is not None:
            headers["X-RateLimit-Tokens-Remaining"] = str(int(result.tokens_remaining))

        # Add service context if available
        if context.get("service"):
            headers["X-RateLimit-Service"] = context["service"]

        # Add cost information
        if context.get("cost", 1) > 1:
            headers["X-RateLimit-Cost"] = str(context["cost"])

        for key, value in headers.items():
            response.headers[key] = value

async def _track_successful_request(
        self,
        request: Request,
        context: Dict[str, Any],
        start_time: float,
        response: Response,
    ):
        """Track successful requests for monitoring and analytics."""
        if self.monitoring_service and context["principal_type"] != "unauthenticated":
            try:
                latency_ms = (time.time() - start_time) * 1000

                await self.monitoring_service.track_usage(
                    key_id=context["principal_id"],
                    user_id=context["principal_id"]
                    if context["principal_type"] == "user"
                    else "unknown",
                    service=context.get("service", "api"),
                    endpoint=context["endpoint"],
                    success=response.status_code < 400,
                    latency_ms=latency_ms,
                    error_code=str(response.status_code)
                    if response.status_code >= 400
                    else None,
                    error_message=None,
                    request_size=len(
                        await request.body() if hasattr(request, "body") else b""
                    ),
                    response_size=len(response.body)
                    if hasattr(response, "body")
                    else 0,
                    metadata={
                        "method": request.method,
                        "principal_type": context["principal_type"],
                        "tier": context.get("tier", "unknown"),
                        "cost": context["cost"],
                        "status_code": response.status_code,
                    },
                )
            except Exception as e:
                logger.debug(f"Failed to track successful request: {e}")

# Configuration helper functions
def create_rate_limit_config_from_dict(config_dict: Dict[str, Any]) -> RateLimitConfig:
    """Create a RateLimitConfig from a dictionary (useful for dynamic configuration)."""
    return RateLimitConfig(**config_dict)

def get_default_rate_limit_middleware(
    app: ASGIApp,
    settings: Optional[Settings] = None,
    use_dragonfly: Optional[bool] = None,
    monitoring_service=None,
) -> EnhancedRateLimitMiddleware:
    """Get a pre-configured rate limiting middleware with sensible defaults."""
    if settings is None:
        settings = get_settings()

    if use_dragonfly is None:
        use_dragonfly = settings.rate_limit_use_dragonfly

    return EnhancedRateLimitMiddleware(
        app=app,
        settings=settings,
        use_dragonfly=use_dragonfly,
        monitoring_service=monitoring_service,
    )

def validate_key_format(cls, v: str) -> str:
        """Basic key format validation."""
        if len(v.strip()) < 8:
            raise ValueError("API key must be at least 8 characters long")
        return v.strip()

def is_expired(self) -> bool:
        """Check if the key is expired."""
        if not self.expires_at:
            return False
        return datetime.now(timezone.utc) > self.expires_at

def expires_in_days(self) -> Optional[int]:
        """Days until expiration."""
        if not self.expires_at:
            return None
        delta = self.expires_at - datetime.now(timezone.utc)
        return max(0, delta.days)

def success_rate_category(self) -> str:
        """Categorize based on success."""
        return "success" if self.is_valid else "failure"

def is_healthy(self) -> bool:
        """Simple health check."""
        return self.status == ServiceHealthStatus.HEALTHY

async def check_service_health(self, service: ServiceType) -> ServiceHealthCheck:
        """
        Check the health of an external service.

        Args:
            service: The service to check

        Returns:
            Health check result
        """
        start_time = datetime.now(timezone.utc)

        try:
            if service == ServiceType.OPENAI:
                return await self._check_openai_health()
            elif service == ServiceType.WEATHER:
                return await self._check_weather_health()
            elif service == ServiceType.GOOGLEMAPS:
                return await self._check_googlemaps_health()
            else:
                return ServiceHealthCheck(
                    service=service,
                    status=ServiceHealthStatus.UNKNOWN,
                    latency_ms=0,
                    message="Health check not implemented for this service",
                )

        except Exception as e:
            latency_ms = (
                datetime.now(timezone.utc) - start_time
            ).total_seconds() * 1000

            return ServiceHealthCheck(
                service=service,
                status=ServiceHealthStatus.UNHEALTHY,
                latency_ms=latency_ms,
                message=f"Health check failed: {str(e)}",
                details={"error": str(e)},
            )

async def _validate_openai_key(self, key_value: str) -> ValidationResult:
        """Validate OpenAI API key."""
        if not key_value.startswith("sk-"):
            return ValidationResult(
                is_valid=False,
                status=ValidationStatus.FORMAT_ERROR,
                service=ServiceType.OPENAI,
                message="Invalid OpenAI key format (should start with 'sk-')",
            )

        try:
            response = await self.client.get(
                "https://api.openai.com/v1/models",
                headers={"Authorization": f"Bearer {key_value}"},
                timeout=self.validation_timeout,
            )

            if response.status_code == 200:
                data = response.json()
                models = [model["id"] for model in data.get("data", [])]

                # Capability detection
                capabilities = []
                if any("gpt-4" in model for model in models):
                    capabilities.append("gpt-4")
                if any("gpt-3.5" in model for model in models):
                    capabilities.append("gpt-3.5")
                if any("dall-e" in model for model in models):
                    capabilities.append("image-generation")

                return ValidationResult(
                    is_valid=True,
                    status=ValidationStatus.VALID,
                    service=ServiceType.OPENAI,
                    message="OpenAI API key is valid",
                    capabilities=capabilities,
                    details={
                        "models_available": len(models),
                        "sample_models": models[:5],
                    },
                )

            elif response.status_code == 401:
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.INVALID,
                    service=ServiceType.OPENAI,
                    message="Invalid API key - authentication failed",
                )

            elif response.status_code == 429:
                headers = response.headers
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.RATE_LIMITED,
                    service=ServiceType.OPENAI,
                    message="Rate limit exceeded",
                    rate_limit_info={
                        "retry_after": headers.get("retry-after"),
                        "limit": headers.get("x-ratelimit-limit"),
                        "remaining": headers.get("x-ratelimit-remaining"),
                        "reset": headers.get("x-ratelimit-reset"),
                    },
                )

            else:
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.SERVICE_ERROR,
                    service=ServiceType.OPENAI,
                    message=f"Unexpected response: {response.status_code}",
                    details={"status_code": response.status_code},
                )

        except httpx.TimeoutException:
            return ValidationResult(
                is_valid=False,
                status=ValidationStatus.SERVICE_ERROR,
                service=ServiceType.OPENAI,
                message="Validation request timed out",
            )

async def _validate_weather_key(self, key_value: str) -> ValidationResult:
        """Validate weather API key."""
        if len(key_value) < 16:
            return ValidationResult(
                is_valid=False,
                status=ValidationStatus.FORMAT_ERROR,
                service=ServiceType.WEATHER,
                message="Weather API key too short (minimum 16 characters)",
            )

        try:
            response = await self.client.get(
                "https://api.openweathermap.org/data/2.5/weather",
                params={"q": "London", "appid": key_value},
                timeout=self.validation_timeout,
            )

            if response.status_code == 200:
                data = response.json()

                # Extract quota information if available
                quota_info = {}
                if "X-RateLimit-Limit" in response.headers:
                    quota_info = {
                        "limit": response.headers.get("X-RateLimit-Limit"),
                        "remaining": response.headers.get("X-RateLimit-Remaining"),
                    }

                return ValidationResult(
                    is_valid=True,
                    status=ValidationStatus.VALID,
                    service=ServiceType.WEATHER,
                    message="Weather API key is valid",
                    quota_info=quota_info,
                    capabilities=["current", "forecast", "historical"],
                    details={
                        "api_version": "2.5",
                        "test_location": data.get("name"),
                    },
                )

            elif response.status_code == 401:
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.INVALID,
                    service=ServiceType.WEATHER,
                    message="Invalid API key",
                )

            elif response.status_code == 429:
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.RATE_LIMITED,
                    service=ServiceType.WEATHER,
                    message="API rate limit exceeded",
                )

            else:
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.SERVICE_ERROR,
                    service=ServiceType.WEATHER,
                    message=f"Unexpected response: {response.status_code}",
                )

        except httpx.TimeoutException:
            return ValidationResult(
                is_valid=False,
                status=ValidationStatus.SERVICE_ERROR,
                service=ServiceType.WEATHER,
                message="Validation request timed out",
            )

async def _validate_googlemaps_key(self, key_value: str) -> ValidationResult:
        """Validate Google Maps API key."""
        if len(key_value) < 20:
            return ValidationResult(
                is_valid=False,
                status=ValidationStatus.FORMAT_ERROR,
                service=ServiceType.GOOGLEMAPS,
                message="Google Maps API key too short",
            )

        try:
            response = await self.client.get(
                "https://maps.googleapis.com/maps/api/geocode/json",
                params={
                    "address": "1600 Amphitheatre Parkway, Mountain View, CA",
                    "key": key_value,
                },
                timeout=self.validation_timeout,
            )

            data = response.json()
            status = data.get("status", "")

            if status == "OK":
                # Capability checking
                capabilities = await self._check_googlemaps_capabilities(key_value)

                return ValidationResult(
                    is_valid=True,
                    status=ValidationStatus.VALID,
                    service=ServiceType.GOOGLEMAPS,
                    message="Google Maps API key is valid",
                    capabilities=capabilities,
                    details={
                        "apis_tested": ["geocoding"],
                        "status": status,
                    },
                )

            elif status == "REQUEST_DENIED":
                error_message = data.get("error_message", "API key is invalid")
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.INVALID,
                    service=ServiceType.GOOGLEMAPS,
                    message=f"Invalid API key: {error_message}",
                    details={"error": error_message},
                )

            elif status == "OVER_QUERY_LIMIT":
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.RATE_LIMITED,
                    service=ServiceType.GOOGLEMAPS,
                    message="Query limit exceeded",
                )

            else:
                return ValidationResult(
                    is_valid=False,
                    status=ValidationStatus.SERVICE_ERROR,
                    service=ServiceType.GOOGLEMAPS,
                    message=f"API returned status: {status}",
                    details={"status": status},
                )

        except httpx.TimeoutException:
            return ValidationResult(
                is_valid=False,
                status=ValidationStatus.SERVICE_ERROR,
                service=ServiceType.GOOGLEMAPS,
                message="Validation request timed out",
            )

async def _validate_flights_key(self, key_value: str) -> ValidationResult:
        """Validate flights API key (placeholder for specific implementation)."""
        return await self._validate_generic_key(ServiceType.FLIGHTS, key_value)

async def _validate_generic_key(
        self, service: ServiceType, key_value: str
    ) -> ValidationResult:
        """Generic validation for services without specific implementation."""
        if len(key_value) < 10:
            return ValidationResult(
                is_valid=False,
                status=ValidationStatus.FORMAT_ERROR,
                service=service,
                message="API key too short",
            )

        # Generic validation
        return ValidationResult(
            is_valid=True,
            status=ValidationStatus.VALID,
            service=service,
            message="API key accepted (generic validation)",
            details={"validation_type": "generic", "key_length": len(key_value)},
        )

async def _check_openai_health(self) -> ServiceHealthCheck:
        """Check OpenAI service health."""
        start_time = datetime.now(timezone.utc)

        try:
            response = await self.client.get(
                "https://status.openai.com/api/v2/status.json",
                timeout=5,  # Quick health check
            )

            latency_ms = (
                datetime.now(timezone.utc) - start_time
            ).total_seconds() * 1000

            if response.status_code == 200:
                data = response.json()
                status_indicator = data.get("status", {}).get("indicator", "none")

                if status_indicator == "none":
                    health_status = ServiceHealthStatus.HEALTHY
                elif status_indicator == "minor":
                    health_status = ServiceHealthStatus.DEGRADED
                else:
                    health_status = ServiceHealthStatus.UNHEALTHY

                return ServiceHealthCheck(
                    service=ServiceType.OPENAI,
                    status=health_status,
                    latency_ms=latency_ms,
                    message=data.get("status", {}).get("description", "Unknown"),
                    details={
                        "indicator": status_indicator,
                        "updated_at": data.get("page", {}).get("updated_at"),
                    },
                )
            else:
                return ServiceHealthCheck(
                    service=ServiceType.OPENAI,
                    status=ServiceHealthStatus.UNKNOWN,
                    latency_ms=latency_ms,
                    message=f"Status check returned {response.status_code}",
                )

        except Exception as e:
            latency_ms = (
                datetime.now(timezone.utc) - start_time
            ).total_seconds() * 1000

            return ServiceHealthCheck(
                service=ServiceType.OPENAI,
                status=ServiceHealthStatus.UNKNOWN,
                latency_ms=latency_ms,
                message=f"Health check error: {str(e)}",
            )

async def _check_weather_health(self) -> ServiceHealthCheck:
        """Check weather service health."""
        start_time = datetime.now(timezone.utc)

        try:
            response = await self.client.get(
                "https://api.openweathermap.org/data/2.5/weather",
                params={"q": "London", "appid": "invalid"},
                timeout=5,
            )

            latency_ms = (
                datetime.now(timezone.utc) - start_time
            ).total_seconds() * 1000

            # Service is healthy if it returns 401 (unauthorized) - means it's up
            if response.status_code in [200, 401]:
                return ServiceHealthCheck(
                    service=ServiceType.WEATHER,
                    status=ServiceHealthStatus.HEALTHY,
                    latency_ms=latency_ms,
                    message="Weather API is operational",
                )
            else:
                return ServiceHealthCheck(
                    service=ServiceType.WEATHER,
                    status=ServiceHealthStatus.DEGRADED,
                    latency_ms=latency_ms,
                    message=f"Unexpected status code: {response.status_code}",
                )

        except httpx.TimeoutException:
            latency_ms = (
                datetime.now(timezone.utc) - start_time
            ).total_seconds() * 1000

            return ServiceHealthCheck(
                service=ServiceType.WEATHER,
                status=ServiceHealthStatus.UNHEALTHY,
                latency_ms=latency_ms,
                message="Service timeout",
            )

async def _check_googlemaps_health(self) -> ServiceHealthCheck:
        """Check Google Maps service health."""
        start_time = datetime.now(timezone.utc)

        try:
            response = await self.client.get(
                "https://maps.googleapis.com/maps/api/geocode/json",
                params={"address": "test", "key": "invalid"},
                timeout=5,
            )

            latency_ms = (
                datetime.now(timezone.utc) - start_time
            ).total_seconds() * 1000

            # Service is healthy if it returns proper error response
            if response.status_code == 200:
                data = response.json()
                if data.get("status") in ["REQUEST_DENIED", "INVALID_REQUEST"]:
                    return ServiceHealthCheck(
                        service=ServiceType.GOOGLEMAPS,
                        status=ServiceHealthStatus.HEALTHY,
                        latency_ms=latency_ms,
                        message="Google Maps API is operational",
                    )

            return ServiceHealthCheck(
                service=ServiceType.GOOGLEMAPS,
                status=ServiceHealthStatus.DEGRADED,
                latency_ms=latency_ms,
                message="Service may be experiencing issues",
            )

        except httpx.TimeoutException:
            latency_ms = (
                datetime.now(timezone.utc) - start_time
            ).total_seconds() * 1000

            return ServiceHealthCheck(
                service=ServiceType.GOOGLEMAPS,
                status=ServiceHealthStatus.UNHEALTHY,
                latency_ms=latency_ms,
                message="Service timeout",
            )

async def _get_cached_validation(
        self, service: ServiceType, key_value: str
    ) -> Optional[ValidationResult]:
        """Get cached validation result if available."""
        if not self.cache:
            return None

        try:
            # Create secure cache key
            key_hash = hashlib.sha256(
                f"{service.value}:{key_value}".encode()
            ).hexdigest()
            cache_key = f"api_validation:v2:{key_hash}"

            cached_data = await self.cache.get(cache_key)
            if cached_data:
                data = json.loads(cached_data)
                return ValidationResult(**data)

        except Exception as e:
            logger.warning(f"Cache retrieval error: {e}")

        return None

async def _cache_validation_result(
        self, service: ServiceType, key_value: str, result: ValidationResult
    ) -> None:
        """Cache validation result with modern patterns."""
        if not self.cache:
            return

        try:
            key_hash = hashlib.sha256(
                f"{service.value}:{key_value}".encode()
            ).hexdigest()
            cache_key = f"api_validation:v2:{key_hash}"

            # Cache for 5 minutes with JSON serialization
            await self.cache.set(
                cache_key,
                json.dumps(result.model_dump(mode="json")),
                ex=300,
            )

        except Exception as e:
            logger.warning(f"Cache storage error: {e}")

def _db_result_to_response(self, result: Dict[str, Any]) -> ApiKeyResponse:
        """Convert database result to modern response model."""
        return ApiKeyResponse(
            id=result["id"],
            name=result["name"],
            service=ServiceType(result["service"]),
            description=result.get("description"),
            is_valid=result["is_valid"],
            created_at=datetime.fromisoformat(result["created_at"]),
            updated_at=datetime.fromisoformat(result["updated_at"]),
            expires_at=datetime.fromisoformat(result["expires_at"])
            if result.get("expires_at")
            else None,
            last_used=datetime.fromisoformat(result["last_used"])
            if result.get("last_used")
            else None,
            last_validated=datetime.fromisoformat(result["last_validated"])
            if result.get("last_validated")
            else None,
            usage_count=result["usage_count"],
        )

def worker() -> None:
        if not nfc:
            return
        try:
            with nfc.ContactlessFrontend("usb") as clf:
                tag = clf.connect(rdwr={"on-connect": lambda tag: False}, timeout=timeout)
                if tag and hasattr(tag, "identifier"):
                    uid_box["uid"] = tag.identifier.hex().upper()
        except Exception as exc:  # pragma: no cover - hardware errors
            print(f"RFID hardware error: {exc}")

def __eq__(self, other):
        if not isinstance(other, Symbol):
            return False
        return self.qname == other.qname and self.scope == other.scope

def push_scope(self, scope: Scope):
        """进入新作用域"""
        if self.scope_stack:
            scope.parent = self.scope_stack[-1]
        self.scope_stack.append(scope)

def pop_scope(self):
        """退出当前作用域"""
        return self.scope_stack.pop()

def current_scope(self) -> Optional[Scope]:
        """获取当前作用域"""
        return self.scope_stack[-1] if self.scope_stack else None

def resolve_name(self, name: str, from_scope: Optional[Scope] = None) -> Optional[Symbol]:
        """从作用域栈解析名称（LEGB规则）"""
        scope = from_scope or self.current_scope()

        # 检查是否有 nonlocal 或 global 声明
        if scope:
            if name in scope.nonlocal_vars:
                # nonlocal 变量 - 跳过当前作用域，从父作用域开始查找
                scope = scope.parent
            elif name in scope.global_vars:
                # global 变量 - 直接跳到模块作用域
                while scope and scope.scope_type != 'module':
                    scope = scope.parent

        # 正常的LEGB查找
        while scope:
            if name in scope.symbols:
                return scope.symbols[name]
            scope = scope.parent

        return None

def get_module_qname(self, module_path: Path) -> str:
        """获取模块的限定名"""
        try:
            rel_path = module_path.relative_to(self.project_root)
            parts = list(rel_path.parts[:-1]) + [rel_path.stem]
            if parts[-1] == '__init__':
                parts = parts[:-1]
            return '.'.join(parts)
        except ValueError:
            return module_path.stem

def resolve_relative_import(self, level: int, module: Optional[str], 
                              current_file: Path) -> Optional[Path]:
        """解析相对导入"""
        if level == 0:
            # 绝对导入
            return self.resolve_module_path(module if module else '')

        # 相对导入
        current_package = current_file.parent

        # 向上移动 level-1 次
        for _ in range(level - 1):
            current_package = current_package.parent
            if not current_package.is_relative_to(self.project_root):
                return None

        if module:
            # from ..module import something
            return self.resolve_module_path(module, current_package)
        else:
            # from .. import something
            return current_package / '__init__.py'

def is_internal_module(self, module_name: str, current_file: Path, level: int = 0) -> bool:
        """判断是否为内部模块"""
        if level > 0:
            # 相对导入总是内部的
            return True

        module_path = self.resolve_module_path(module_name)
        if module_path and module_path.is_relative_to(self.project_root):
            return True

        return False

def visit_ImportFrom(self, node: ast.ImportFrom):
        """处理 from ... import ... 语句"""
        # 检查是否是 __future__ 导入
        if node.module == '__future__':
            for alias in node.names:
                self.future_imports.add(f"from __future__ import {alias.name}")
            return

        # 检查通配符导入
        if any(alias.name == '*' for alias in node.names):
            raise UnsupportedFeatureError(
                f"Wildcard imports ('from ... import *') are not supported in {self.current_module_path}"
            )

        level = node.level or 0
        module_name = node.module or ''

        # 解析模块路径
        if level > 0:
            # 相对导入
            module_path = self.resolve_relative_import(level, module_name, self.current_module_path)
        else:
            # 绝对导入
            module_path = self.resolve_module_path(module_name)

        if module_path and self.is_internal_module(module_name, self.current_module_path, level):
            # 内部模块
            self.analyze_module(module_path)

            for alias in node.names:
                symbol_name = alias.name
                alias_name = alias.asname or symbol_name

                # 创建导入别名符号
                symbol = Symbol(
                    name=alias_name,
                    qname=f"{self.get_module_qname(self.current_module_path)}.{alias_name}",
                    symbol_type='import_alias', 
                    def_node=node,
                    scope=self.current_scope()
                )

                # 找到被导入的原始符号
                target_qname = f"{self.get_module_qname(module_path)}.{symbol_name}"
                if target_qname in self.all_symbols:
                    symbol.dependencies.add(self.all_symbols[target_qname])

                self.current_scope().symbols[alias_name] = symbol
                self.all_symbols[symbol.qname] = symbol
                self.module_symbols[self.current_module_path][alias_name] = symbol
        else:
            # 外部导入
            for alias in node.names:
                if alias.asname:
                    self.external_imports.add(
                        f"from {module_name} import {alias.name} as {alias.asname}"
                    )
                else:
                    self.external_imports.add(
                        f"from {module_name} import {alias.name}"
                    )

def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef):
        """处理异步函数定义"""
        self.visit_FunctionDef(node)

def visit_AsyncFor(self, node: ast.AsyncFor):
        """处理异步 for 循环"""
        self.visit_For(node)

def visit_With(self, node: Union[ast.With, ast.AsyncWith]):
        """处理 with 语句"""
        for item in node.items:
            if item.optional_vars and isinstance(item.optional_vars, ast.Name):
                with_var = Symbol(
                    name=item.optional_vars.id,
                    qname=f"{self.get_current_qname()}.{item.optional_vars.id}",
                    symbol_type='variable',
                    def_node=item.optional_vars,
                    scope=self.current_scope()
                )
                self.current_scope().symbols[item.optional_vars.id] = with_var

        self.generic_visit(node)

def visit_AsyncWith(self, node: ast.AsyncWith):
        """处理异步 with 语句"""
        self.visit_With(node)

def visit_ListComp(self, node: ast.ListComp):
        """处理列表推导式"""
        self._visit_comprehension(node)

def visit_SetComp(self, node: ast.SetComp):
        """处理集合推导式"""
        self._visit_comprehension(node)

def visit_DictComp(self, node: ast.DictComp):
        """处理字典推导式"""
        self._visit_comprehension(node)

def visit_GeneratorExp(self, node: ast.GeneratorExp):
        """处理生成器表达式"""
        self._visit_comprehension(node)

def get_current_qname(self) -> str:
        """获取当前作用域的限定名"""
        if self.current_scope().scope_type == 'module':
            return self.get_module_qname(self.current_module_path)

        # 查找当前作用域对应的符号
        for symbol in self.all_symbols.values():
            if symbol.def_node == self.current_scope().node:
                return symbol.qname

        return ""

def analyze_dependencies(self, node: ast.AST, parent_scope: Optional[Scope] = None) -> Set[Symbol]:
        """分析AST节点的依赖，使用作用域栈"""
        if parent_scope:
            # 临时推入父作用域以便正确解析名称
            original_stack_size = len(self.scope_stack)
            self.push_scope(parent_scope)

        dependencies = set()

        # 使用一个访问器来正确处理作用域
        class LocalDependencyAnalyzer(ast.NodeVisitor):
            def __init__(self, outer):
                self.outer = outer
                self.deps = set()

            def visit_Name(self, node):
                if isinstance(node.ctx, ast.Load):
                    symbol = self.outer.resolve_name(node.id)
                    if symbol and symbol.symbol_type not in ('parameter', 'loop_var', 'local_var'):
                        self.deps.add(symbol)

            def visit_Attribute(self, node):
                # 处理属性访问
                if isinstance(node.value, ast.Name):
                    symbol = self.outer.resolve_name(node.value.id)
                    if symbol and symbol.symbol_type not in ('parameter', 'loop_var', 'local_var'):
                        self.deps.add(symbol)
                self.generic_visit(node)

            def visit_FunctionDef(self, node):
                # 不进入嵌套函数定义
                pass

            def visit_AsyncFunctionDef(self, node):
                # 不进入嵌套异步函数定义
                pass

            def visit_ClassDef(self, node):
                # 不进入嵌套类定义
                pass

        analyzer = LocalDependencyAnalyzer(self)
        analyzer.visit(node)
        dependencies = analyzer.deps

        if parent_scope:
            # 恢复原始作用域栈
            while len(self.scope_stack) > original_stack_size:
                self.pop_scope()

        return dependencies

def __init__(self, outer):
                self.outer = outer
                self.deps = set()

def visit_Name(self, node):
                if isinstance(node.ctx, ast.Load):
                    symbol = self.outer.resolve_name(node.id)
                    if symbol and symbol.symbol_type not in ('parameter', 'loop_var', 'local_var'):
                        self.deps.add(symbol)

def visit_Attribute(self, node):
                # 处理属性访问
                if isinstance(node.value, ast.Name):
                    symbol = self.outer.resolve_name(node.value.id)
                    if symbol and symbol.symbol_type not in ('parameter', 'loop_var', 'local_var'):
                        self.deps.add(symbol)
                self.generic_visit(node)

def visit_FunctionDef(self, node):
                # 不进入嵌套函数定义
                pass

def visit_AsyncFunctionDef(self, node):
                # 不进入嵌套异步函数定义
                pass

def visit_ClassDef(self, node):
                # 不进入嵌套类定义
                pass

def visit_Nonlocal(self, node: ast.Nonlocal):
        """处理nonlocal声明"""
        current = self.current_scope()
        if current and current.scope_type == 'function':
            for name in node.names:
                current.nonlocal_vars.add(name)
        return node

def visit_Global(self, node: ast.Global):
        """处理global声明"""
        current = self.current_scope()
        if current:
            for name in node.names:
                current.global_vars.add(name)
        return node

def analyze_entry_script(self, script_path: Path) -> Tuple[Set[Symbol], List[ast.AST]]:
        """分析入口脚本，返回初始符号集和主代码"""
        self.visitor.analyze_module(script_path)

        initial_symbols = set()
        main_code = []

        with open(script_path, 'r', encoding='utf-8') as f:
            content = f.read()

        tree = ast.parse(content, filename=str(script_path))

        # 分析入口脚本的每个语句
        for node in tree.body:
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                # 导入语句 - 收集导入的符号
                if isinstance(node, ast.ImportFrom) and node.module == '__future__':
                    continue  # __future__ 导入已经被收集

                # 直接从作用域中查找导入创建的符号
                module_qname = self.visitor.get_module_qname(script_path)
                module_scope = None
                for scope in self.visitor.scope_stack:
                    if scope.module_path == script_path:
                        module_scope = scope
                        break

                if not module_scope:
                    # 从保存的模块作用域中查找
                    if script_path in self.visitor.module_symbols:
                        module_scope = self.visitor.module_symbols[script_path].get('__scope__')

                if module_scope:
                    # 查找导入创建的别名符号
                    if isinstance(node, ast.ImportFrom):
                        for alias in node.names:
                            alias_name = alias.asname or alias.name
                            if alias_name in module_scope.symbols:
                                initial_symbols.add(module_scope.symbols[alias_name])
                    elif isinstance(node, ast.Import):
                        for alias in node.names:
                            alias_name = alias.asname or alias.name.split('.')[-1]
                            if alias_name in module_scope.symbols:
                                initial_symbols.add(module_scope.symbols[alias_name])
            else:
                # 其他语句 - 分析其中使用的符号
                main_code.append(node)

                # 收集主代码中引用的符号
                deps = self.visitor.analyze_dependencies(node)
                initial_symbols.update(deps)

        return initial_symbols, main_code

def collect_all_dependencies(self, initial_symbols: Set[Symbol]) -> Set[Symbol]:
        """递归收集所有依赖"""
        needed = set()
        to_process = deque(initial_symbols)

        while to_process:
            symbol = to_process.popleft()
            if symbol in needed:
                continue

            needed.add(symbol)

            # 添加符号的所有依赖
            for dep in symbol.dependencies:
                if dep not in needed:
                    to_process.append(dep)

            # 如果是导入别名，添加目标符号
            if symbol.symbol_type == 'import_alias' and symbol.dependencies:
                for dep in symbol.dependencies:
                    if dep not in needed:
                        to_process.append(dep)

        return needed

def topological_sort(self, symbols: Set[Symbol]) -> List[Symbol]:
        """拓扑排序"""
        # 构建依赖图
        graph = defaultdict(set)
        in_degree = defaultdict(int)

        for symbol in symbols:
            in_degree[symbol] = 0

        for symbol in symbols:
            for dep in symbol.dependencies:
                if dep in symbols:
                    graph[dep].add(symbol)
                    in_degree[symbol] += 1

        # 拓扑排序
        queue = deque([s for s in symbols if in_degree[s] == 0])
        sorted_symbols = []

        while queue:
            current = queue.popleft()
            sorted_symbols.append(current)

            for dependent in graph[current]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)

        # 检查循环依赖
        if len(sorted_symbols) != len(symbols):
            remaining = symbols - set(sorted_symbols)
            raise CircularDependencyError(
                f"Circular dependency detected among symbols: "
                f"{', '.join(s.qname for s in remaining)}"
            )

        return sorted_symbols

def generate_name_mappings(self, symbols: Set[Symbol]):
        """生成名称映射"""
        # 统计名称冲突
        name_counts = defaultdict(int)
        for symbol in symbols:
            if symbol.symbol_type != 'import_alias':
                name_counts[symbol.name] += 1

        # 生成映射
        for symbol in symbols:
            if symbol.symbol_type == 'import_alias':
                # 导入别名保持不变
                continue

            if name_counts[symbol.name] > 1:
                # 有冲突，需要重命名
                module_key = self.visitor.get_module_qname(symbol.scope.module_path)
                module_key = module_key.replace('.', '_').replace('__init__', 'pkg')
                new_name = f"{module_key}_{symbol.name}"
                self.name_mappings[symbol.qname] = new_name
            else:
                # 无冲突，保持原名
                self.name_mappings[symbol.qname] = symbol.name

def transform_symbol(self, symbol: Symbol) -> ast.AST:
        """转换符号定义"""
        node = copy.deepcopy(symbol.def_node)

        # 跳过模块文档字符串
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
            return None

        # 跳过参数节点（不应该作为独立符号）
        if isinstance(node, ast.arg):
            return None

        # 跳过单独的名称节点
        if isinstance(node, ast.Name):
            return None

        # 设置当前作用域栈
        self.current_scope_stack = [symbol.scope]

        # 转换节点
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            return self.transform_function(node, symbol)
        elif isinstance(node, ast.ClassDef):
            return self.transform_class(node, symbol)
        elif isinstance(node, (ast.Assign, ast.AnnAssign)):
            # 特殊处理 __all__
            if isinstance(node, ast.Assign) and symbol.export_list:
                return self.transform_all_assignment(node, symbol)
            return self.visit(node)
        else:
            # 其他类型的符号，跳过
            return None

def get_current_module_path(self) -> Optional[Path]:
        """获取当前模块路径"""
        if self.current_scope_stack:
            return self.current_scope_stack[0].module_path
        return None

def current_module_path(self) -> Optional[Path]:
        """获取当前模块路径 - 兼容原始代码"""
        return self.get_current_module_path()

def find_symbol_qname(self, name: str) -> Optional[str]:
        """查找符号的限定名 - 保留用于向后兼容"""
        symbol = self.resolve_name_to_symbol(name)
        if symbol:
            if symbol.symbol_type == 'import_alias' and symbol.dependencies:
                # 返回导入指向的真实符号的qname
                for dep in symbol.dependencies:
                    return dep.qname
            return symbol.qname
        return None

def transform_all_assignment(self, node: ast.Assign, symbol: Symbol) -> ast.AST:
        """转换 __all__ 赋值，更新导出列表中的名称"""
        # 深拷贝节点
        new_node = copy.deepcopy(node)

        # 如果值是列表或元组，更新其中的字符串
        if isinstance(new_node.value, (ast.List, ast.Tuple)):
            new_elts = []
            for elt in new_node.value.elts:
                if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                    old_name = elt.value
                    # 查找这个名称对应的符号
                    for sym in self.all_symbols.values():
                        if sym.name == old_name and sym.scope.module_path == self.current_module_path:
                            if sym.qname in self.name_mappings:
                                # 使用新名称
                                new_elt = ast.Constant(value=self.name_mappings[sym.qname])
                                new_elts.append(new_elt)
                                break
                    else:
                        # 保持原名称
                        new_elts.append(elt)
                else:
                    new_elts.append(elt)
            new_node.value.elts = new_elts

        return new_node

def visit_Name(self, node: ast.Name):
        """转换名称引用"""
        if isinstance(node.ctx, ast.Load):
            # 查找符号的限定名
            qname = self.find_symbol_qname(node.id)
            if qname and qname in self.name_mappings:
                node.id = self.name_mappings[qname]
        return node

def visit_Attribute(self, node: ast.Attribute) -> ast.AST:
        """转换属性访问"""
        # 递归解析属性链，直到找到最左侧的根符号
        # 例如，对于 a.b.c，我们先解析 a
        # 这是一个简化的实现，只处理单层 a.b

        # 1. 解析 node.value (例如 global_same_a)
        if not isinstance(node.value, ast.Name):
            # 无法处理更复杂的情况，如 (get_obj()).attr，先保持原样
            return self.generic_visit(node)

        base_name = node.value.id
        # 2. 找到基名对应的符号 (global_same_a -> import_alias 符号)
        base_symbol = self.resolve_name_to_symbol(base_name)

        if not base_symbol:
            # 基名无法解析，保持原样
            return self.generic_visit(node)

        # 3. 找到别名指向的真实符号 (import_alias -> module 符号)
        # 这需要确保在分析阶段，import_alias 的依赖被正确设置
        target_symbol = None
        if base_symbol.symbol_type == 'import_alias':
            # 假设别名只有一个依赖，即其指向的模块或符号
            if base_symbol.dependencies:
                target_symbol = next(iter(base_symbol.dependencies))
        else:
            # 如果基名不是别名，而是普通变量，它可能是一个对象实例
            # 暂时不处理这种情况，但这是未来扩展的方向
            target_symbol = base_symbol

        if not target_symbol:
            return self.generic_visit(node)

        # 4. 在真实符号的作用域中查找属性 (在 module 'a_pkg.a' 中查找 'hello2')
        # 这要求 target_symbol 必须有一个指向其作用域的链接
        if target_symbol.scope and node.attr in target_symbol.scope.symbols:
            final_symbol = target_symbol.scope.symbols[node.attr]

            # 5. 获取最终符号的重命名
            if final_symbol.qname in self.name_mappings:
                new_name = self.name_mappings[final_symbol.qname]
                # 6. 将整个 ast.Attribute 节点替换为ast.Name节点
                return ast.Name(id=new_name, ctx=node.ctx)

        # 如果以上步骤失败，保持原样
        return self.generic_visit(node)

def visit_Global(self, node: ast.Global):
        """转换global声明"""
        # Global声明的名称通常不需要转换，因为它们引用的是模块级名称
        # 但我们仍然需要检查是否有映射
        new_names = []
        current_module = self.get_current_module_path()
        if current_module:
            for name in node.names:
                # 查找模块级符号
                module_qname = self.visitor.get_module_qname(current_module)
                symbol_qname = f"{module_qname}.{name}"
                if symbol_qname in self.name_mappings:
                    new_names.append(self.name_mappings[symbol_qname])
                else:
                    new_names.append(name)
        else:
            new_names = node.names
        node.names = new_names
        return node

