    /**
     * 파일이 더 최신인지 확인
     */
private boolean isFileNewer(Path file1, Path file2) {
        try {
            var time1 = Files.getLastModifiedTime(file1);
            var time2 = Files.getLastModifiedTime(file2);
            return time1.compareTo(time2) >= 0;
        } catch (IOException e) {
            log.warn("파일 수정 시간 비교 실패", e);
            return false;
        }
    }

