override fun doFilterInternal(
        request: HttpServletRequest,
        response: HttpServletResponse,
        filterChain: FilterChain
    ) {
        val jwt = getJwtFromRequest(request)

        if (StringUtils.hasText(jwt) && jwtTokenProvider.validateToken(jwt!!)) {
            val email = jwtTokenProvider.getEmailFromToken(jwt)
            val userDetails = userDetailsService.loadUserByUsername(email)

            val authentication = UsernamePasswordAuthenticationToken(
                userDetails, null, userDetails.authorities
            )
            authentication.details = WebAuthenticationDetailsSource().buildDetails(request)

            SecurityContextHolder.getContext().authentication = authentication
        }

        filterChain.doFilter(request, response)
    }

private fun getJwtFromRequest(request: HttpServletRequest): String? {
        val bearerToken = request.getHeader("Authorization")
        return if (StringUtils.hasText(bearerToken) && bearerToken.startsWith("Bearer ")) {
            bearerToken.substring(7)
        } else null
    }

private fun getSigningKey(): Key {
        return Keys.hmacShaKeyFor(jwtSecret.toByteArray())
    }

fun generateToken(email: String): String {
        val now = Date()
        val expiryDate = Date(now.time + jwtExpirationInMs)

        return Jwts.builder()
            .setSubject(email)
            .setIssuedAt(now)
            .setExpiration(expiryDate)
            .signWith(getSigningKey(), SignatureAlgorithm.HS512)
            .compact()
    }

fun validateToken(token: String): Boolean {
        try {
            Jwts.parserBuilder()
                .setSigningKey(getSigningKey())
                .build()
                .parseClaimsJws(token)
            return true
        } catch (ex: SecurityException) {
            // Invalid JWT signature
        } catch (ex: MalformedJwtException) {
            // Invalid JWT token
        } catch (ex: ExpiredJwtException) {
            // Expired JWT token
        } catch (ex: UnsupportedJwtException) {
            // Unsupported JWT token
        } catch (ex: IllegalArgumentException) {
            // JWT claims string is empty
        }
        return false
    }

override fun loadUserByUsername(email: String): UserDetails {
        val user = userRepository.findByEmail(email)
            .orElseThrow { UsernameNotFoundException("Usuário não encontrado com email: $email") }

        if (!user.active) {
            throw UsernameNotFoundException("Usuário inativo: $email")
        }

        return User.builder()
            .username(user.email)
            .password(user.passwordHash)
            .authorities("ROLE_USER")
            .accountExpired(false)
            .accountLocked(false)
            .credentialsExpired(false)
            .disabled(!user.active)
            .build()
    }

fun createUser(request: CreateUserRequest): UserResponse {
        if (userRepository.existsByEmail(request.email)) {
            throw IllegalArgumentException("Email já está em uso")
        }

        if (userRepository.existsByCpf(request.cpf)) {
            throw IllegalArgumentException("CPF já está cadastrado")
        }

        val user = User(
            email = request.email,
            passwordHash = passwordEncoder.encode(request.password),
            firstName = request.firstName,
            lastName = request.lastName,
            cpf = request.cpf,
            phone = request.phone
        )

        val savedUser = userRepository.save(user)
        return mapToUserResponse(savedUser)
    }

fun authenticateUser(request: LoginRequest): LoginResponse {
        val user = userRepository.findByEmail(request.email)
            .orElseThrow { IllegalArgumentException("Credenciais inválidas") }

        if (!user.active) {
            throw IllegalArgumentException("Usuário inativo")
        }

        if (!passwordEncoder.matches(request.password, user.passwordHash)) {
            throw IllegalArgumentException("Credenciais inválidas")
        }

        val token = jwtTokenProvider.generateToken(user.email)
        return LoginResponse(
            token = token,
            user = mapToUserResponse(user)
        )
    }

@Transactional(readOnly = true)
    fun getUserById(id: Long): UserResponse {
        val user = userRepository.findActiveUserById(id)
            .orElseThrow { NoSuchElementException("Usuário não encontrado") }
        return mapToUserResponse(user)
    }

@Transactional(readOnly = true)
    fun getUserByEmail(email: String): UserResponse {
        val user = userRepository.findByEmail(email)
            .orElseThrow { NoSuchElementException("Usuário não encontrado") }
        return mapToUserResponse(user)
    }

@Transactional(readOnly = true)
    fun getAllUsers(): List<UserResponse> {
        return userRepository.findAllActiveUsers()
            .map { mapToUserResponse(it) }
    }

fun updateUser(id: Long, request: UpdateUserRequest): UserResponse {
        val user = userRepository.findActiveUserById(id)
            .orElseThrow { NoSuchElementException("Usuário não encontrado") }

        val updatedUser = user.copy(
            firstName = request.firstName,
            lastName = request.lastName,
            phone = request.phone
        )

        val savedUser = userRepository.save(updatedUser)
        return mapToUserResponse(savedUser)
    }

fun changePassword(id: Long, request: ChangePasswordRequest) {
        val user = userRepository.findActiveUserById(id)
            .orElseThrow { NoSuchElementException("Usuário não encontrado") }

        if (!passwordEncoder.matches(request.currentPassword, user.passwordHash)) {
            throw IllegalArgumentException("Senha atual incorreta")
        }

        user.passwordHash = passwordEncoder.encode(request.newPassword)
        userRepository.save(user)
    }

fun deactivateUser(id: Long) {
        val user = userRepository.findActiveUserById(id)
            .orElseThrow { NoSuchElementException("Usuário não encontrado") }

        val deactivatedUser = user.copy(active = false)
        userRepository.save(deactivatedUser)
    }

// Initialize mini-map functionality
function initializeMiniMap() {
    const miniMapToggle = document.getElementById('miniMapToggle');
    const centerMapBtn = document.getElementById('centerMapBtn');
    const toggleAttractionsBtn = document.getElementById('toggleAttractionsBtn');

    if (miniMapToggle) {
        miniMapToggle.addEventListener('click', toggleMiniMap);
    }

    if (centerMapBtn) {
        centerMapBtn.addEventListener('click', centerMiniMapOnLocation);
    }

    if (toggleAttractionsBtn) {
        toggleAttractionsBtn.addEventListener('click', toggleAttractionMarkers);
    }
}

// Toggle mini-map visibility
function toggleMiniMap() {
    const miniMapContainer = document.getElementById('miniMapContainer');
    const miniMapToggle = document.getElementById('miniMapToggle');
    const miniMapSection = document.getElementById('miniMapSection');

    miniMapVisible = !miniMapVisible;

    if (miniMapVisible) {
        miniMapContainer.classList.remove('collapsed');
        miniMapToggle.textContent = '📍 Hide Map';
        miniMapToggle.classList.add('active');
        miniMapSection.classList.add('active');

        // Initialize map if not already done
        if (!miniMap) {
            setTimeout(() => {
                initializeLeafletMap();
            }, 300); // Wait for container to expand
        } else {
            // Invalidate size to handle container resize
            setTimeout(() => {
                miniMap.invalidateSize();
            }, 300);
        }

        // Announce to screen readers
        announceToScreenReader('Mini-map opened. Use arrow keys to navigate the map.');
    } else {
        miniMapContainer.classList.add('collapsed');
        miniMapToggle.textContent = '📍 Show Map';
        miniMapToggle.classList.remove('active');

        // Announce to screen readers
        announceToScreenReader('Mini-map closed.');
    }
}

