    /// <summary>
    /// Generates a comprehensive Markdown report from architecture metrics.
    /// </summary>
public string GenerateMarkdownReport(ArchitectureMetrics metrics)
    {
        var sb = new StringBuilder();

        // Header
        sb.AppendLine("# Progressive Complexity Health Report");
        sb.AppendLine();
        sb.AppendLine($"*Last updated: {metrics.Timestamp:MMMM d, yyyy 'at' HH:mm} UTC*");
        sb.AppendLine();

        // Overall health summary
        var healthIcon = GetHealthIcon(metrics.OverallHealth);
        sb.AppendLine($"## Overall Architecture Health: {metrics.OverallHealth:F0}% {healthIcon}");
        sb.AppendLine();

        // Health explanation
        AppendHealthExplanation(sb, metrics.OverallHealth);
        sb.AppendLine();

        // Module breakdown
        sb.AppendLine("## Module Breakdown");
        sb.AppendLine();

        var modulesByHealth = metrics.Modules
            .OrderByDescending(m => m.FacadeCoverage)
            .ThenByDescending(m => m.ServiceCoverage);

        foreach (var module in modulesByHealth)
        {
            AppendModuleSection(sb, module);
        }

        // Summary recommendations
        AppendGlobalRecommendations(sb, metrics);

        return sb.ToString();
    }

    /// <summary>
    /// Appends a detailed section for a specific module.
    /// </summary>
private static void AppendModuleSection(StringBuilder sb, ModuleMetrics module)
    {
        var healthIcon = GetModuleHealthIcon(module.Health);
        var facadeIcon = GetCoverageIcon(module.FacadeCoverage);
        var serviceIcon = GetCoverageIcon(module.ServiceCoverage);

        sb.AppendLine($"### {GetModuleEmoji(module.Name)} {module.Name} System - {module.FacadeCoverage:F0}% {healthIcon} {module.Health.ToTitleCase()}");
        sb.AppendLine();

        // Coverage metrics
        sb.AppendLine("**Coverage Metrics:**");
        sb.AppendLine($"- **Facade Coverage**: {module.FacadeCoverage:F0}% {facadeIcon} ({GetCoverageDescription(module.FacadeCoverage)})");
        sb.AppendLine($"- **Service Coverage**: {module.ServiceCoverage:F0}% {serviceIcon} ({GetCoverageDescription(module.ServiceCoverage)})");
        sb.AppendLine();

        // Architecture details
        sb.AppendLine("**Architecture Details:**");
        sb.AppendLine($"- **Service Interface**: `{module.ServiceInterface}`");
        sb.AppendLine($"- **Implementation**: `{module.Implementation}`");
        sb.AppendLine($"- **Facade Access**: {module.Facade}");
        sb.AppendLine();

        // Opportunities
        if (module.Opportunities.Count > 0)
        {
            sb.AppendLine("**Improvement Opportunities:**");
            foreach (var opportunity in module.Opportunities)
            {
                sb.AppendLine($"- {opportunity}");
            }
            sb.AppendLine();
        }

        // Priority assessment
        AppendPriorityAssessment(sb, module);
        sb.AppendLine();
    }

    /// <summary>
    /// Appends a priority assessment for the module.
    /// </summary>
private static void AppendPriorityAssessment(StringBuilder sb, ModuleMetrics module)
    {
        var priority = DeterminePriority(module);
        var priorityIcon = priority switch
        {
            "High" => "🔥",
            "Medium" => "⚠️",
            "Low" => "✅",
            _ => "ℹ️"
        };

        sb.AppendLine($"**Priority**: {priorityIcon} {priority} - {GetPriorityReason(module, priority)}");
    }

    /// <summary>
    /// Appends global recommendations based on overall metrics.
    /// </summary>
private static void AppendGlobalRecommendations(StringBuilder sb, ArchitectureMetrics metrics)
    {
        sb.AppendLine("## Architecture Recommendations");
        sb.AppendLine();

        var criticalModules = metrics.Modules.Where(m => m.FacadeCoverage < 30).ToList();
        var goodModules = metrics.Modules.Where(m => m.FacadeCoverage >= 70).ToList();

        if (criticalModules.Count > 0)
        {
            sb.AppendLine("### 🚨 Critical Actions Needed");
            sb.AppendLine();
            foreach (var module in criticalModules)
            {
                sb.AppendLine($"- **{module.Name}**: Create facade layer for beginner accessibility");
            }
            sb.AppendLine();
        }

        if (goodModules.Count > 0)
        {
            sb.AppendLine("### ✅ Well-Architected Systems");
            sb.AppendLine();
            sb.AppendLine("These systems demonstrate good Progressive Complexity patterns:");
            foreach (var module in goodModules)
            {
                sb.AppendLine($"- **{module.Name}**: Excellent facade coverage ({module.FacadeCoverage:F0}%)");
            }
            sb.AppendLine();
        }

        // Educational impact
        sb.AppendLine("### 📚 Educational Impact");
        sb.AppendLine();
        var learnerFriendlyPercent = (double)goodModules.Count / metrics.Modules.Count * 100;
        sb.AppendLine($"Currently **{learnerFriendlyPercent:F0}%** of RACEngine systems are beginner-friendly.");
        sb.AppendLine();

        if (learnerFriendlyPercent < 70)
        {
            sb.AppendLine("**Recommendation**: Focus on facade layer development to improve learning curve.");
            sb.AppendLine("Beginner developers should be able to accomplish common tasks through simple facade methods.");
        }
        else
        {
            sb.AppendLine("**Status**: Good progress on educational accessibility! Continue maintaining facade coverage.");
        }
    }

    /// <summary>
    /// Appends explanation of current health status.
    /// </summary>
private static void AppendHealthExplanation(StringBuilder sb, double overallHealth)
    {
        string explanation = overallHealth switch
        {
            >= 80 => "**Excellent**: RACEngine demonstrates strong Progressive Complexity patterns with comprehensive facade coverage.",
            >= 60 => "**Good**: Most systems follow Progressive Complexity principles with room for facade improvements.",
            >= 40 => "**Needs Improvement**: Several systems lack beginner-friendly facade layers.",
            _ => "**Critical**: Significant facade coverage gaps impact educational accessibility."
        };

        sb.AppendLine(explanation);
    }

private static string GetModuleHealthIcon(string health) => health switch
    {
        "excellent" => "🎯",
        "good" => "✅",
        "needs-improvement" => "⚠️",
        "critical" => "❌",
        _ => "ℹ️"
    };

private static string GetCoverageIcon(double coverage) => coverage switch
    {
        >= 70 => "🟢",
        >= 50 => "🟡",
        >= 30 => "🟠", 
        _ => "🔴"
    };

private static string GetCoverageDescription(double coverage) => coverage switch
    {
        >= 70 => "excellent coverage",
        >= 50 => "good coverage",
        >= 30 => "needs improvement",
        _ => "critical gaps"
    };

private static string DeterminePriority(ModuleMetrics module)
    {
        if (module.FacadeCoverage < 30) return "High";
        if (module.FacadeCoverage < 50) return "Medium";
        return "Low";
    }

private static string GetPriorityReason(ModuleMetrics module, string priority) => priority switch
    {
        "High" => "Critical facade coverage gap impacts beginner accessibility",
        "Medium" => "Moderate improvements needed for better discoverability",
        "Low" => "System shows good Progressive Complexity patterns",
        _ => "Monitoring recommended"
    };

public static string ToTitleCase(this string input)
    {
        if (string.IsNullOrEmpty(input)) return input;

        var words = input.Split('-', '_', ' ');
        return string.Join(" ", words.Select(word => 
            char.ToUpper(word[0]) + word.Substring(1).ToLower()));
    }

    /// <summary>
    /// Calculates architecture metrics for all detected service patterns.
    /// </summary>
    /// <param name="patterns">Detected service patterns from code analysis</param>
    /// <returns>Complete architecture metrics with per-module coverage</returns>
public ArchitectureMetrics CalculateMetrics(IReadOnlyList<ServicePattern> patterns)
    {
        var modules = patterns.Select(CalculateModuleMetrics).ToList();
        var overallHealth = CalculateOverallHealth(modules);

        return new ArchitectureMetrics
        {
            Timestamp = DateTime.UtcNow,
            OverallHealth = overallHealth,
            Modules = modules
        };
    }

    /// <summary>
    /// Calculates metrics for a single module service pattern.
    /// </summary>
private ModuleMetrics CalculateModuleMetrics(ServicePattern pattern)
    {
        var serviceCoverage = CalculateServiceCoverage(pattern);
        var facadeCoverage = CalculateFacadeCoverage(pattern);
        var health = DetermineHealthStatus(serviceCoverage, facadeCoverage);
        var opportunities = GenerateOpportunities(pattern, serviceCoverage, facadeCoverage);

        return new ModuleMetrics
        {
            Name = pattern.ModuleName,
            ServiceInterface = pattern.ServiceInterface,
            Implementation = pattern.Implementation,
            Facade = DetermineFacadeDescription(pattern),
            ServiceCoverage = serviceCoverage,
            FacadeCoverage = facadeCoverage,
            Health = health,
            Opportunities = opportunities
        };
    }

    /// <summary>
    /// Calculates Implementation → Service coverage percentage.
    /// Measures how well the service interface exposes implementation functionality.
    /// </summary>
private static double CalculateServiceCoverage(ServicePattern pattern)
    {
        if (pattern.ImplementationMethods.Count == 0)
            return 0.0;

        // Count how many implementation methods are exposed through the service interface
        var exposedMethods = pattern.ImplementationMethods
            .Count(implMethod => pattern.ServiceMethods.Any(serviceMethod => 
                string.Equals(implMethod, serviceMethod, StringComparison.OrdinalIgnoreCase) ||
                IsMethodEquivalent(implMethod, serviceMethod)));

        return (double)exposedMethods / pattern.ImplementationMethods.Count * 100.0;
    }

    /// <summary>
    /// Calculates Service → Facade coverage percentage.
    /// Measures how well facade methods expose basic service functionality for beginners.
    /// </summary>
private static double CalculateFacadeCoverage(ServicePattern pattern)
    {
        if (pattern.BasicServiceMethods.Count == 0)
            return 0.0;

        // Count how many basic service methods have facade equivalents
        var facadeExposedMethods = pattern.BasicServiceMethods
            .Count(basicMethod => pattern.FacadeMethods.Any(facadeMethod =>
                string.Equals(basicMethod, facadeMethod, StringComparison.OrdinalIgnoreCase) ||
                IsMethodEquivalent(basicMethod, facadeMethod) ||
                IsFacadeMethodRelated(basicMethod, facadeMethod)));

        return (double)facadeExposedMethods / pattern.BasicServiceMethods.Count * 100.0;
    }

    /// <summary>
    /// Determines if two method names are functionally equivalent.
    /// Handles naming variations like Play vs PlaySound.
    /// </summary>
private static bool IsMethodEquivalent(string method1, string method2)
    {
        // Remove common suffixes/prefixes to find core functionality
        var core1 = ExtractMethodCore(method1);
        var core2 = ExtractMethodCore(method2);

        return string.Equals(core1, core2, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Determines if a facade method is related to a basic service method.
    /// Checks for semantic relationships beyond exact naming.
    /// </summary>
private static bool IsFacadeMethodRelated(string basicMethod, string facadeMethod)
    {
        // Map common facade patterns to service methods
        var relationships = new Dictionary<string, string[]>
        {
            ["CreateEntity"] = new[] { "Create", "CreateEntity", "Add" },
            ["DestroyEntity"] = new[] { "Destroy", "Remove", "Delete" },
            ["PlaySound"] = new[] { "Play", "PlaySound", "PlayAudio" },
            ["SetVolume"] = new[] { "Set", "SetVolume", "SetMasterVolume" }
        };

        foreach (var (facade, related) in relationships)
        {
            if (string.Equals(facadeMethod, facade, StringComparison.OrdinalIgnoreCase))
            {
                return related.Any(r => basicMethod.Contains(r, StringComparison.OrdinalIgnoreCase));
            }
        }

        return false;
    }

    /// <summary>
    /// Extracts the core functionality from a method name by removing common prefixes/suffixes.
    /// </summary>
private static string ExtractMethodCore(string methodName)
    {
        var prefixesToRemove = new[] { "Get", "Set", "Is", "Has", "Can" };
        var suffixesToRemove = new[] { "Async", "Service", "Method", "Function" };

        var core = methodName;

        foreach (var prefix in prefixesToRemove)
        {
            if (core.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                core = core.Substring(prefix.Length);
                break;
            }
        }

        foreach (var suffix in suffixesToRemove)
        {
            if (core.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            {
                core = core.Substring(0, core.Length - suffix.Length);
                break;
            }
        }

        return core;
    }

    /// <summary>
    /// Calculates overall architecture health across all modules.
    /// </summary>
private static double CalculateOverallHealth(List<ModuleMetrics> modules)
    {
        if (modules.Count == 0)
            return 0.0;

        // Weight facade coverage more heavily as it's the primary indicator of beginner-friendliness
        var weightedScores = modules.Select(m => (m.ServiceCoverage * 0.3) + (m.FacadeCoverage * 0.7));
        return weightedScores.Average();
    }

    /// <summary>
    /// Determines health status based on coverage metrics.
    /// </summary>
private static string DetermineHealthStatus(double serviceCoverage, double facadeCoverage)
    {
        // Priority on facade coverage for beginner experience
        return facadeCoverage switch
        {
            >= 70 => "excellent",
            >= 50 => "good", 
            >= 30 => "needs-improvement",
            _ => "critical"
        };
    }

    /// <summary>
    /// Generates specific improvement opportunities for a module.
    /// </summary>
private static List<string> GenerateOpportunities(ServicePattern pattern, double serviceCoverage, double facadeCoverage)
    {
        var opportunities = new List<string>();

        if (facadeCoverage < 50)
        {
            opportunities.Add($"Add facade methods for common {pattern.ModuleName.ToLower()} operations");

            // Suggest specific missing facade methods
            var missingFacadeMethods = pattern.BasicServiceMethods
                .Where(basic => !pattern.FacadeMethods.Any(facade => 
                    IsMethodEquivalent(basic, facade) || IsFacadeMethodRelated(basic, facade)))
                .Take(3); // Limit to top 3 suggestions

            foreach (var missing in missingFacadeMethods)
            {
                opportunities.Add($"Consider adding {missing}() convenience method");
            }
        }

        if (serviceCoverage < 70 && pattern.ImplementationMethods.Count > pattern.ServiceMethods.Count)
        {
            opportunities.Add($"Expose more {pattern.ModuleName.ToLower()} implementation methods through service interface");
        }

        if (string.IsNullOrEmpty(pattern.ServiceInterface))
        {
            opportunities.Add($"Create I{pattern.ModuleName}Service interface for dependency injection support");
        }

        return opportunities;
    }

    /// <summary>
    /// Determines facade description based on detected facade patterns.
    /// </summary>
private static string DetermineFacadeDescription(ServicePattern pattern)
    {
        if (pattern.FacadeMethods.Count > 0)
        {
            return $"EngineFacade.{pattern.ModuleName}.*";
        }

        return "No facade layer detected";
    }

public static async Task Main(string[] args)
    {
        Console.WriteLine("RACEngine Progressive Complexity Metrics Analyzer");
        Console.WriteLine("================================================");

        var projectRoot = args.Length > 0 ? args[0] : FindProjectRoot();
        var srcPath = Path.Combine(projectRoot, "src");

        if (!Directory.Exists(srcPath))
        {
            Console.WriteLine($"Error: Source directory not found at {srcPath}");
            Environment.Exit(1);
        }

        Console.WriteLine($"Analyzing RACEngine projects in: {srcPath}");

        try
        {
            var metrics = await AnalyzeProjectsAsync(srcPath);
            await GenerateReports(metrics, projectRoot);

            Console.WriteLine($"\nAnalysis complete! Overall health: {metrics.OverallHealth:F1}%");
            Console.WriteLine($"Analyzed {metrics.Modules.Count} modules");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error during analysis: {ex.Message}");
            Environment.Exit(1);
        }
    }

    /// <summary>
    /// Analyzes all Rac.* projects and calculates architecture metrics.
    /// </summary>
private static async Task<ArchitectureMetrics> AnalyzeProjectsAsync(string srcPath)
    {
        var analyzer = new ProgressiveComplexityAnalyzer();
        var calculator = new MetricsCalculator();
        var allPatterns = new List<ServicePattern>();

        // Find all Rac.* project directories
        var projectDirs = Directory.GetDirectories(srcPath, "Rac.*")
            .Where(dir => File.Exists(Path.Combine(dir, Path.GetFileName(dir) + ".csproj")))
            .ToList();

        Console.WriteLine($"Found {projectDirs.Count} RACEngine projects:");
        foreach (var dir in projectDirs)
        {
            Console.WriteLine($"  - {Path.GetFileName(dir)}");
        }

        // Use a single detector across all projects to merge patterns
        var globalDetector = new ServicePatternDetector();

        // Analyze each project
        foreach (var projectDir in projectDirs)
        {
            await AnalyzeProjectAsync(projectDir, analyzer, globalDetector);
        }

        var patterns = globalDetector.GetDetectedPatterns();
        Console.WriteLine($"\nDetected {patterns.Count} service patterns:");
        foreach (var pattern in patterns)
        {
            Console.WriteLine($"  - {pattern.ModuleName}: {pattern.ServiceInterface} → {pattern.Implementation}");
        }

        return calculator.CalculateMetrics(patterns);
    }

    /// <summary>
    /// Analyzes a single project directory for service patterns.
    /// </summary>
private static async Task AnalyzeProjectAsync(string projectDir, ProgressiveComplexityAnalyzer analyzer, ServicePatternDetector detector)
    {
        var csFiles = Directory.GetFiles(projectDir, "*.cs", SearchOption.AllDirectories)
            .Where(f => !f.Contains("bin") && !f.Contains("obj"))
            .ToList();

        foreach (var csFile in csFiles)
        {
            try
            {
                var sourceCode = await File.ReadAllTextAsync(csFile);
                var syntaxTree = CSharpSyntaxTree.ParseText(sourceCode);

                // Create a basic compilation for semantic analysis
                var compilation = CSharpCompilation.Create("TempCompilation")
                    .AddSyntaxTrees(syntaxTree);
                var semanticModel = compilation.GetSemanticModel(syntaxTree);

                // Use the global detector instead of creating patterns per file
                var context = new AnalysisContextWrapper(semanticModel);
                var root = syntaxTree.GetRoot();

                // Analyze interfaces and classes
                foreach (var node in root.DescendantNodes())
                {
                    if (node is InterfaceDeclarationSyntax interfaceDecl)
                    {
                        detector.AnalyzeInterface(context, interfaceDecl);
                    }
                    else if (node is ClassDeclarationSyntax classDecl)
                    {
                        detector.AnalyzeClass(context, classDecl);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Warning: Could not analyze {csFile}: {ex.Message}");
            }
        }
    }

    /// <summary>
    /// Generates JSON and Markdown reports from architecture metrics.
    /// </summary>
private static async Task GenerateReports(ArchitectureMetrics metrics, string projectRoot)
    {
        var artifactsDir = Path.Combine(projectRoot, "tools", "artifacts", "architecture-metrics");
        Directory.CreateDirectory(artifactsDir);

        // Generate JSON report
        var jsonPath = Path.Combine(artifactsDir, $"metrics-{DateTime.UtcNow:yyyy-MM-dd-HHmmss}.json");
        var jsonOptions = new JsonSerializerOptions { WriteIndented = true };
        var json = JsonSerializer.Serialize(metrics, jsonOptions);
        await File.WriteAllTextAsync(jsonPath, json);
        Console.WriteLine($"JSON metrics saved to: {jsonPath}");

        // Generate Markdown report
        var docGenerator = new DocumentationGenerator();
        var markdown = docGenerator.GenerateMarkdownReport(metrics);
        var mdPath = Path.Combine(projectRoot, "docs", "architecture", "progressive-complexity-report.md");
        Directory.CreateDirectory(Path.GetDirectoryName(mdPath)!);
        await File.WriteAllTextAsync(mdPath, markdown);
        Console.WriteLine($"Markdown report saved to: {mdPath}");
    }

    /// <summary>
    /// Finds the project root directory by looking for the .sln file.
    /// </summary>
private static string FindProjectRoot()
    {
        var currentDir = Directory.GetCurrentDirectory();
        while (currentDir != null)
        {
            if (File.Exists(Path.Combine(currentDir, "RACEngine.sln")))
            {
                return currentDir;
            }
            currentDir = Directory.GetParent(currentDir)?.FullName;
        }
        return Directory.GetCurrentDirectory();
    }

public AnalysisContextWrapper(SemanticModel semanticModel)
    {
        SemanticModel = semanticModel;
    }

    /// <summary>
    /// Analyzes C# syntax trees and returns detected service patterns.
    /// </summary>
public List<ServicePattern> AnalyzeSyntaxTree(SyntaxTree syntaxTree, SemanticModel semanticModel)
    {
        var detector = new ServicePatternDetector();
        var context = new AnalysisContextWrapper(semanticModel);
        var root = syntaxTree.GetRoot();

        // Analyze interfaces and classes
        foreach (var node in root.DescendantNodes())
        {
            if (node is InterfaceDeclarationSyntax interfaceDecl)
            {
                detector.AnalyzeInterface(context, interfaceDecl);
            }
            else if (node is ClassDeclarationSyntax classDecl)
            {
                detector.AnalyzeClass(context, classDecl);
            }
        }

        return detector.GetDetectedPatterns().ToList();
    }

    /// <summary>
    /// Generates architecture insights based on detected patterns.
    /// </summary>
public List<ArchitectureInsight> GenerateInsights(ArchitectureMetrics metrics)
    {
        var insights = new List<ArchitectureInsight>();

        foreach (var module in metrics.Modules)
        {
            // Report opportunities for systems with good service coverage but low facade coverage
            if (module.ServiceCoverage > 70 && module.FacadeCoverage < 60)
            {
                insights.Add(new ArchitectureInsight
                {
                    Type = "PCM001",
                    Level = "Info",
                    Title = "Architecture opportunity: System could expose more facade methods",
                    Message = $"Architecture opportunity: {module.Name} system could expose more facade methods (current: {module.FacadeCoverage:F0}%)",
                    Module = module.Name
                });
            }

            // Report facade gaps for systems with very low facade coverage
            if (module.FacadeCoverage < 30)
            {
                insights.Add(new ArchitectureInsight
                {
                    Type = "PCM002",
                    Level = "Info", 
                    Title = "Facade gap: System has no beginner-friendly layer",
                    Message = $"Facade gap: {module.Name} system has no beginner-friendly layer ({module.FacadeCoverage:F0}% coverage)",
                    Module = module.Name
                });
            }
        }

        // Report overall health summary
        var healthSummary = GenerateHealthSummary(metrics.Modules);
        insights.Add(new ArchitectureInsight
        {
            Type = "PCM999",
            Level = "Hidden",
            Title = "Progressive Complexity Health Report",
            Message = $"Health Report: {healthSummary}",
            Module = "Overall"
        });

        return insights;
    }

private static string GenerateHealthSummary(IEnumerable<ModuleMetrics> modules)
    {
        var summaryParts = modules.Select(m =>
        {
            var healthIcon = m.FacadeCoverage >= 70 ? "✅" : m.FacadeCoverage >= 40 ? "⚠️" : "❌";
            return $"{m.Name}={m.ServiceCoverage:F0}%/{m.FacadeCoverage:F0}% {healthIcon}";
        });

        return string.Join(" | ", summaryParts);
    }

    /// <summary>
    /// Analyzes an interface declaration to detect service interfaces.
    /// Service interfaces follow the naming pattern I{ModuleName}Service.
    /// </summary>
public void AnalyzeInterface(AnalysisContextWrapper context, InterfaceDeclarationSyntax interfaceDecl)
    {
        var interfaceName = interfaceDecl.Identifier.ValueText;

        // Check if this is a service interface (I{ModuleName}Service pattern)
        if (IsServiceInterface(interfaceName))
        {
            var moduleName = ExtractModuleName(interfaceName);
            var methods = GetPublicMembers(interfaceDecl);

            var pattern = GetOrCreatePattern(moduleName);
            pattern.ServiceInterface = interfaceName;
            pattern.ServiceMethods.AddRange(methods);
            pattern.BasicServiceMethods.AddRange(methods.Where(IsBasicMethod));
        }
    }

    /// <summary>
    /// Analyzes a class declaration to detect service implementations and facade classes.
    /// </summary>
public void AnalyzeClass(AnalysisContextWrapper context, ClassDeclarationSyntax classDecl)
    {
        var className = classDecl.Identifier.ValueText;

        // Check if this is a service implementation
        var implementedInterfaces = GetImplementedInterfaces(classDecl, context.SemanticModel);

        foreach (var interfaceName in implementedInterfaces)
        {
            if (IsServiceInterface(interfaceName))
            {
                var moduleName = ExtractModuleName(interfaceName);
                var pattern = GetOrCreatePattern(moduleName);

                if (IsNullImplementation(className))
                {
                    pattern.NullImplementation = className;
                }
                else
                {
                    pattern.Implementation = className;
                    var methods = GetPublicMembers(classDecl);
                    pattern.ImplementationMethods.AddRange(methods);
                }
            }
        }

        // Check if this is a facade class (EngineFacade or {Module}Facade)
        if (IsFacadeClass(className))
        {
            var methods = GetPublicMembers(classDecl);

            // For EngineFacade, distribute methods to appropriate modules based on context
            if (className == "EngineFacade" || className == "ModularEngineFacade")
            {
                DistributeFacadeMethods(methods, classDecl, context.SemanticModel);
            }
            else
            {
                // Direct module facade
                var moduleName = ExtractModuleNameFromFacade(className);
                var pattern = GetOrCreatePattern(moduleName);
                pattern.FacadeMethods.AddRange(methods);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // PATTERN DETECTION HELPER METHODS
    // ═══════════════════════════════════════════════════════════════════════════

private static bool IsServiceInterface(string interfaceName)
    {
        return interfaceName.StartsWith("I") && interfaceName.EndsWith("Service");
    }

private static bool IsNullImplementation(string className)
    {
        return className.StartsWith("Null") && className.EndsWith("Service");
    }

private static bool IsFacadeClass(string className)
    {
        return className.EndsWith("Facade") || 
               className == "EngineFacade" || 
               className == "ModularEngineFacade";
    }

private static string ExtractModuleName(string interfaceName)
    {
        // I{Module}Service -> {Module}
        if (interfaceName.StartsWith("I") && interfaceName.EndsWith("Service"))
        {
            return interfaceName.Substring(1, interfaceName.Length - 8); // Remove "I" and "Service"
        }
        return interfaceName;
    }

private static string ExtractModuleNameFromFacade(string className)
    {
        // {Module}Facade -> {Module}
        if (className.EndsWith("Facade"))
        {
            return className.Substring(0, className.Length - 6); // Remove "Facade"
        }
        return className;
    }

private static bool IsBasicMethod(string methodName)
    {
        // Basic methods are simple, common operations suitable for facade exposure
        // Exclude advanced methods with many parameters or complex names
        var basicPrefixes = new[] { "Play", "Stop", "Set", "Get", "Create", "Destroy", "Add", "Remove", "Load", "Save" };
        var advancedKeywords = new[] { "3D", "Advanced", "Complex", "Detailed", "Internal" };

        // Input events are considered basic facade operations
        var inputEvents = new[] { "KeyEvent", "LeftClickEvent", "MouseScrollEvent", "OnLeftClick", "OnMouseScroll", "PressedKey", "OnKeyEvent" };

        var isBasicPrefix = basicPrefixes.Any(prefix => methodName.StartsWith(prefix));
        var hasAdvancedKeyword = advancedKeywords.Any(keyword => methodName.Contains(keyword));
        var isInputEvent = inputEvents.Contains(methodName);

        return (isBasicPrefix && !hasAdvancedKeyword) || isInputEvent;
    }

private static List<string> GetPublicMembers(TypeDeclarationSyntax typeDecl)
    {
        var members = new List<string>();

        // Get public methods
        var methods = typeDecl.Members
            .OfType<MethodDeclarationSyntax>()
            .Where(m => m.Modifiers.Any(Microsoft.CodeAnalysis.CSharp.SyntaxKind.PublicKeyword) ||
                       (typeDecl is InterfaceDeclarationSyntax)) // Interface methods are implicitly public
            .Select(m => m.Identifier.ValueText);

        members.AddRange(methods);

        // Get public events (important for facade pattern detection)
        var events = typeDecl.Members
            .OfType<EventDeclarationSyntax>()
            .Where(e => e.Modifiers.Any(Microsoft.CodeAnalysis.CSharp.SyntaxKind.PublicKeyword) ||
                       (typeDecl is InterfaceDeclarationSyntax)) // Interface events are implicitly public
            .Select(e => e.Identifier.ValueText);

        // Also check for event field declarations (like "public event Action<> EventName;")
        var eventFields = typeDecl.Members
            .OfType<EventFieldDeclarationSyntax>()
            .Where(e => e.Modifiers.Any(Microsoft.CodeAnalysis.CSharp.SyntaxKind.PublicKeyword) ||
                       (typeDecl is InterfaceDeclarationSyntax))
            .SelectMany(e => e.Declaration.Variables.Select(v => v.Identifier.ValueText));

        members.AddRange(events);
        members.AddRange(eventFields);

        // Get public properties (for comprehensive facade coverage)
        var properties = typeDecl.Members
            .OfType<PropertyDeclarationSyntax>()
            .Where(p => p.Modifiers.Any(Microsoft.CodeAnalysis.CSharp.SyntaxKind.PublicKeyword) ||
                       (typeDecl is InterfaceDeclarationSyntax)) // Interface properties are implicitly public
            .Select(p => p.Identifier.ValueText);

        members.AddRange(properties);

        return members;
    }

private static List<string> GetImplementedInterfaces(ClassDeclarationSyntax classDecl, SemanticModel? semanticModel)
    {
        var interfaces = new List<string>();

        if (classDecl.BaseList != null)
        {
            foreach (var baseType in classDecl.BaseList.Types)
            {
                var typeName = baseType.Type.ToString();

                // Simple heuristic: if it starts with I and looks like an interface, assume it is
                if (typeName.StartsWith("I") && char.IsUpper(typeName[1]))
                {
                    interfaces.Add(typeName);
                }

                // Try semantic model if available
                if (semanticModel != null)
                {
                    try
                    {
                        var symbolInfo = semanticModel.GetSymbolInfo(baseType.Type);
                        if (symbolInfo.Symbol is INamedTypeSymbol namedType && namedType.TypeKind == TypeKind.Interface)
                        {
                            interfaces.Add(namedType.Name);
                        }
                    }
                    catch
                    {
                        // Ignore semantic model errors, fall back to simple analysis
                    }
                }
            }
        }

        return interfaces.Distinct().ToList();
    }

private void DistributeFacadeMethods(List<string> methods, ClassDeclarationSyntax classDecl, SemanticModel semanticModel)
    {
        // Analyze method implementations to determine which module they belong to
        // This is a simplified approach - in reality, we'd need more sophisticated analysis

        foreach (var methodName in methods)
        {
            var moduleName = InferModuleFromMethodName(methodName);
            if (!string.IsNullOrEmpty(moduleName))
            {
                var pattern = GetOrCreatePattern(moduleName);
                pattern.FacadeMethods.Add(methodName);
            }
        }
    }

private static string InferModuleFromMethodName(string methodName)
    {
        // Simple heuristic to map facade method names to modules
        if (methodName.Contains("Entity") || methodName.Contains("Component"))
            return "ECS";
        if (methodName.Contains("Sound") || methodName.Contains("Audio") || methodName.Contains("Music"))
            return "Audio";
        if (methodName.Contains("Render") || methodName.Contains("Draw") || methodName.Contains("Color"))
            return "Rendering";
        if (methodName.Contains("Input") || methodName.Contains("Key") || methodName.Contains("Mouse") || 
            methodName == "KeyEvent" || methodName == "LeftClickEvent" || methodName == "MouseScrollEvent")
            return "Input";
        if (methodName.Contains("Physics") || methodName.Contains("Collision"))
            return "Physics";
        if (methodName.Contains("Container"))
            return "Container";

        return string.Empty; // Unknown module
    }

private ServicePattern GetOrCreatePattern(string moduleName)
    {
        var existing = _detectedPatterns.FirstOrDefault(p => p.ModuleName.Equals(moduleName, StringComparison.OrdinalIgnoreCase));
        if (existing != null)
            return existing;

        var newPattern = new ServicePattern { ModuleName = moduleName };
        _detectedPatterns.Add(newPattern);
        return newPattern;
    }

