func TestProfiler_processCustomSpans_FlushTicker(t *testing.T) {
	storage := NewMockJSONStorage()
	config := Config{
		APIKey:       "test-key",
		IngestURL:    "https://api.pprofio.com",
		Storage:      storage,
		SampleRate:   50 * time.Millisecond, // Short interval for faster testing
		ServiceName:  "test-service",
		EnableCustom: true,
	}

	profiler, err := newProfiler(config)
	if err != nil {
		t.Fatalf("Failed to create profiler: %v", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 150*time.Millisecond)
	defer cancel()

	// Start processCustomSpans in a goroutine
	profiler.wg.Add(1)
	go profiler.processCustomSpans(ctx)

	// Send a test span
	testSpan := &Span{
		Name:     "flush-test-span",
		Start:    time.Now(),
		Duration: 10 * time.Millisecond,
		Tags:     map[string]string{"test": "flush"},
	}

	select {
	case profiler.spanCh <- testSpan:
	case <-time.After(25 * time.Millisecond):
		t.Error("Failed to send test span")
	}

	// Wait for the flush ticker to trigger at least once
	time.Sleep(80 * time.Millisecond)

	// Wait for context to timeout
	<-ctx.Done()

	// Close the stop channel and wait for cleanup
	close(profiler.stopCh)
	profiler.wg.Wait()
}

func TestHTTPStorage_ErrorConditions(t *testing.T) {
	t.Run("MissingURL", func(t *testing.T) {
		storage := NewHTTPStorage("", "test-key", "local")

		_, err := storage.Upload(context.Background(), "test-file")
		if err == nil {
			t.Error("Expected error when URL is missing")
		}

		if !strings.Contains(err.Error(), "URL and APIKey are required") {
			t.Errorf("Expected 'URL and APIKey are required' error, got: %v", err)
		}
	})

	t.Run("MissingAPIKey", func(t *testing.T) {
		storage := NewHTTPStorage("https://test.com", "", "local")

		_, err := storage.Upload(context.Background(), "test-file")
		if err == nil {
			t.Error("Expected error when API key is missing")
		}

		if !strings.Contains(err.Error(), "URL and APIKey are required") {
			t.Errorf("Expected 'URL and APIKey are required' error, got: %v", err)
		}
	})

	t.Run("InvalidURL", func(t *testing.T) {
		storage := NewHTTPStorage("invalid-url", "test-key", "local")

		// Create a temporary file first
		tmpFile, err := os.CreateTemp("", "test-profile")
		if err != nil {
			t.Fatalf("Failed to create temp file: %v", err)
		}
		defer os.Remove(tmpFile.Name())

		tmpFile.WriteString("test data")
		tmpFile.Close()

		_, err = storage.Upload(context.Background(), tmpFile.Name())
		if err == nil {
			t.Error("Expected error for invalid URL")
		}

		if !strings.Contains(err.Error(), "invalid URL") && !strings.Contains(err.Error(), "unsupported protocol scheme") {
			t.Errorf("Expected 'invalid URL' or 'unsupported protocol scheme' error, got: %v", err)
		}
	})

	t.Run("HTTPSRequired", func(t *testing.T) {
		storage := NewHTTPStorage("http://test.com", "test-key", "production")

		_, err := storage.Upload(context.Background(), "test-file")
		if err == nil {
			t.Error("Expected error for HTTP URL in non-local environment")
		}

		if !strings.Contains(err.Error(), "HTTPS is required") {
			t.Errorf("Expected 'HTTPS is required' error, got: %v", err)
		}
	})

	t.Run("FileNotFound", func(t *testing.T) {
		storage := NewHTTPStorage("https://test.com", "test-key", "local")

		_, err := storage.Upload(context.Background(), "non-existent-file.txt")
		if err == nil {
			t.Error("Expected error for non-existent file")
		}

		if !strings.Contains(err.Error(), "failed to open file") {
			t.Errorf("Expected 'failed to open file' error, got: %v", err)
		}
	})

	t.Run("AuthenticationFailed", func(t *testing.T) {
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(http.StatusUnauthorized)
		}))
		defer server.Close()

		storage := NewHTTPStorage(server.URL, "invalid-key", "local")

		// Create a temporary file
		tmpFile, err := os.CreateTemp("", "test-profile")
		if err != nil {
			t.Fatalf("Failed to create temp file: %v", err)
		}
		defer os.Remove(tmpFile.Name())

		tmpFile.WriteString("test data")
		tmpFile.Close()

		_, err = storage.Upload(context.Background(), tmpFile.Name())
		if err == nil {
			t.Error("Expected authentication error")
		}

		if !strings.Contains(err.Error(), "authentication failed") {
