def safe_thread(func: Callable) -> Callable:
    """
    装饰器：确保线程安全执行

    Args:
        func: 要执行的函数
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            error_handler.handle_exception(e, f"线程执行 {func.__name__}")
            return None
    return wrapper

def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            error_handler.handle_exception(e, f"线程执行 {func.__name__}")
            return None

