def run_form():
    """Run the form backend"""
    print("📝 Starting Form Backend on port 5001...")

    try:
        subprocess.run([sys.executable, "form.py"], check=True)
    except KeyboardInterrupt:
        print("\n📝 Form Backend stopped.")
