            var step = savedPlan.Steps.First();
            Assert.Equal(2, step.AssignedMembers.Count);
            Assert.Contains(step.AssignedMembers, am => am.Name == "Member 1");
            Assert.Contains(step.AssignedMembers, am => am.Name == "Member 2");
        }

