def test_load_config_with_file(self):
        """Test loading configuration with specific file"""
        config_data = {
            'logging': {'level': 'WARNING'},
            'processing': {'max_workers': 10}
        }

        config_file = Path(self.temp_dir) / "config.yaml"
        with open(config_file, 'w') as f:
