func extractModelName(imageTag string) string {
	pattern := regexp.MustCompile(`liquidai/[^-]+-([^:]+)`)
	matches := pattern.FindStringSubmatch(imageTag)
	if len(matches) < 2 {
		return "lfm-7b" // Default value if pattern doesn't match
	}
	return matches[1]
}

