def get_day_type_count(self, person_id, target_date, existing_schedule):
        target_day_name = calendar.day_name[target_date.weekday()]
        day_type_count = 0

        for scheduled_date, scheduled_person, _ in existing_schedule:
            if scheduled_person == person_id:
                if calendar.day_name[scheduled_date.weekday()] == target_day_name:
                    day_type_count += 1

        return day_type_count

def display_schedule(self, schedule, year, month):
        personnel_counts = defaultdict(int)
        personnel_names = {}

        personnel = self.get_active_personnel()
        for person_id, name, status in personnel:
            personnel_names[person_id] = name
            personnel_counts[person_id] = 0

        for _, person_id, _ in schedule:
            if person_id:
                personnel_counts[person_id] += 1

        month_name = calendar.month_name[month]
        output = [f"\n{month_name} {year} Nöbet Listesi"]
        output.append("=" * 30)

        for day in schedule:
            date_obj, person_id, day_type = day
            day_name = calendar.day_name[date_obj.weekday()]
            date_str = date_obj.strftime("%d.%m.%Y")

            if person_id:
                person_name = personnel_names.get(person_id, "Bilinmeyen")
                count = personnel_counts[person_id]
                line = f"{date_str} {day_name.ljust(10)} - {day_type.ljust(12)}: {person_name} [{count}]"
            else:
                line = f"{date_str} {day_name.ljust(10)} - {day_type.ljust(12)}: ATAMA YAPILMADI"

            output.append(line)

        output.append("\nPersonel Nöbet Özeti:")
        output.append("-" * 25)
        for person_id, count in sorted(personnel_counts.items(), key=lambda x: x[1], reverse=True):
            output.append(f"{personnel_names[person_id].ljust(20)}: {count} nöbet")

        return "\n".join(output)

def test_simple_schedule():
    print("\n=== TESTING SIMPLE SCHEDULE GENERATION ===")

    db = Database()
    db.populate_sample_data()
    scheduler = DutyScheduler(db)

    try:
        schedule = scheduler.generate_schedule(2025, 6)
        print(f"Schedule generated successfully with {len(schedule)} days")

        person_day_counts = {}
        for scheduled_date, person_id, _ in schedule:
            if person_id:
                day_name = calendar.day_name[scheduled_date.weekday()]
                if person_id not in person_day_counts:
                    person_day_counts[person_id] = {}
                person_day_counts[person_id][day_name] = person_day_counts[person_id].get(day_name, 0) + 1

        violations = []
        for person_id, day_counts in person_day_counts.items():
            for day_name, count in day_counts.items():
                if count > 2:
                    violations.append(f"Person {person_id}: {day_name} = {count}")

        if violations:
            print(f"❌ VIOLATIONS: {violations}")
            return False
        else:
            print("✅ All day-type constraints satisfied")
            return True

    except Exception as e:
        print(f"❌ ERROR: {e}")
        return False

def _transform_for_moving_matrix(a):
    """Transform array for moving matrix functions.

    Benchmark arrays are in (..., vars, obs) format.
    Moving functions need (..., obs, vars) so we swap the last two dimensions.
    """
    return a.swapaxes(-2, -1)

def get_column_value(summary_df, func, lib, dimension, matrix_shape_exclusions):
        """Extract column value for a function/library pair with matrix function handling."""
        matching_cols = [
            col for col in summary_df.columns if col[0].removesuffix("_ratio") == lib
        ]

        if not matching_cols or func not in summary_df.index:
            return "n/a"

        # For matrix functions, try to find matrix-specific column first
        value = None
        if "matrix" in func:
            matrix_cols = [
                col
                for col in matching_cols
                if not any(exclusion in col[1] for exclusion in matrix_shape_exclusions)
            ]
            if matrix_cols:
                value = summary_df.loc[func, matrix_cols[0]]

        # Fallback to first column if no matrix-specific column found
        if value is None:
            value = summary_df.loc[func, matching_cols[0]]

        return value if not pd.isna(value) else "n/a"

def process_dimension_data(
        summary_df, func, dimension, all_libs, matrix_shape_exclusions
    ):
        """Process data for a single dimension (1D or 2D) for a specific function."""
        if summary_df.empty:
            return {f"{dimension}_{lib}": "n/a" for lib in all_libs}

        return {
            f"{dimension}_{lib}": get_column_value(
                summary_df, func, lib, dimension, matrix_shape_exclusions
            )
            for lib in all_libs
        }

func FindByEmail(ctx context.Context, email string) (*DBUser, error) {
	u := DBUser{}
	err := db.FindOneQContext(ctx, Collection, db.Query(bson.M{
		EmailAddressKey: email,
	}), &u)
	if adb.ResultsNotFound(err) {
		return nil, nil
	}
	if err != nil {
		return nil, errors.Wrap(err, "finding user by email")
	}

	return &u, nil
}

func ExtractCoAuthorEmail(message string) string {
	re := regexp.MustCompile(`(?i)Co-Authored-By:.*<([^>]+)>`)
	matches := re.FindStringSubmatch(message)
	if len(matches) > 1 {
		return matches[1]
	}
	return ""
}

func GetCommitAuthorEmail(ctx context.Context, owner, repo string, prNumber int) (string, error) {
	caller := "GetCommitAuthorEmail"
	ctx, span := tracer.Start(ctx, caller, trace.WithAttributes(
		attribute.String(githubEndpointAttribute, caller),
		attribute.String(githubOwnerAttribute, owner),
		attribute.String(githubRepoAttribute, repo),
	))
	defer span.End()

	token, err := getInstallationToken(ctx, owner, repo, nil)
	if err != nil {
		return "", errors.Wrap(err, "getting installation token")
	}

	githubClient := getGithubClient(token, caller, retryConfig{retry: true})
	defer githubClient.Close()

	opts := &github.ListOptions{Page: 1, PerPage: 1}
	commits, resp, err := githubClient.PullRequests.ListCommits(ctx, owner, repo, prNumber, opts)
	if resp != nil {
		defer resp.Body.Close()
		span.SetAttributes(attribute.Bool(githubCachedAttribute, respFromCache(resp.Response)))
	}
	if err != nil {
		return "", errors.Wrap(err, "listing commits from PR")
	}
	if len(commits) == 0 {
		return "", errors.New("no commits found in PR")
	}

	firstCommit := commits[0]
	if firstCommit.Commit == nil {
		return "", errors.New("commit information not found")
	}

	if firstCommit.Commit.Message != nil {
		coAuthorEmail := ExtractCoAuthorEmail(*firstCommit.Commit.Message)
		if coAuthorEmail != "" {
			grip.Info(message.Fields{
				"message":         "Found co-author in commit message",
				"commit_sha":      firstCommit.GetSHA(),
				"co_author_email": coAuthorEmail,
				"ticket":          "DEVPROD-16345",
			})
			return coAuthorEmail, nil
		}
	}

	if firstCommit.Commit.Author == nil || firstCommit.Commit.Author.Email == nil {
		return "", errors.New("commit author email not found")
	}

	return *firstCommit.Commit.Author.Email, nil
}

