        userJpaRepository.findAll().map { it.toDomain() }
    }

override suspend fun sendPasswordResetEmail(to: String, resetLink: String) {
        withContext(Dispatchers.IO) {
            try {
                val message = mailSender.createMimeMessage()
                val helper = MimeMessageHelper(message, true, "UTF-8")

                helper.setTo(to)
                helper.setSubject("Password Reset Request")

                val context = Context()
                context.setVariable("resetLink", resetLink)

                val htmlContent = templateEngine.process("email/password-reset-email", context)
                helper.setText(htmlContent, true)

                mailSender.send(message)
                logger.info("Password reset email sent to: $to")
            } catch (e: Exception) {
                logger.error("Failed to send password reset email to: $to", e)
                throw e
            }
        }
    }

    /**
     * Convert SearchRequestDto to SearchCriteria domain model
     */
fun toDomain(dto: SearchRequestDto): SearchCriteria {
        return SearchCriteria(
            query = dto.query,
            category = dto.category,
            minPrice = dto.minPrice,
            maxPrice = dto.maxPrice,
            location = dto.location,
            sortBy = parseSortOption(dto.sortBy),
            limit = dto.limit,
            offset = dto.offset
        )
    }

