constructor() {
        this.viewports = [];
        this.models = [null, null, null];
        this.wireframeMode = false;
        this.isSync = false;
        this.loadingStates = [false, false, false];

        this.init();
    }

init() {
        // 初始化三个视窗
        for (let i = 0; i < 3; i++) {
            this.initViewport(i);
        }

        // 绑定文件输入事件
        this.bindFileInputs();

        // 开始渲染循环
        this.animate();
    }

initViewport(index) {
        const viewportElement = document.getElementById(`viewport${index + 1}`);
        const loadingElement = document.getElementById(`loading${index + 1}`);

        // 创建场景
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0xf0f0f0);

        // 创建相机
        const camera = new THREE.PerspectiveCamera(
            75,
            viewportElement.clientWidth / (viewportElement.clientHeight - 60),
            0.1,
            1000
        );
        camera.position.set(0, 0, 5);

        // 创建渲染器
        const renderer = new THREE.WebGLRenderer({ 
            antialias: true,
            alpha: true
        });
        renderer.setSize(
            viewportElement.clientWidth,
            viewportElement.clientHeight - 60
        );
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;

        // 添加到DOM
        viewportElement.appendChild(renderer.domElement);

        // 创建控制器
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.enableZoom = true;
        controls.enablePan = true;
        controls.enableRotate = true;

        // 添加灯光
        this.addLights(scene);

        // 绑定同步事件
        this.bindSyncEvents(controls, index);

        // 存储视窗信息
        this.viewports[index] = {
            scene,
            camera,
            renderer,
            controls,
            element: viewportElement,
            loadingElement
        };

        // 隐藏加载指示器
        loadingElement.style.display = 'none';

        // 处理窗口大小变化
        window.addEventListener('resize', () => this.handleResize(index));
    }

addLights(scene) {
        // 环境光
        const ambientLight = new THREE.AmbientLight(0x404040, 0.6);
        scene.add(ambientLight);

        // 主方向光
        const directionalLight1 = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight1.position.set(1, 1, 1);
        directionalLight1.castShadow = true;
        directionalLight1.shadow.mapSize.width = 2048;
        directionalLight1.shadow.mapSize.height = 2048;
        scene.add(directionalLight1);

        // 补充方向光
        const directionalLight2 = new THREE.DirectionalLight(0xffffff, 0.4);
        directionalLight2.position.set(-1, -1, -1);
        scene.add(directionalLight2);

        // 点光源
        const pointLight = new THREE.PointLight(0xffffff, 0.5, 100);
        pointLight.position.set(0, 10, 10);
        scene.add(pointLight);
    }

bindSyncEvents(controls, index) {
        let isUpdating = false;

        const syncTransformation = () => {
            if (isUpdating || !this.isSync) return;

            isUpdating = true;
            this.showSyncIndicator();

            const sourceCamera = this.viewports[index].camera;
            const sourceControls = this.viewports[index].controls;

            // 同步到其他视窗
            this.viewports.forEach((viewport, i) => {
                if (i !== index && viewport) {
                    // 同步相机位置和目标
                    viewport.camera.position.copy(sourceCamera.position);
                    viewport.camera.quaternion.copy(sourceCamera.quaternion);
                    viewport.controls.target.copy(sourceControls.target);
                    viewport.controls.update();
                }
            });

            setTimeout(() => {
                this.hideSyncIndicator();
                isUpdating = false;
            }, 100);
        };

        controls.addEventListener('change', syncTransformation);
    }

