                    const result = loader.parse(fileData);
                    resolve(result);
                }
            } catch (error) {
                reject(error);
            }
        }

getModelColor(index) {
        const colors = [0x667eea, 0xe74c3c, 0x2ecc71];
        return colors[index % colors.length];
    }

clearModel(viewportIndex) {
        const viewport = this.viewports[viewportIndex];
        if (this.models[viewportIndex]) {
            viewport.scene.remove(this.models[viewportIndex]);
            this.models[viewportIndex] = null;
        }

        // 清除模型信息
        const existingInfo = viewport.element.querySelector('.model-info');
        if (existingInfo) {
            existingInfo.remove();
        }
    }

fitModelToView(mesh, viewport) {
        // 计算模型边界框
        const box = new THREE.Box3().setFromObject(mesh);
        const size = box.getSize(new THREE.Vector3());
        const center = box.getCenter(new THREE.Vector3());

        // 将模型移动到原点
        mesh.position.sub(center);

        // 计算适合的缩放比例
        const maxDimension = Math.max(size.x, size.y, size.z);
        const scale = 2 / maxDimension;
        mesh.scale.setScalar(scale);

        // 调整相机位置
        const distance = Math.max(2, maxDimension * 0.8);
        viewport.camera.position.set(distance, distance, distance);
        viewport.camera.lookAt(0, 0, 0);
        viewport.controls.target.set(0, 0, 0);
        viewport.controls.update();
    }

updateModelInfo(viewportIndex, fileName, geometry) {
        const viewport = this.viewports[viewportIndex];

        // 计算顶点数
        let vertexCount = 0;
        if (geometry.isBufferGeometry) {
            vertexCount = geometry.attributes.position ? geometry.attributes.position.count : 0;
        } else if (geometry.isGroup) {
            // 对于OBJ文件的Group对象
            geometry.traverse((child) => {
                if (child.isMesh && child.geometry.attributes.position) {
                    vertexCount += child.geometry.attributes.position.count;
                }
            });
        }

        // 创建信息显示
        const infoDiv = document.createElement('div');
        infoDiv.className = 'model-info';
        infoDiv.innerHTML = `
            <div><strong>${fileName}</strong></div>
            <div>顶点数: ${vertexCount.toLocaleString()}</div>
        `;

        viewport.element.appendChild(infoDiv);
    }

            // 对于OBJ文件的Group对象
(child) => {
                if (child.isMesh && child.geometry.attributes.position) {
                    vertexCount += child.geometry.attributes.position.count;
                }
            }

showLoading(index) {
        this.loadingStates[index] = true;
        const loadingElement = this.viewports[index].loadingElement;
        loadingElement.style.display = 'block';
        loadingElement.innerHTML = `
            <div class="spinner"></div>
            正在加载模型...
        `;
    }

hideLoading(index) {
        this.loadingStates[index] = false;
        const loadingElement = this.viewports[index].loadingElement;
        loadingElement.style.display = 'none';
    }

showSyncIndicator() {
        const indicator = document.getElementById('syncIndicator');
        indicator.classList.add('active');
    }

hideSyncIndicator() {
        const indicator = document.getElementById('syncIndicator');
        indicator.classList.remove('active');
    }

handleResize(index) {
        const viewport = this.viewports[index];
        if (!viewport) return;

        const width = viewport.element.clientWidth;
        const height = viewport.element.clientHeight - 60;

        viewport.camera.aspect = width / height;
        viewport.camera.updateProjectionMatrix();
        viewport.renderer.setSize(width, height);
    }

animate() {
        requestAnimationFrame(() => this.animate());

        // 更新所有视窗
        this.viewports.forEach((viewport, index) => {
            if (viewport && !this.loadingStates[index]) {
                viewport.controls.update();
                viewport.renderer.render(viewport.scene, viewport.camera);
            }
        });
    }

