toggleWireframe() {
        this.wireframeMode = !this.wireframeMode;

        this.models.forEach((model) => {
            if (model) {
                if (model.isMesh) {
                    model.material.wireframe = this.wireframeMode;
                } else if (model.isGroup) {
                    model.traverse((child) => {
                        if (child.isMesh) {
                            child.material.wireframe = this.wireframeMode;
                        }
                    });
                }
            }
        });
