// TestTupleKey tests the TupleKey helper function
func TestTupleKey(t *testing.T) {
	tests := []struct {
		name     string
		user     string
		relation string
		object   string
		want     ClientTupleKey
	}{
		{
			name:     "standard tuple",
			user:     "user:123",
			relation: "admin",
			object:   "project:456",
			want: ClientTupleKey{
				User:     "user:123",
				Relation: "admin",
				Object:   "project:456",
			},
		},
		{
			name:     "wildcard user",
			user:     "user:*",
			relation: "viewer",
			object:   "project:public",
			want: ClientTupleKey{
				User:     "user:*",
				Relation: "viewer",
				Object:   "project:public",
			},
		},
		{
			name:     "group user",
			user:     "group:developers",
			relation: "writer",
			object:   "project:123",
			want: ClientTupleKey{
				User:     "group:developers",
				Relation: "writer",
				Object:   "project:123",
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			handlerService := setupService()
			got := handlerService.fgaService.TupleKey(tt.user, tt.relation, tt.object)
			if got.User != tt.want.User || got.Relation != tt.want.Relation || got.Object != tt.want.Object {
				t.Errorf("fgaTupleKey() = %+v, want %+v", got, tt.want)
			}
