// Reply implements the INatsMsg interface
func (m *MockNatsMsg) Reply() string {
	return m.reply
}

// Respond implements the INatsMsg interface
func (m *MockNatsMsg) Respond(data []byte) error {
	args := m.Called(data)
	return args.Error(0)
}

// Data implements the INatsMsg interface
func (m *MockNatsMsg) Data() []byte {
	return m.data
}

// Subject implements the INatsMsg interface
func (m *MockNatsMsg) Subject() string {
	return m.subject
}

// CreateMockNatsMsg creates a mock NATS message that can be used in tests
func CreateMockNatsMsg(data []byte) *MockNatsMsg {
	msg := MockNatsMsg{
		data: data,
	}
	return &msg
}

// NewMockKeyValue creates a new MockKeyValue instance
func NewMockKeyValue() *MockKeyValue {
	return &MockKeyValue{
		data:         make(map[string][]byte),
		createdTimes: make(map[string]time.Time),
		notFoundKeys: make(map[string]bool),
	}
}

// Get implements the jetstream.KeyValue interface
func (m *MockKeyValue) Get(ctx context.Context, key string) (jetstream.KeyValueEntry, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.returnError != nil {
		return nil, m.returnError
	}
	if m.notFoundKeys[key] {
		return nil, jetstream.ErrKeyNotFound
	}
	if data, exists := m.data[key]; exists {
		return &MockKeyValueEntry{
			key:     key,
			value:   data,
			created: m.createdTimes[key],
		}, nil
	}
	return nil, jetstream.ErrKeyNotFound
}

// Put implements the jetstream.KeyValue interface
func (m *MockKeyValue) Put(ctx context.Context, key string, value []byte) (uint64, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.returnError != nil {
		return 0, m.returnError
	}
	m.data[key] = value
	m.createdTimes[key] = time.Now()
	return 1, nil
}

// PutString implements the jetstream.KeyValue interface
func (m *MockKeyValue) PutString(ctx context.Context, key, value string) (uint64, error) {
	return m.Put(ctx, key, []byte(value))
}

// SetNotFound implements the jetstream.KeyValue interface
func (m *MockKeyValue) SetNotFound(key string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.notFoundKeys[key] = true
}

// SetError implements the jetstream.KeyValue interface
func (m *MockKeyValue) SetError(err error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.returnError = err
}

    /// <summary>
    /// Initializes a new instance of the CaptureCompareUnit class.
    /// </summary>
    /// <param name="unitNumber">The unit number (0-6, where 0 is typically the period register).</param>
public CaptureCompareUnit(int unitNumber)
    {
        UnitNumber = unitNumber;
        Reset();
    }

    /// <summary>
    /// Handles a timer count update in compare mode.
    /// </summary>
    /// <param name="timerValue">The current timer value.</param>
    /// <param name="isEqu0Event">True if this is an EQU0 event (timer equals TAxCCR0).</param>
public void HandleCompareEvent(ushort timerValue, bool isEqu0Event = false)
    {
        if (_mode != CaptureCompareMode.Compare)
        {
            return;
        }

        bool isEqunEvent = timerValue == _captureCompareValue;

        if (isEqunEvent || isEqu0Event)
        {
            UpdateOutput(isEqunEvent, isEqu0Event);

            if (isEqunEvent)
            {
                // According to SLAU445I Section 13.2.4.2: "The input signal CCI is latched into SCCI"
                _synchronizedCaptureCompareInput = _captureCompareInput;

                // Set interrupt flag only on EQUn events (not EQU0)
                _interruptFlag = true;

                // Raise interrupt if enabled
                if (_interruptEnable)
                {
                    InterruptRequested?.Invoke(this, new CaptureCompareInterruptEventArgs(UnitNumber));
                }
            }
        }
    }

    /// <summary>
    /// Handles a capture event when an input signal edge is detected.
    /// </summary>
    /// <param name="timerValue">The current timer value to capture.</param>
public void HandleCaptureEvent(ushort timerValue)
    {
        if (_mode != CaptureCompareMode.Capture)
        {
            return;
        }

        // Check for capture overflow according to SLAU445I Section 13.2.4.1 Figure 13-11
        // COV is set if a second capture occurs before the first capture was read
        if (_interruptFlag && !_lastCaptureRead)
        {
            _captureOverflow = true;
        }

        // Capture the timer value
        _captureCompareValue = timerValue;
        _lastCaptureRead = false;

        // Set interrupt flag
        _interruptFlag = true;

        // Raise interrupt if enabled
        if (_interruptEnable)
        {
            InterruptRequested?.Invoke(this, new CaptureCompareInterruptEventArgs(UnitNumber));
        }
    }

    /// <summary>
    /// Clears the interrupt flag.
    /// </summary>
public void ClearInterruptFlag()
    {
        _interruptFlag = false;
    }

    /// <summary>
    /// Clears the capture overflow flag.
    /// Must be called by software to clear COV bit.
    /// </summary>
public void ClearCaptureOverflow()
    {
        _captureOverflow = false;
    }

    /// <summary>
    /// Resets the capture/compare unit to its default state.
    /// </summary>
public void Reset()
    {
        _captureCompareValue = 0x0000;
        _mode = CaptureCompareMode.Compare;
        _outputMode = OutputMode.Output;
        _captureInput = CaptureInputSelect.CCIxA;
        _captureEdgeMode = CaptureEdgeMode.None;
        _synchronizeCaptureSource = false;
        _outputValue = false;
        _interruptEnable = false;
        _interruptFlag = false;
        _captureOverflow = false;
        _lastCaptureRead = true;
        _captureCompareInput = false;
        _synchronizedCaptureCompareInput = false;
    }

    /// <summary>
    /// Updates the output signal based on the output mode and event type.
    /// 
    /// MSP430FR2xx FR4xx Family User's Guide (SLAU445I) - Section 13.2.5.1:
    /// Table 13-2: Output Modes
    /// </summary>
    /// <param name="isEqunEvent">True if this is an EQUn event (timer equals TAxCCRn).</param>
    /// <param name="isEqu0Event">True if this is an EQU0 event (timer equals TAxCCR0).</param>
private void UpdateOutput(bool isEqunEvent, bool isEqu0Event)
    {
        switch (_outputMode)
        {
            case OutputMode.Output:
                // Mode 0: Output is controlled by the OUT bit - no automatic changes
                break;

            case OutputMode.Set:
                // Mode 1: Set on EQUn, remains set until reset or mode change
                if (isEqunEvent)
                {
                    _outputValue = true;
                }
                break;

            case OutputMode.ToggleReset:
                // Mode 2: Toggle on EQUn, reset on EQU0
                if (isEqunEvent)
                {
                    _outputValue = !_outputValue;
                }
                if (isEqu0Event)
                {
                    _outputValue = false;
                }
                break;

            case OutputMode.SetReset:
                // Mode 3: Set on EQUn, reset on EQU0
                if (isEqunEvent)
                {
                    _outputValue = true;
                }
                if (isEqu0Event)
                {
                    _outputValue = false;
                }
                break;

            case OutputMode.Toggle:
                // Mode 4: Toggle on EQUn - output period is double timer period
                if (isEqunEvent)
                {
                    _outputValue = !_outputValue;
                }
                break;

            case OutputMode.Reset:
                // Mode 5: Reset on EQUn, remains reset until mode change
                if (isEqunEvent)
                {
                    _outputValue = false;
                }
                break;

            case OutputMode.ToggleSet:
                // Mode 6: Toggle on EQUn, set on EQU0
                if (isEqunEvent)
                {
                    _outputValue = !_outputValue;
                }
                if (isEqu0Event)
                {
                    _outputValue = true;
                }
                break;

            case OutputMode.ResetSet:
                // Mode 7: Reset on EQUn, set on EQU0
                if (isEqunEvent)
                {
                    _outputValue = false;
                }
                if (isEqu0Event)
                {
                    _outputValue = true;
                }
                break;
        }
    }

    /// <summary>
    /// Initializes a new instance of the CaptureCompareInterruptEventArgs class.
    /// </summary>
    /// <param name="unitNumber">The capture/compare unit number that generated the interrupt.</param>
public CaptureCompareInterruptEventArgs(int unitNumber)
    {
        UnitNumber = unitNumber;
    }

    /// <summary>
    /// Initializes a new instance of the TimerA class.
    /// </summary>
    /// <param name="timerName">The timer name (e.g., "TA0", "TA1").</param>
    /// <param name="baseAddress">The base address of the timer registers.</param>
    /// <param name="interruptVector">The interrupt vector address for this timer.</param>
    /// <param name="logger">Optional logger for diagnostic output.</param>
    /// <exception cref="ArgumentNullException">Thrown when timerName is null.</exception>
public TimerA(string timerName, ushort baseAddress, ushort interruptVector, ILogger? logger = null)
        : base($"Timer_{timerName}", baseAddress, 0x30, logger)
    {
        _timerName = timerName ?? throw new ArgumentNullException(nameof(timerName));
        _interruptVector = interruptVector;
        _clock = new TimerClock();

        // Create capture/compare units (typically 3 units: CCR0, CCR1, CCR2)
        _captureCompareUnits = new CaptureCompareUnit[3];
        for (int i = 0; i < _captureCompareUnits.Length; i++)
        {
            _captureCompareUnits[i] = new CaptureCompareUnit(i);
            _captureCompareUnits[i].InterruptRequested += OnCaptureCompareInterrupt;
        }

        InitializeRegisters();
    }

    /// <summary>
    /// Advances the timer by one clock cycle.
    /// This method should be called by the emulator core to update the timer state.
    /// </summary>
public void Tick()
    {
        if (_mode == TimerMode.Stop)
        {
            return;
        }

        bool rollover = false;

        switch (_mode)
        {
            case TimerMode.Up:
                TickUpMode(out rollover);
                break;

            case TimerMode.Continuous:
                TickContinuousMode(out rollover);
                break;

            case TimerMode.UpDown:
                TickUpDownMode(out rollover);
                break;
        }

        // Check for capture/compare events
        for (int i = 0; i < _captureCompareUnits.Length; i++)
        {
            CaptureCompareUnit unit = _captureCompareUnits[i];

            // Check for EQUn event (timer equals this unit's CCR value)
            bool isEqunEvent = _timerValue == unit.CaptureCompareValue;

            // Check for EQU0 event (timer equals CCR0 - only relevant for units 1+ in certain modes)
            bool isEqu0Event = false;
            if (i > 0) // Unit 0 doesn't respond to its own EQU0 event for output modes
            {
                isEqu0Event = _timerValue == _captureCompareUnits[0].CaptureCompareValue;
            }

            // Handle the compare event
            if (isEqunEvent || isEqu0Event)
            {
                unit.HandleCompareEvent(_timerValue, isEqu0Event);
            }
        }

        // Handle timer overflow interrupt
        if (rollover && _interruptEnable)
        {
            _interruptFlag = true;
            OnInterruptRequested(_interruptVector, $"{_timerName}_TAIFG", 1);
        }
    }

    /// <summary>
    /// Simulates a capture event on the specified capture/compare unit.
    /// </summary>
    /// <param name="unitNumber">The capture/compare unit number.</param>
public void TriggerCaptureEvent(int unitNumber)
    {
        if (unitNumber >= 0 && unitNumber < _captureCompareUnits.Length)
        {
            _captureCompareUnits[unitNumber].HandleCaptureEvent(_timerValue);
        }
    }

    /// <summary>
    /// Gets the PWM duty cycle for the specified capture/compare unit.
    /// </summary>
    /// <param name="unitNumber">The capture/compare unit number.</param>
    /// <returns>The duty cycle as a percentage (0-100), or 0 if not in PWM mode.</returns>
public double GetPwmDutyCycle(int unitNumber)
    {
        if (unitNumber < 0 || unitNumber >= _captureCompareUnits.Length || unitNumber == 0)
        {
            return 0.0;
        }

        if (_mode != TimerMode.Up)
        {
            return 0.0;
        }

        CaptureCompareUnit unit = _captureCompareUnits[unitNumber];
        ushort period = _captureCompareUnits[0].CaptureCompareValue;

        if (period == 0)
        {
            return 0.0;
        }

        return (double)unit.CaptureCompareValue / period * 100.0;
    }

    /// <summary>
    /// Sets the PWM duty cycle for the specified capture/compare unit.
    /// </summary>
    /// <param name="unitNumber">The capture/compare unit number.</param>
    /// <param name="dutyCyclePercent">The duty cycle as a percentage (0-100).</param>
public void SetPwmDutyCycle(int unitNumber, double dutyCyclePercent)
    {
        if (unitNumber <= 0 || unitNumber >= _captureCompareUnits.Length)
        {
            return;
        }

        dutyCyclePercent = Math.Clamp(dutyCyclePercent, 0.0, 100.0);
        ushort period = _captureCompareUnits[0].CaptureCompareValue;
        ushort compareValue = (ushort)(period * dutyCyclePercent / 100.0);

        _captureCompareUnits[unitNumber].CaptureCompareValue = compareValue;
    }

    /// <inheritdoc />
protected override void OnReset()
    {
        _timerValue = 0x0000;
        _lastTimerValue = 0x0000;
        _mode = TimerMode.Stop;
        _isCountingUp = true;
        _interruptEnable = false;
        _interruptFlag = false;
        _clock.Reset();

        foreach (CaptureCompareUnit unit in _captureCompareUnits)
        {
            unit.Reset();
        }

        Logger?.Debug($"Timer {_timerName} reset completed");
    }

    /// <inheritdoc />
protected override void OnRegisterChanged(PeripheralRegister register, ushort address)
    {
        ushort offset = (ushort)(address - BaseAddress);

        switch (offset)
        {
            case OffsetTAxCTL:
                HandleControlRegisterChange(register.ReadWord());
                break;

            case OffsetTAxR:
                _timerValue = register.ReadWord();
                break;

            case OffsetTAxCCR0:
                // Warn if updating compare value while timer is running
                if (_mode != TimerMode.Stop && _captureCompareUnits[0].Mode == CaptureCompareMode.Compare)
                {
                    Logger?.Warning($"Timer {_timerName} CCR0 updated while timer is running. This may cause unexpected behavior. " +
                                   "Stop timer (MC=0) before updating compare values.");
                }
                _captureCompareUnits[0].CaptureCompareValue = register.ReadWord();
                break;

            case OffsetTAxCCR1:
                if (_captureCompareUnits.Length > 1)
                {
                    // Warn if updating compare value while timer is running
                    if (_mode != TimerMode.Stop && _captureCompareUnits[1].Mode == CaptureCompareMode.Compare)
                    {
                        Logger?.Warning($"Timer {_timerName} CCR1 updated while timer is running. This may cause unexpected behavior. " +
                                       "Stop timer (MC=0) before updating compare values.");
                    }
                    _captureCompareUnits[1].CaptureCompareValue = register.ReadWord();
                }

                break;

            case OffsetTAxCCR2:
                if (_captureCompareUnits.Length > 2)
                {
                    // Warn if updating compare value while timer is running
                    if (_mode != TimerMode.Stop && _captureCompareUnits[2].Mode == CaptureCompareMode.Compare)
                    {
                        Logger?.Warning($"Timer {_timerName} CCR2 updated while timer is running. This may cause unexpected behavior. " +
                                       "Stop timer (MC=0) before updating compare values.");
                    }
                    _captureCompareUnits[2].CaptureCompareValue = register.ReadWord();
                }

                break;

            case OffsetTAxCCTL0:
                HandleCaptureCompareControlChange(0, register.ReadWord());
                break;

            case OffsetTAxCCTL1:
                if (_captureCompareUnits.Length > 1)
                {
                    HandleCaptureCompareControlChange(1, register.ReadWord());
                }

                break;

            case OffsetTAxCCTL2:
                if (_captureCompareUnits.Length > 2)
                {
                    HandleCaptureCompareControlChange(2, register.ReadWord());
                }

                break;
        }
    }

    /// <summary>
    /// Initializes the timer registers.
    /// </summary>
private void InitializeRegisters()
    {
        // Timer_A Control Register
        AddRegister(new PeripheralRegister(
            (ushort)(BaseAddress + OffsetTAxCTL),
            0x0000,
            PeripheralRegisterAccess.ReadWrite,
            readMask: 0x03FF,
            writeMask: 0x03FF,
            name: $"{_timerName}CTL"));

        // Timer_A Counter Register
        AddRegister(new PeripheralRegister(
            (ushort)(BaseAddress + OffsetTAxR),
            0x0000,
            PeripheralRegisterAccess.ReadWrite,
            name: $"{_timerName}R"));

        // Capture/Compare Control and Value Registers
        for (int i = 0; i < _captureCompareUnits.Length; i++)
        {
            ushort cctlOffset = (ushort)(OffsetTAxCCTL0 + (i * 2));
            ushort ccrOffset = (ushort)(OffsetTAxCCR0 + (i * 2));

            AddRegister(new PeripheralRegister(
                (ushort)(BaseAddress + cctlOffset),
                0x0000,
                PeripheralRegisterAccess.ReadWrite,
                readMask: 0xF1FF,
                writeMask: 0xF1FF,
                name: $"{_timerName}CCTL{i}"));

            AddRegister(new PeripheralRegister(
                (ushort)(BaseAddress + ccrOffset),
                0x0000,
                PeripheralRegisterAccess.ReadWrite,
                name: $"{_timerName}CCR{i}"));
        }

        // Timer_A Interrupt Vector Register (read-only)
        AddRegister(new PeripheralRegister(
            (ushort)(BaseAddress + OffsetTAxIV),
            0x0000,
            PeripheralRegisterAccess.Read,
            name: $"{_timerName}IV"));
    }

    /// <summary>
    /// Handles changes to the timer control register.
    /// </summary>
    /// <param name="value">The new control register value.</param>
private void HandleControlRegisterChange(ushort value)
    {
        // Check for timer clear
        if ((value & TAxCTL_TACLR) != 0)
        {
            _timerValue = 0x0000;
            // According to SLAU445I Section 13.2.3.4: "The TACLR bit also clears the direction"
            _isCountingUp = true;
            // Clear bit is automatically cleared after operation
            PeripheralRegister? ctlRegister = GetRegister((ushort)(BaseAddress + OffsetTAxCTL));
            ctlRegister?.WriteWord((ushort)(value & ~TAxCTL_TACLR));
        }

        // Update mode
        int modeField = (value & TAxCTL_MC_MASK) >> 4;
        _mode = (TimerMode)modeField;

        // Update interrupt enable
        _interruptEnable = (value & TAxCTL_TAIE) != 0;

        // Update clock source
        int clockSourceField = (value & TAxCTL_TASSEL_MASK) >> 8;
        _clock.ClockSource = (TimerClockSource)clockSourceField;

        // Update input divider
        int dividerField = (value & TAxCTL_ID_MASK) >> 6;
        _clock.InputDivider = (TimerInputDivider)dividerField;

        Logger?.Debug($"Timer {_timerName} control updated: Mode={_mode}, ClockSource={_clock.ClockSource}, Divider={_clock.InputDivider}");
    }

    /// <summary>
    /// Handles changes to capture/compare control registers.
    /// </summary>
    /// <param name="unitNumber">The capture/compare unit number.</param>
    /// <param name="value">The new control register value.</param>
private void HandleCaptureCompareControlChange(int unitNumber, ushort value)
    {
        CaptureCompareUnit unit = _captureCompareUnits[unitNumber];

        // Update capture/compare mode
        unit.Mode = (value & TAxCCTLn_CAP) != 0 ? CaptureCompareMode.Capture : CaptureCompareMode.Compare;

        // Update output mode (for compare mode)
        int outputModeField = (value & TAxCCTLn_OUTMOD_MASK) >> 5;
        unit.OutputMode = (OutputMode)outputModeField;

        // Update capture input select (for capture mode)
        int captureInputField = (value & TAxCCTLn_CCIS_MASK) >> 12;
        unit.CaptureInput = (CaptureInputSelect)captureInputField;

        // Update capture edge mode (for capture mode)
        int captureEdgeField = (value & TAxCCTLn_CM_MASK) >> 14;
        unit.CaptureEdgeMode = (CaptureEdgeMode)captureEdgeField;

        // Update synchronize capture source
        unit.SynchronizeCaptureSource = (value & TAxCCTLn_SCS) != 0;

        // Update interrupt enable
        unit.InterruptEnable = (value & TAxCCTLn_CCIE) != 0;

        // Update output value
        unit.OutputValue = (value & TAxCCTLn_OUT) != 0;

        // Handle software-initiated capture per SLAU445I Section 13.2.4.1.1
        // When CCIS is set to VCC/GND and toggled, it can trigger a capture
        if (unit.Mode == CaptureCompareMode.Capture &&
            (unit.CaptureInput == CaptureInputSelect.VCC || unit.CaptureInput == CaptureInputSelect.GND))
        {
            // Check if this is a transition that should trigger a capture
            CheckSoftwareCaptureTransition(unit);
        }

        Logger?.Debug($"Timer {_timerName} CCR{unitNumber} control updated: Mode={unit.Mode}, OutputMode={unit.OutputMode}, CaptureEdge={unit.CaptureEdgeMode}");

        // Handle COV bit clearing on write
        if ((value & TAxCCTLn_COV) == 0 && unit.CaptureOverflow)
        {
            unit.ClearCaptureOverflow();
            Logger?.Debug($"Timer {_timerName} CCR{unitNumber} COV flag cleared");
        }
    }

    /// <inheritdoc />
public override ushort ReadWord(ushort address)
    {
        ushort offset = (ushort)(address - BaseAddress);

        // Handle dynamic register values that need to be built from current state
        switch (offset)
        {
            case OffsetTAxR:
                // Update timer register with current value
                GetRegister(address)?.WriteWord(_timerValue);
                break;

            case OffsetTAxCCTL0:
            case OffsetTAxCCTL1:
            case OffsetTAxCCTL2:
                // Update control register with current unit state including COV
                int unitIndex = (offset - OffsetTAxCCTL0) / 2;
                if (unitIndex < _captureCompareUnits.Length)
                {
                    ushort controlValue = BuildCaptureCompareControlValue(unitIndex);
                    GetRegister(address)?.WriteWord(controlValue);
                }
                break;
        }

        return base.ReadWord(address);
    }

    /// <summary>
    /// Builds the current control register value for a capture/compare unit.
    /// </summary>
    /// <param name="unitNumber">The unit number.</param>
    /// <returns>The control register value with current flags.</returns>
private ushort BuildCaptureCompareControlValue(int unitNumber)
    {
        CaptureCompareUnit unit = _captureCompareUnits[unitNumber];
        ushort value = 0;

        // Build control value from current unit state
        if (unit.InterruptFlag)
        {
            value |= TAxCCTLn_CCIFG;
        }

        if (unit.CaptureOverflow)
        {
            value |= TAxCCTLn_COV;
        }

        if (unit.OutputValue)
        {
            value |= TAxCCTLn_OUT;
        }

        if (unit.CaptureCompareInput)
        {
            value |= TAxCCTLn_CCI;
        }

        if (unit.InterruptEnable)
        {
            value |= TAxCCTLn_CCIE;
        }

        value |= (ushort)((ushort)unit.OutputMode << 5);

        if (unit.Mode == CaptureCompareMode.Capture)
        {
            value |= TAxCCTLn_CAP;
        }

        if (unit.SynchronizedCaptureCompareInput)
        {
            value |= TAxCCTLn_SCCI;
        }

        if (unit.SynchronizeCaptureSource)
        {
            value |= TAxCCTLn_SCS;
        }

        value |= (ushort)((ushort)unit.CaptureInput << 12);
        value |= (ushort)((ushort)unit.CaptureEdgeMode << 14);

        return value;
    }

    /// <summary>
    /// Handles timer tick in up mode.
    /// </summary>
    /// <param name="rollover">Returns true if a rollover occurred.</param>
private void TickUpMode(out bool rollover)
    {
        rollover = false;
        ushort period = _captureCompareUnits[0].CaptureCompareValue;

        if (period == 0)
        {
            // If period is 0, timer counts to 0xFFFF
            if (_timerValue == 0xFFFF)
            {
                _timerValue = 0x0000;
                rollover = true;
            }
            else
            {
                _timerValue++;
            }
        }
        else
        {
            // According to SLAU445I Section 13.2.3.1: 
            // "When the timer value equals TAxCCR0, the timer restarts counting from zero"
            if (_timerValue == period)
            {
                _timerValue = 0x0000;
                rollover = true;
            }
            else
            {
                _timerValue++;
            }
        }
    }

    /// <summary>
    /// Handles timer tick in continuous mode.
    /// </summary>
    /// <param name="rollover">Returns true if a rollover occurred.</param>
private void TickContinuousMode(out bool rollover)
    {
        rollover = false;

        if (_timerValue == 0xFFFF)
        {
            _timerValue = 0x0000;
            rollover = true;
        }
        else
        {
            _timerValue++;
        }
    }

    /// <summary>
    /// Handles timer tick in up/down mode.
    /// According to SLAU445I Section 13.2.3.4: 
    /// - TAxCCR0 CCIFG is set when timer counts from TAxCCR0-1 to TAxCCR0
    /// - TAIFG is set when timer completes counting down from 0001h to 0000h
    /// </summary>
    /// <param name="rollover">Returns true if a rollover occurred.</param>
private void TickUpDownMode(out bool rollover)
    {
        rollover = false;
        ushort period = _captureCompareUnits[0].CaptureCompareValue;
        _lastTimerValue = _timerValue;

        if (period == 0)
        {
            _timerValue = 0x0000;
            return;
        }

        if (_isCountingUp)
        {
            // Timer counts up to TAxCCR0 then down
            if (_timerValue == period)
            {
                _isCountingUp = false;
                // Don't increment on the turn-around point, start counting down
                _timerValue--;
            }
            else
            {
                _timerValue++;

                // Check for TAxCCR0 CCIFG: set when counting from CCR0-1 to CCR0
                if (_lastTimerValue == (period - 1) && _timerValue == period)
                {
                    _captureCompareUnits[0].InterruptFlag = true;
                    if (_captureCompareUnits[0].InterruptEnable)
                    {
                        OnCaptureCompareInterrupt(_captureCompareUnits[0], new CaptureCompareInterruptEventArgs(0));
                    }
                }
            }
        }
        else
        {
            if (_timerValue == 0)
            {
                _isCountingUp = true;
                rollover = true;

                // TAIFG is set when counting down from 0001h to 0000h
                if (_lastTimerValue == 1 && _timerValue == 0)
                {
                    _interruptFlag = true;
                    if (_interruptEnable)
                    {
                        OnInterruptRequested(_interruptVector, $"{_timerName}_TAIFG", 1);
                    }
                }

                // Don't decrement below 0, start counting up
                _timerValue++;
            }
            else
            {
                _timerValue--;
            }
        }
    }

    /// <summary>
    /// Checks for software-initiated capture transitions according to SLAU445I Section 13.2.4.1.1.
    /// When CCIS is set to VCC or GND, toggling can trigger captures.
    /// </summary>
    /// <param name="unit">The capture/compare unit to check.</param>
private void CheckSoftwareCaptureTransition(CaptureCompareUnit unit)
    {
        bool newInputValue = unit.CaptureInput == CaptureInputSelect.VCC;
        bool oldInputValue = unit.CaptureCompareInput;

        // Update the current input value
        unit.CaptureCompareInput = newInputValue;

        // Check if this transition should trigger a capture based on edge mode
        bool triggerCapture = false;
        switch (unit.CaptureEdgeMode)
        {
            case CaptureEdgeMode.RisingEdge:
                triggerCapture = !oldInputValue && newInputValue;
                break;

            case CaptureEdgeMode.FallingEdge:
                triggerCapture = oldInputValue && !newInputValue;
                break;

            case CaptureEdgeMode.BothEdges:
                triggerCapture = oldInputValue != newInputValue;
                break;

            default: // CaptureEdgeMode.None or other values
                triggerCapture = false;
                break;
        }

        if (triggerCapture)
        {
            unit.HandleCaptureEvent(_timerValue);
            Logger?.Debug($"Timer {_timerName} software capture triggered on unit {unit.UnitNumber}");
        }
    }

    /// <summary>
    /// Handles capture/compare unit interrupt events.
    /// </summary>
    /// <param name="sender">The capture/compare unit that generated the interrupt.</param>
    /// <param name="e">The interrupt event arguments.</param>
private void OnCaptureCompareInterrupt(object? sender, CaptureCompareInterruptEventArgs e)
    {
        // Calculate interrupt vector based on unit number
        ushort vector = (ushort)(_interruptVector + (e.UnitNumber * 2));
        OnInterruptRequested(vector, $"{_timerName}_CCR{e.UnitNumber}", (byte)(2 + e.UnitNumber));

        // Update interrupt vector register
        PeripheralRegister? ivRegister = GetRegister((ushort)(BaseAddress + OffsetTAxIV));
        ivRegister?.WriteWord((ushort)(e.UnitNumber * 2));
    }

    /// <summary>
    /// Initializes a new instance of the TimerClock class.
    /// </summary>
    /// <param name="clockSource">The initial clock source.</param>
    /// <param name="inputDivider">The initial input divider.</param>
    /// <param name="sourceFrequency">The frequency of the clock source in Hz.</param>
public TimerClock(TimerClockSource clockSource = TimerClockSource.SMCLK,
                     TimerInputDivider inputDivider = TimerInputDivider.DivideBy1,
                     uint sourceFrequency = 1000000)
    {
        _clockSource = clockSource;
        _inputDivider = inputDivider;
        _sourceFrequency = sourceFrequency;
    }

    /// <summary>
    /// Calculates the time in microseconds for a given number of timer counts.
    /// </summary>
    /// <param name="counts">The number of timer counts.</param>
    /// <returns>The time in microseconds.</returns>
public double CountsToMicroseconds(uint counts)
    {
        return counts * PeriodMicroseconds;
    }

    /// <summary>
    /// Calculates the number of timer counts for a given time in microseconds.
    /// </summary>
    /// <param name="microseconds">The time in microseconds.</param>
    /// <returns>The number of timer counts.</returns>
public uint MicrosecondsToTimerCounts(double microseconds)
    {
        return microseconds > 0 ? (uint)(microseconds / PeriodMicroseconds) : 0;
    }

    /// <summary>
    /// Gets the numeric divider value for the current input divider setting.
    /// </summary>
    /// <returns>The divider value (1, 2, 4, or 8).</returns>
private uint GetDividerValue()
    {
        return _inputDivider switch
        {
            TimerInputDivider.DivideBy1 => 1,
            TimerInputDivider.DivideBy2 => 2,
            TimerInputDivider.DivideBy4 => 4,
            TimerInputDivider.DivideBy8 => 8,
            _ => 1
        };
    }

    /// <summary>
    /// Resets the clock configuration to default values.
    /// </summary>
public void Reset()
    {
        _clockSource = TimerClockSource.SMCLK;
        _inputDivider = TimerInputDivider.DivideBy1;
        _sourceFrequency = 1000000; // Default 1 MHz SMCLK
    }

public TimerATests()
    {
        _timer = new TimerA("TA0", 0x0340, 0xFFEC);
    }

[Fact]
        public void Constructor_WithValidParameters_InitializesCorrectly()
        {
            Assert.Equal("Timer_TA0", _timer.PeripheralId);
            Assert.Equal(0x0340, _timer.BaseAddress);
            Assert.Equal(0x0000, _timer.TimerValue);
            Assert.Equal(TimerMode.Stop, _timer.Mode);
        }

[Fact]
        public void Constructor_WithNullTimerName_ThrowsArgumentNullException()
        {
            ArgumentNullException exception = Assert.Throws<ArgumentNullException>(() =>
                new TimerA(null!, 0x0340, 0xFFEC));
            Assert.Equal("timerName", exception.ParamName);
        }

[Fact]
        public void CaptureCompareUnits_AfterConstruction_HasThreeUnits()
        {
            Assert.Equal(3, _timer.CaptureCompareUnits.Count);
        }

[Fact]
        public void Clock_AfterConstruction_HasDefaultConfiguration()
        {
            Assert.Equal(TimerClockSource.SMCLK, _timer.Clock.ClockSource);
            Assert.Equal(TimerInputDivider.DivideBy1, _timer.Clock.InputDivider);
            Assert.Equal(1000000U, _timer.Clock.SourceFrequency);
        }

[Fact]
        public void Tick_InStopMode_DoesNotIncrementTimer()
        {
            SetTimerMode(TimerMode.Stop);
            ushort initialValue = _timer.TimerValue;

            _timer.Tick();

            Assert.Equal(initialValue, _timer.TimerValue);
        }

[Fact]
        public void Tick_InUpModeWithPeriod100_CountsFromZeroTo100()
        {
            SetTimerMode(TimerMode.Up);
            _timer.CaptureCompareUnits[0].CaptureCompareValue = 100;

            for (int i = 0; i <= 100; i++)
            {
                Assert.Equal((ushort)i, _timer.TimerValue);
                _timer.Tick();
            }

            Assert.Equal(0, _timer.TimerValue); // Should roll over to 0
        }

[Fact]
        public void Tick_InContinuousMode_CountsToMaxValue()
        {
            SetTimerMode(TimerMode.Continuous);

            // Fast forward near the rollover point
            SetTimerValue(0xFFFE);

            _timer.Tick();
            Assert.Equal(0xFFFF, _timer.TimerValue);

            _timer.Tick();
            Assert.Equal(0x0000, _timer.TimerValue); // Should roll over
        }

[Fact]
        public void Tick_InUpDownModeWithPeriod10_CountsUpThenDown()
        {
            SetTimerMode(TimerMode.UpDown);
            _timer.CaptureCompareUnits[0].CaptureCompareValue = 10;

            // Count up to 10
            for (int i = 0; i <= 10; i++)
            {
                Assert.Equal((ushort)i, _timer.TimerValue);
                _timer.Tick();
            }

            // Count down to 0
            for (int i = 9; i >= 0; i--)
            {
                Assert.Equal((ushort)i, _timer.TimerValue);
                _timer.Tick();
            }

            Assert.Equal(1, _timer.TimerValue); // Should start counting up again
        }

[Fact]
        public void CaptureCompareUnit_InCompareMode_GeneratesInterruptOnMatch()
        {
            bool interruptRaised = false;
            _timer.CaptureCompareUnits[1].InterruptRequested += (s, e) => interruptRaised = true;

            _timer.CaptureCompareUnits[1].Mode = CaptureCompareMode.Compare;
            _timer.CaptureCompareUnits[1].CaptureCompareValue = 50;
            _timer.CaptureCompareUnits[1].InterruptEnable = true;

            SetTimerMode(TimerMode.Continuous);
            SetTimerValue(49);

            _timer.Tick(); // Should reach 50 and trigger interrupt

            Assert.True(interruptRaised);
            Assert.True(_timer.CaptureCompareUnits[1].InterruptFlag);
        }

[Fact]
        public void CaptureCompareUnit_InCaptureMode_CapturesTimerValue()
        {
            _timer.CaptureCompareUnits[1].Mode = CaptureCompareMode.Capture;
            SetTimerValue(0x1234);

            _timer.TriggerCaptureEvent(1);

            Assert.Equal(0x1234, _timer.CaptureCompareUnits[1].CaptureCompareValue);
            Assert.True(_timer.CaptureCompareUnits[1].InterruptFlag);
        }

[Fact]
        public void CaptureCompareUnit_MultipleCaptures_SetsCOVFlag()
        {
            _timer.CaptureCompareUnits[1].Mode = CaptureCompareMode.Capture;

            // First capture
            SetTimerValue(0x1000);
            _timer.TriggerCaptureEvent(1);
            Assert.False(_timer.CaptureCompareUnits[1].CaptureOverflow);

            // Second capture before reading first value - should set COV
            SetTimerValue(0x2000);
            _timer.TriggerCaptureEvent(1);
            Assert.True(_timer.CaptureCompareUnits[1].CaptureOverflow);
        }

[Fact]
        public void CaptureCompareUnit_ReadAfterCapture_ClearsCOVLogic()
        {
            _timer.CaptureCompareUnits[1].Mode = CaptureCompareMode.Capture;

            // First capture
            SetTimerValue(0x1000);
            _timer.TriggerCaptureEvent(1);

            // Read the captured value
            ushort capturedValue = _timer.CaptureCompareUnits[1].CaptureCompareValue;
            Assert.Equal(0x1000, capturedValue);

            // Second capture after reading - should NOT set COV
            SetTimerValue(0x2000);
            _timer.TriggerCaptureEvent(1);
            Assert.False(_timer.CaptureCompareUnits[1].CaptureOverflow);
        }

[Fact]
