[Fact]
        public void Reset_AfterModifyingState_RestoresToDefaults()
        {
            // Modify timer state
            SetTimerMode(TimerMode.Up);
            SetTimerValue(0x1234);
            _timer.InterruptFlag = true;
            _timer.CaptureCompareUnits[0].CaptureCompareValue = 500;
            _timer.CaptureCompareUnits[0].InterruptFlag = true;

            _timer.Reset();

            Assert.Equal(0x0000, _timer.TimerValue);
            Assert.Equal(TimerMode.Stop, _timer.Mode);
            Assert.False(_timer.InterruptFlag);
            Assert.Equal(0x0000, _timer.CaptureCompareUnits[0].CaptureCompareValue);
            Assert.False(_timer.CaptureCompareUnits[0].InterruptFlag);
        }

    /// <summary>
    /// Helper methods for test setup.
    /// </summary>
private void SetTimerMode(TimerMode mode)
    {
        // Simulate writing to the control register to set mode
        ushort controlValue = (ushort)((ushort)mode << 4);
        ushort controlAddress = (ushort)(_timer.BaseAddress + 0x00);

        // Use the peripheral's WriteWord method to properly trigger register change handling
        _timer.WriteWord(controlAddress, controlValue);
    }

private void SetTimerValue(ushort value)
    {
        // Use reflection to set the timer value directly for testing
        System.Reflection.FieldInfo? field = _timer.GetType().GetField("_timerValue",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        field?.SetValue(_timer, value);
    }

def run(self):
        cmd = [sys.executable, 'script.py', self.infile, self.outfile]
        if self.opts.get('mode'):
            cmd += ['--mode', self.opts['mode']]
        if self.opts.get('local_model'):
            cmd += ['--local-model', self.opts['local_model']]
        if self.opts.get('diarize'):
            cmd.append('--diarize')
        if self.opts.get('language'):
            cmd += ['--language', self.opts['language']]
        if self.opts.get('timestamps'):
            cmd.append('--timestamps')
        if self.opts.get('aggregate'):
            cmd.append('--aggregate')

        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        for line in proc.stdout:
            self.log.append(line)
        proc.wait()
        if proc.returncode == 0:
            self.status = 'done'
        else:
            self.status = 'error'
        self.log.append(f"[END] exit code {proc.returncode}\n")

def logs(job_id):
    job = JOBS.get(job_id)
    if not job:
        return jsonify({'error': 'job not found'}), 404
    data = {'status': job.status, 'log': ''.join(job.log)}
    if job.status == 'done':
        with open(job.outfile, 'r', encoding='utf-8') as fh:
            data['result'] = fh.read()
    return jsonify(data)

def download(job_id):
    job = JOBS.get(job_id)
    if not job or job.status != 'done':
        return 'Not ready', 404
    return send_file(job.outfile, as_attachment=True, download_name='transcript.txt')

