     * Compose object like this:
     * [
     *  {
     *    order_id: 1,
     *    created_at: '2022-01-01'
     *    customer_receive_time: '11:15'
     *    items: [
     *      {
     *        order_id: 1,
     *        name: "鶏唐揚弁当",
     *        price: 500,
     *        quantity:3
     *        created_at: '2022-01-01'
     *        customer_receive_time: '11:15'
     *      }
     *    ]
     *  }
     * ]
     */
    return rows.reduce((orders, item) => {
      const index = orders.findIndex(
        (order) => (order.order_id == item.order_id)
      );
      if (index >= 0) {
        orders[index].items.push(item);
      } else {
        orders.push({
