@Test
  public void testClearAll() {
    // Set up some scenarios
    ChaosScenarios.fullChaos();

    BugRegistry registry = BugRegistry.getInstance();
    assertTrue(registry.size() > 0, "Should have bugs registered");

    // Clear all
    ChaosScenarios.clearAll();

    assertEquals(0, registry.size(), "All bugs should be cleared");
  }

@Test
  public void testScenarioOverwrite() {
    // Set up one scenario
    ChaosScenarios.networkChaos();

    BugRegistry registry = BugRegistry.getInstance();
    int initialSize = registry.size();

    // Set up another scenario that might have overlapping bugs
    ChaosScenarios.storageChaos();

    // Size should increase (no overlapping bugs in these scenarios)
    assertTrue(registry.size() > initialSize, 
        "Adding another scenario should register more bugs");
  }

def get_vector_embedding(text):
    """Get vector embedding from Ollama"""
    if not text or len(text.strip()) == 0:
        return None

    try:
        payload = {
            "model": "llama3",
            "prompt": text
        }

        response = requests.post(
            "http://localhost:11434/api/embeddings",
            headers={"Content-Type": "application/json"},
            json=payload
        )

        if response.status_code == 200:
            result = response.json()
            return result.get("embedding", [])
        else:
            logger.error(f"Error getting vector embedding: {response.status_code} - {response.text}")
            return None
    except Exception as e:
        logger.error(f"Error getting vector embedding: {e}")
        return None

def get_vector_embedding(text):
    """Get vector embedding from Ollama"""
    if not text or len(text.strip()) == 0:
        return None

    max_retries = 3
    retry_delay = 2

    for retry in range(max_retries):
        try:
            payload = {
                "model": "llama3",
                "prompt": text
            }

            response = requests.post(
                "http://localhost:11434/api/embeddings",
                headers={"Content-Type": "application/json"},
                json=payload,
                timeout=30
            )

            if response.status_code == 200:
                result = response.json()
                embedding = result.get("embedding", [])
                if embedding:
                    return embedding
                else:
                    logger.error(f"Empty embedding returned (attempt {retry+1}/{max_retries})")
                    if retry < max_retries - 1:
                        time.sleep(retry_delay)
            else:
                logger.error(f"Error getting vector embedding: {response.status_code} - {response.text} (attempt {retry+1}/{max_retries})")
                if retry < max_retries - 1:
                    time.sleep(retry_delay)
        except Exception as e:
            logger.error(f"Exception getting vector embedding: {e} (attempt {retry+1}/{max_retries})")
            if retry < max_retries - 1:
                time.sleep(retry_delay)

    # If we get here, all retries failed
    return None

def determine_chunk_parameters(text_length):
    """Determine chunk size and overlap based on text length"""
    if text_length < 5000:
        return 800, 100  # Small documents
    elif text_length < 20000:
        return 1500, 200  # Medium documents
    else:
        return 2000, 300  # Large documents

def create_opinionchunks_index():
    """Create the opinionchunks index if it doesn't exist"""
    try:
        # Check if index exists
        response = requests.head("http://localhost:9200/opinionchunks")
        if response.status_code == 404:
            logger.info("Creating opinionchunks index...")

            # Create index mapping
            mapping = {
                "mappings": {
                    "properties": {
                        "id": {"type": "keyword"},
                        "opinion_id": {"type": "keyword"},
                        "chunk_index": {"type": "integer"},
                        "text": {"type": "text", "analyzer": "english"},
                        "case_name": {
                            "type": "text",
                            "fields": {"keyword": {"type": "keyword", "ignore_above": 256}}
                        },
                        "chunk_size": {"type": "integer"},
                        "chunk_overlap": {"type": "integer"},
                        "vectorized_at": {"type": "date"},
                        "vector_embedding": {
                            "type": "dense_vector",
                            "dims": 4096,
                            "index": true,
                            "similarity": "cosine"
                        }
                    }
                }
            }

            # Create the index
            response = requests.put(
                "http://localhost:9200/opinionchunks",
                json=mapping,
                headers={"Content-Type": "application/json"}
            )

            if response.status_code not in (200, 201):
                logger.error(f"Error creating opinionchunks index: {response.text}")
                return False

            logger.info("Successfully created opinionchunks index")
        return True
    except Exception as e:
        logger.error(f"Error checking/creating opinionchunks index: {e}")
        return False

