def run(self):
        total_images = sum(len(self._list_images(e.path)) for e in self.entries)
        processed = 0
        for entry in self.entries:
            images = self._list_images(entry.path)
            if self.mode == "total":
                quota = int(self.total_count * entry.percent / 100)
            else:
                quota = int(len(images) * entry.percent / 100)
            if quota > len(images):
                quota = len(images)
                self.message.emit(f"{entry.path}: using max available {quota} images")
            selected = random.sample(images, quota)
            for img in selected:
                base = os.path.basename(img)
                name, _ = os.path.splitext(base)
                caption_file = os.path.join(entry.path, name + ".txt")
                dest_img = os.path.join(self.dest, base)
                dest_caption = os.path.join(self.dest, name + ".txt")
                shutil.copy2(img, dest_img)
                if os.path.exists(caption_file):
                    shutil.copy2(caption_file, dest_caption)
                processed += 1
                if total_images:
                    self.progress.emit(int(processed / total_images * 100))
        self.finished.emit()

def _list_images(self, folder: str) -> List[str]:
        files = []
        for f in os.listdir(folder):
            ext = os.path.splitext(f)[1].lower()
            if ext in IMAGE_EXTENSIONS:
                files.append(os.path.join(folder, f))
        return files

def remove_folder(self):
        if self.list_layout.count() == 0:
            return
        item = self.list_layout.takeAt(self.list_layout.count() - 1)
        if item:
            widget = item.widget()
            widget.setParent(None)
            self.entries.pop()

def browse_dest(self):
        dest = QtWidgets.QFileDialog.getExistingDirectory(self, "Destination Folder")
        if dest:
            self.dest_edit.setText(dest)

def _load_settings(self):
        dest = self.settings.value("dest", "")
        self.dest_edit.setText(dest)

def closeEvent(self, event):
        self.settings.setValue("dest", self.dest_edit.text())
        super().closeEvent(event)

def print_rate_limit_info(analyzer):
    """Print current rate limit information."""
    try:
        rate_limit_info = analyzer.get_rate_limit_info()
        print(f"Rate limit remaining: [{rate_limit_info['remaining']}]/[{rate_limit_info['limit']}]")
        if rate_limit_info['time_until_reset_total_seconds'] > 0:
            print(f"Rate limit resets in: [{rate_limit_info['time_until_reset_minutes']}] minutes and [{rate_limit_info['time_until_reset_seconds']}] seconds")
        else:
            print("Rate limit has already reset")
    except Exception as e:
        print(f"Warning: Could not fetch rate limit info: [{e}]")

def apply_patches():
    """Apply necessary patches to make the libraries compatible"""
    print("Applying compatibility patches...")

    try:
        from huggingface_hub import constants
        if not hasattr(constants, 'HF_HUB_CACHE'):
            print("Adding missing HF_HUB_CACHE attribute to huggingface_hub.constants")
            constants.HF_HUB_CACHE = os.path.expanduser("~/.cache/huggingface/hub")
            print(f"Set HF_HUB_CACHE to: {constants.HF_HUB_CACHE}")
    except ImportError:
        print("Warning: Could not import huggingface_hub.constants")

    try:
        import torch.nn as nn
        original_conv2d_forward = nn.Conv2d.forward

        def patched_conv2d_forward(self, input, *args):
            """Patched Conv2d forward to handle extra arguments from peft"""
            return original_conv2d_forward(self, input)

        nn.Conv2d.forward = patched_conv2d_forward
        print("Patched torch.nn.Conv2d.forward to handle extra arguments from peft")
    except Exception as e:
        print(f"Warning: Failed to patch Conv2d.forward: {e}")

    print("Patches applied successfully")

def patched_conv2d_forward(self, input, *args):
            """Patched Conv2d forward to handle extra arguments from peft"""
            return original_conv2d_forward(self, input)

def build_extension():
    """Build the pylatro extension"""
    print("Building pylatro extension...")

    pylatro_dir = os.path.join(os.path.dirname(__file__), "pylatro")

    try:
        result = subprocess.run([
            "maturin", "develop", "--release"
        ], cwd=pylatro_dir, capture_output=True, text=True, timeout=120)

        if result.returncode == 0:
            print("✅ Extension built successfully")
            return True
        else:
            print(f"❌ Build failed: {result.stderr}")
            return False

    except subprocess.TimeoutExpired:
        print("❌ Build timed out")
        return False
    except FileNotFoundError:
        print("❌ maturin not found. Please install with: pip install maturin")
        return False
    except Exception as e:
        print(f"❌ Build error: {e}")
        return False

def benchmark_creation_performance():
    """Benchmark game creation performance"""
    print("\n=== Game Creation Performance ===")

    batch_sizes = [10, 50, 100, 500, 1000, 2000]
    results = {}

    for batch_size in batch_sizes:
        print(f"Testing batch size: {batch_size}")

        try:
            start_time = time.time()
            batch = pylatro.BatchGameEngine(batch_size)
            creation_time = time.time() - start_time

            games_per_sec = batch_size / creation_time
            results[batch_size] = {
                'creation_time': creation_time,
                'games_per_sec': games_per_sec,
                'success': True
            }

            print(f"  ✅ {creation_time:.3f}s ({games_per_sec:.0f} games/sec)")

        except Exception as e:
            print(f"  ❌ Failed: {e}")
            results[batch_size] = {'success': False, 'error': str(e)}

    return results

def benchmark_memory_usage():
    """Benchmark memory usage scaling"""
    print("\n=== Memory Usage Scaling ===")

    batch_sizes = [100, 500, 1000, 2000, 5000]
    results = {}

    for batch_size in batch_sizes:
        print(f"Testing batch size: {batch_size}")

        try:
            batch = pylatro.BatchGameEngine(batch_size)
            stats = batch.get_batch_stats()

            memory_mb = stats['memory_usage_mb']
            memory_per_game = memory_mb / batch_size * 1024  # KB per game

            results[batch_size] = {
                'total_memory_mb': memory_mb,
                'memory_per_game_kb': memory_per_game,
                'success': True
            }

            print(f"  ✅ {memory_mb} MB total ({memory_per_game:.1f} KB/game)")

        except Exception as e:
            print(f"  ❌ Failed: {e}")
            results[batch_size] = {'success': False, 'error': str(e)}

    return results

def get_batch_action_spaces(self) -> np.ndarray:
        """
        Get action spaces for all games as 2D NumPy array

        Returns:
            2D array of shape (batch_size, action_space_size)
        """
        action_spaces = self.batch_engine.batch_gen_action_spaces()

        if not action_spaces:
            return np.array([])

        # Convert to NumPy 2D array
        return np.array(action_spaces, dtype=np.int32)

def _call(
        self,
        prompt: str,
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> str:
        """Call the DeepSeek API."""
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }

        payload = {
            "model": self.model_name,
            "messages": [
                {"role": "user", "content": prompt}
            ],
            "temperature": self.temperature,
            "max_tokens": self.max_tokens
        }

        if stop:
            payload["stop"] = stop

        try:
            response = requests.post(
                "https://api.deepseek.com/v1/chat/completions",
                headers=headers, 
                json=payload
            )

            if response.status_code != 200:
                raise ValueError(f"Error from DeepSeek API: {response.text}")

            return response.json()["choices"][0]["message"]["content"]
        except Exception as e:
            raise ValueError(f"Error calling DeepSeek API: {str(e)}")

def extract_content(html):
    """提取页面主要内容"""
    soup = BeautifulSoup(html, "html.parser")
    content_area = soup.select_one(".doc-content, .main-content, article, .content")

    if content_area:
        return content_area.get_text(separator="\n")

    body = soup.body
    if body:
        return body.get_text(separator="\n")

    return ""

