() => {
  const router = useRouter();
  const [userSession, setUserSessionState] = useState(null);
  const [subscriptionStatus, setSubscriptionStatus] = useState(null);
  const [remainingUsage, setRemainingUsage] = useState(null);
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [email, setEmail] = useState('');
  const [isCheckingSubscription, setIsCheckingSubscription] = useState(false);
  const [isCreatingCheckout, setIsCreatingCheckout] = useState(false);
  const [checkoutError, setCheckoutError] = useState(null);

  useEffect(() => {
    loadUserData();
    checkUrlParams();
  }, []);

  const checkUrlParams = () => {
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('success')) {
      // Payment successful
      setTimeout(() => {
        alert('🎉 Payment successful! Your subscription is now active.');
        loadUserData(); // Refresh subscription status
        router.replace('/account'); // Remove URL params
      }, 500);
    } else if (urlParams.get('canceled')) {
      // Payment canceled
      setTimeout(() => {
        alert('Payment was canceled. You can try again anytime!');
        router.replace('/account'); // Remove URL params
      }, 500);
    }
  };

  const loadUserData = async () => {
    setIsCheckingSubscription(true);

    try {
      const session = await getUserSessionWithStripe();
      const status = await getSubscriptionStatus(session?.email);
      const usage = await getRemainingUsage(session?.email);

      setUserSessionState(session);
      setSubscriptionStatus(status);
      setRemainingUsage(usage);
    } catch (error) {
      console.error('Error loading user data:', error);
    } finally {
      setIsCheckingSubscription(false);
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!email.trim()) {
      alert('Please enter your email address');
      return;
    }

    setIsLoggingIn(true);

    // Simulate login delay
    setTimeout(async () => {
      setUserSession({
        isLoggedIn: true,
        email: email.trim(),
      });
      await loadUserData();
      setIsLoggingIn(false);
    }, 1000);
  };

  const handleLogout = () => {
    clearUserSession();
    setEmail('');
    setUserSessionState(null);
    setSubscriptionStatus(null);
    setRemainingUsage(null);
    router.push('/');
  };

  const handleUpgrade = async (plan) => {
    if (!userSession?.isLoggedIn) {
      alert('Please log in first to upgrade your plan');
      return;
    }

    if (subscriptionStatus?.plan === plan) {
      alert('You already have this plan!');
      return;
    }

    setIsCreatingCheckout(true);
    setCheckoutError(null);

    try {
      const checkoutUrl = await createStripeCheckout(plan, userSession.email);

      // Redirect to Stripe Checkout
      window.location.href = checkoutUrl;
    } catch (error) {
      console.error('Error creating checkout session:', error);
      setCheckoutError(error.message);
    } finally {
      setIsCreatingCheckout(false);
    }
  };

  const plans = [
    {
      name: 'Free',
      price: '$0',
      period: 'forever',
      features: [
        '10 excuses per session',
        'All 4 tones available',
        'Save & copy excuses',
        'Email sharing',
      ],
      limitations: [
        'Limited daily usage',
        'No priority support',
      ],
      current: subscriptionStatus?.plan === 'free',
      buttonText: 'Current Plan',
      disabled: true,
    },
    {
      name: 'Pro',
      price: '$4.99',
      period: 'per month',
      features: [
        'Unlimited excuse generation',
        'All tones & future updates',
        'Advanced customization',
        'Priority support',
        'Export to multiple formats',
        'Custom tone training',
      ],
      limitations: [],
      current: subscriptionStatus?.plan === 'pro',
      buttonText: subscriptionStatus?.plan === 'pro' ? 'Current Plan' : 'Upgrade to Pro',
      disabled: subscriptionStatus?.plan === 'pro' || subscriptionStatus?.plan === 'lifetime',
      onUpgrade: () => handleUpgrade('pro'),
      popular: true,
    },
    {
      name: 'Lifetime',
      price: '$19.99',
      period: 'one-time',
      features: [
        'Everything in Pro',
        'Lifetime access',
        'Future feature access',
        'Premium support',
        'Early access to new tools',
        'Commercial usage rights',
      ],
      limitations: [],
      current: subscriptionStatus?.plan === 'lifetime',
      buttonText: subscriptionStatus?.plan === 'lifetime' ? 'Current Plan' : 'Get Lifetime',
      disabled: subscriptionStatus?.plan === 'lifetime',
      onUpgrade: () => handleUpgrade('lifetime'),
      bestValue: true,
    },
  ];

  return (
    <div className="flex-1 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold mb-6">
            <span className="neon-text-pink">Account</span>
            <br />
            <span className="neon-text-blue glitch-text" data-text="MANAGEMENT">
              MANAGEMENT
            </span>
          </h1>
          <p className="text-xl text-gray-300 max-w-2xl mx-auto">
            Manage your account, subscription, and excuse preferences.
          </p>
        </div>

        {!userSession?.isLoggedIn ? (
          // Login Form
          <div className="max-w-md mx-auto">
            <div className="card-glow p-8">
              <h2 className="text-2xl font-bold neon-text-green mb-6 text-center">
                Sign In to Your Account
              </h2>
              <form onSubmit={handleLogin} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">
                    Email Address
                  </label>
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="your@email.com"
                    className="w-full px-4 py-3 bg-gray-900 border border-gray-700 rounded-lg text-white placeholder-gray-500 focus:border-neon-pink focus:outline-none"
                    required
                  />
                </div>
                <button
                  type="submit"
                  disabled={isLoggingIn}
                  className={`w-full neon-button text-neon-pink flex items-center justify-center space-x-2 ${
                    isLoggingIn ? 'opacity-50 cursor-not-allowed' : ''
                  }`}
                >
                  <LogIn size={20} />
                  <span>{isLoggingIn ? 'Signing In...' : 'Sign In'}</span>
                </button>
              </form>
              <p className="text-center text-sm text-gray-400 mt-4">
                Enter any email to access your account and subscription features.
              </p>
            </div>
          </div>
        ) : (
          // Account Dashboard
          <div className="space-y-8">
            {/* User Info */}
            <div className="card-glow p-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-4">
                  <div className="w-12 h-12 bg-neon-pink bg-opacity-20 rounded-full flex items-center justify-center">
                    <User className="text-neon-pink" size={24} />
                  </div>
                  <div>
