async function handler(req, res) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    res.status(405).end('Method Not Allowed');
    return;
  }

  try {
    const { priceId, email, plan } = req.body;

    // Validate required fields
    if (!priceId || !email || !plan) {
      return res.status(400).json({ 
        error: 'Missing required fields: priceId, email, and plan are required' 
      });
    }

    // Validate plan type
    if (!['pro', 'lifetime'].includes(plan)) {
      return res.status(400).json({ 
        error: 'Invalid plan type. Must be "pro" or "lifetime"' 
      });
    }

    // Validate price ID matches plan
    const expectedPriceId = STRIPE_CONFIG.products[plan].priceId;
    if (priceId !== expectedPriceId) {
      return res.status(400).json({ 
        error: 'Price ID does not match the selected plan' 
      });
    }

    // Check if customer already exists
    let customer = await getCustomerByEmail(email);
    const customerId = customer?.id || null;

    // Create checkout session
    const session = await createCheckoutSession(priceId, customerId);

    res.status(200).json({ 
      sessionId: session.id,
      url: session.url 
    });

  } catch (error) {
    console.error('Error creating checkout session:', error);
    res.status(500).json({ 
      error: 'Failed to create checkout session',
      details: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
}

async function handler(req, res) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    res.status(405).end('Method Not Allowed');
    return;
  }

  try {
    const { email } = req.body;

    if (!email) {
      return res.status(400).json({ 
        error: 'Email is required' 
      });
    }

    // Find customer by email
    const customer = await getCustomerByEmail(email);

    if (!customer) {
      // Customer doesn't exist, they're on free plan
      return res.status(200).json({
        plan: 'free',
        status: 'inactive',
        currentPeriodEnd: null,
        cancelAtPeriodEnd: false,
        customerId: null,
      });
    }

    // Get subscription status for existing customer
    const subscriptionStatus = await getSubscriptionStatus(customer.id);

    res.status(200).json({
      ...subscriptionStatus,
      customerId: customer.id,
      customerEmail: customer.email,
    });

  } catch (error) {
    console.error('Error checking subscription status:', error);
    res.status(500).json({ 
      error: 'Failed to check subscription status',
      details: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
}

async function handler(req, res) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    res.status(405).end('Method Not Allowed');
    return;
  }

  const buf = await buffer(req);
  const sig = req.headers['stripe-signature'];
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  let event;

  try {
    event = stripe.webhooks.constructEvent(buf, sig, webhookSecret);
  } catch (err) {
    console.error('Webhook signature verification failed:', err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  console.log('Stripe webhook event received:', event.type);

  try {
    switch (event.type) {
      case WEBHOOK_EVENTS.CHECKOUT_SESSION_COMPLETED:
        await handleCheckoutSessionCompleted(event.data.object);
        break;

      case WEBHOOK_EVENTS.CUSTOMER_SUBSCRIPTION_CREATED:
        await handleSubscriptionCreated(event.data.object);
        break;

      case WEBHOOK_EVENTS.CUSTOMER_SUBSCRIPTION_UPDATED:
        await handleSubscriptionUpdated(event.data.object);
        break;

      case WEBHOOK_EVENTS.CUSTOMER_SUBSCRIPTION_DELETED:
        await handleSubscriptionDeleted(event.data.object);
        break;

      case WEBHOOK_EVENTS.INVOICE_PAYMENT_SUCCEEDED:
        await handleInvoicePaymentSucceeded(event.data.object);
        break;

      case WEBHOOK_EVENTS.INVOICE_PAYMENT_FAILED:
        await handleInvoicePaymentFailed(event.data.object);
        break;

      default:
        console.log(`Unhandled event type: ${event.type}`);
    }

    res.json({ received: true });
  } catch (error) {
    console.error('Error processing webhook:', error);
    res.status(500).json({ error: 'Webhook processing failed' });
  }
}

async function handleCheckoutSessionCompleted(session) {
  console.log('Checkout session completed:', session.id);

  const customerId = session.customer;
