                className="w-full p-4 bg-gray-900 border-2 border-gray-700 rounded-lg text-white placeholder-gray-500 focus:border-neon-pink focus:outline-none transition-colors resize-none"
                rows="4"
                maxLength="500"
                disabled={!canGenerate}
              />
              <div className="flex justify-between items-center text-sm">
                <span className="text-gray-500">
                  Be specific for better results!
                </span>
                <span className="text-gray-500">
                  {userInput.length}/500
                </span>
              </div>
            </div>
          </div>

          {/* Tone Selection */}
          <div className="card-glow p-8">
            <ToneSelector
              selectedTone={selectedTone}
              onToneChange={setSelectedTone}
            />
            {!canGenerate && (
              <div className="mt-4 p-3 bg-gray-800 rounded-lg">
                <p className="text-sm text-gray-400">
                  🔒 Tone selection is disabled. Please upgrade to continue generating excuses.
                </p>
              </div>
            )}
          </div>

          {/* Generate Button */}
          <div className="text-center">
            <button
              onClick={handleGenerate}
              disabled={isGenerating || !canGenerate || userInput.trim().length < 3 || isLoadingStatus}
              className={`neon-button text-neon-pink text-xl px-8 py-4 flex items-center space-x-3 mx-auto ${
                (isGenerating || !canGenerate || userInput.trim().length < 3 || isLoadingStatus)
                  ? 'opacity-50 cursor-not-allowed'
                  : 'hover:scale-105 transform transition-all duration-300'
              }`}
            >
              <Send size={24} />
              <span>
                {isGenerating ? 'Generating Your Excuse...' : 'Generate My Sorry'}
              </span>
            </button>

            {!canGenerate && !isLoadingStatus && (
              <p className="text-sm text-gray-500 mt-3">
                Upgrade your plan to continue generating excuses
              </p>
            )}
          </div>

          {/* Tips */}
          <div className="card-glow p-6">
            <h3 className="text-lg font-bold neon-text-blue mb-4">💡 Pro Tips</h3>
            <ul className="space-y-2 text-gray-300">
              <li>• Be specific about your situation for more personalized excuses</li>
              <li>• Try different tones to see what fits your personality</li>
              <li>• Save your favorites for future use</li>
              <li>• Email excuses directly to friends (if you dare!)</li>
              {subscriptionStatus?.plan === 'free' && (
                <li className="text-neon-pink">• Upgrade to Pro for unlimited excuse generation 🚀</li>
              )}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

