() => {
  const [savedExcuses, setSavedExcuses] = useState([]);
  const [filteredExcuses, setFilteredExcuses] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedToneFilter, setSelectedToneFilter] = useState('all');
  const [sortBy, setSortBy] = useState('newest');

  useEffect(() => {
    loadSavedExcuses();
  }, []);

  useEffect(() => {
    filterAndSortExcuses();
  }, [savedExcuses, searchTerm, selectedToneFilter, sortBy]);

  const loadSavedExcuses = () => {
    const excuses = getSavedExcuses();
    setSavedExcuses(excuses);
  };

  const filterAndSortExcuses = () => {
    let filtered = [...savedExcuses];

    // Filter by search term
    if (searchTerm.trim()) {
      filtered = filtered.filter(excuse =>
        excuse.text.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Filter by tone
    if (selectedToneFilter !== 'all') {
      filtered = filtered.filter(excuse => excuse.tone === selectedToneFilter);
    }

    // Sort excuses
    filtered.sort((a, b) => {
      switch (sortBy) {
        case 'newest':
          return new Date(b.savedAt) - new Date(a.savedAt);
        case 'oldest':
          return new Date(a.savedAt) - new Date(b.savedAt);
        case 'tone':
          return a.tone.localeCompare(b.tone);
        default:
          return 0;
      }
    });

    setFilteredExcuses(filtered);
  };

  const handleDeleteExcuse = (excuseId) => {
    setSavedExcuses(prev => prev.filter(excuse => excuse.id !== excuseId));
  };

  const handleClearAll = () => {
    if (window.confirm('Are you sure you want to delete all saved excuses? This action cannot be undone.')) {
      clearAllSavedExcuses();
      setSavedExcuses([]);
    }
  };

  const getStatsText = () => {
    const totalCount = savedExcuses.length;
    const toneStats = availableTones.reduce((acc, tone) => {
      acc[tone] = savedExcuses.filter(excuse => excuse.tone === tone).length;
      return acc;
    }, {});

    return { totalCount, toneStats };
  };

  const { totalCount, toneStats } = getStatsText();

  return (
    <div className="flex-1 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold mb-6">
            <span className="neon-text-pink">Saved</span>
            <br />
            <span className="neon-text-blue glitch-text" data-text="EXCUSES">
              EXCUSES
            </span>
          </h1>
          <p className="text-xl text-gray-300 max-w-2xl mx-auto">
            Your collection of perfectly crafted excuses, ready for any situation.
          </p>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
          <div className="card-glow p-4 text-center">
            <div className="text-2xl font-bold neon-text-pink">{totalCount}</div>
            <div className="text-sm text-gray-400">Total Saved</div>
          </div>
          {availableTones.map((tone) => (
            <div key={tone} className="card-glow p-4 text-center">
              <div className={`text-2xl font-bold text-${getToneColor(tone)}`}>
                {toneStats[tone] || 0}
              </div>
              <div className="text-sm text-gray-400 capitalize">{tone}</div>
            </div>
          ))}
        </div>

        {totalCount === 0 ? (
          // Empty State
          <div className="text-center py-20">
            <div className="text-6xl mb-6">📝</div>
            <h2 className="text-2xl font-bold neon-text-yellow mb-4">
              No Saved Excuses Yet
            </h2>
            <p className="text-gray-400 mb-8 max-w-md mx-auto">
              Start generating excuses and save your favorites for future use. 
              You'll never be caught without the perfect response!
            </p>
            <Link
              href="/generate"
              className="neon-button text-neon-pink inline-flex items-center space-x-2"
            >
              <Plus size={20} />
              <span>Generate Your First Excuse</span>
            </Link>
          </div>
        ) : (
          <>
            {/* Filters and Search */}
            <div className="card-glow p-6 mb-8">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Search */}
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                  <input
                    type="text"
                    placeholder="Search excuses..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 bg-gray-900 border border-gray-700 rounded-lg text-white placeholder-gray-500 focus:border-neon-pink focus:outline-none"
                  />
                </div>

                {/* Tone Filter */}
                <select
                  value={selectedToneFilter}
                  onChange={(e) => setSelectedToneFilter(e.target.value)}
                  className="px-4 py-2 bg-gray-900 border border-gray-700 rounded-lg text-white focus:border-neon-blue focus:outline-none"
                >
                  <option value="all">All Tones</option>
                  {availableTones.map((tone) => (
                    <option key={tone} value={tone} className="capitalize">
                      {tone}
                    </option>
                  ))}
                </select>

                {/* Sort */}
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="px-4 py-2 bg-gray-900 border border-gray-700 rounded-lg text-white focus:border-neon-green focus:outline-none"
                >
                  <option value="newest">Newest First</option>
                  <option value="oldest">Oldest First</option>
                  <option value="tone">Sort by Tone</option>
                </select>
              </div>

              <div className="flex justify-between items-center mt-4">
                <p className="text-gray-400">
                  Showing {filteredExcuses.length} of {totalCount} excuses
                </p>
                {totalCount > 0 && (
                  <button
                    onClick={handleClearAll}
                    className="text-red-400 hover:text-red-300 flex items-center space-x-1 text-sm transition-colors"
                  >
                    <Trash2 size={16} />
                    <span>Clear All</span>
                  </button>
                )}
              </div>
            </div>

            {/* Excuses Grid */}
            {filteredExcuses.length === 0 ? (
              <div className="text-center py-12">
                <div className="text-4xl mb-4">🔍</div>
                <h3 className="text-xl font-bold neon-text-yellow mb-2">
                  No Excuses Found
                </h3>
                <p className="text-gray-400">
                  Try adjusting your search or filter criteria.
                </p>
              </div>
            ) : (
              <div className="space-y-6">
                {filteredExcuses.map((excuse) => (
                  <ExcuseCard
                    key={excuse.id}
                    excuse={excuse}
                    isSaved={true}
                    showDelete={true}
                    onDelete={handleDeleteExcuse}
                  />
                ))}
              </div>
            )}

            {/* Action Buttons */}
            <div className="text-center mt-12">
              <Link
                href="/generate"
                className="neon-button text-neon-green inline-flex items-center space-x-2 mr-4"
              >
                <Plus size={20} />
                <span>Generate More Excuses</span>
              </Link>
            </div>
          </>
        )}

        {/* Tips */}
        <div className="card-glow p-6 mt-12">
          <h3 className="text-lg font-bold neon-text-blue mb-4">💡 Pro Tips</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-gray-300">
            <div>
              <p className="font-semibold mb-2">🔖 Organization</p>
              <p className="text-sm">Use different tones for different situations. Sassy for friends, Empathetic for family!</p>
            </div>
            <div>
              <p className="font-semibold mb-2">📱 Quick Access</p>
              <p className="text-sm">Save this page as a bookmark for instant access to your excuse arsenal.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

