// Helper function to get random item from array
(array) => {
  return array[Math.floor(Math.random() * array.length)];
}

// Helper function to process excuse text
(template, userExcuse) => {
  // If user provided specific excuse, use it; otherwise use random scenario
  const excuse = userExcuse.trim() || getRandomItem(excuseScenarios);
  return template.replace('{excuse}', excuse);
}

// Main excuse generation function
(userInput, tone, count = 3) => {
  const templates = excuseTemplates[tone] || excuseTemplates.sassy;
  const excuses = [];

  // Generate unique excuses
  const usedTemplates = new Set();

  while (excuses.length < count && usedTemplates.size < templates.length) {
    const template = getRandomItem(templates);

    if (!usedTemplates.has(template)) {
      usedTemplates.add(template);
      const processedExcuse = processExcuseText(template, userInput);
      excuses.push({
        id: Date.now() + Math.random(),
        text: processedExcuse,
        tone: tone,
        createdAt: new Date().toISOString(),
      });
    }
  }

  return excuses;
}

