// Mock subscription upgrade (for local demo)
(plan) => {
  const now = new Date();
  const expiry = new Date();

  if (plan === 'pro') {
    expiry.setMonth(expiry.getMonth() + 1); // 1 month
  } else if (plan === 'lifetime') {
    expiry.setFullYear(expiry.getFullYear() + 100); // 100 years (lifetime)
  }

  return updateSubscriptionStatus({
    plan: plan,
    subscriptionDate: now.toISOString(),
    expiryDate: expiry.toISOString(),
    usageCount: 0, // Reset usage count
    maxUsage: plan === 'free' ? 10 : Infinity,
  });
}

() => {
  if (!stripePromise) {
    stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY);
  }
  return stripePromise;
}

// Helper function to create checkout session
async (priceId, customerId = null) => {
  const sessionConfig = {
    payment_method_types: ['card'],
    line_items: [
      {
        price: priceId,
        quantity: 1,
      },
    ],
    mode: priceId === STRIPE_CONFIG.products.lifetime.priceId ? 'payment' : 'subscription',
    success_url: STRIPE_CONFIG.successUrl,
    cancel_url: STRIPE_CONFIG.cancelUrl,
    metadata: {
      productType: priceId === STRIPE_CONFIG.products.lifetime.priceId ? 'lifetime' : 'pro',
    },
  };

  if (customerId) {
    sessionConfig.customer = customerId;
  } else {
    sessionConfig.customer_creation = 'always';
  }

  return await stripe.checkout.sessions.create(sessionConfig);
}

// Helper function to get customer by email
async (email) => {
  const customers = await stripe.customers.list({
    email: email,
    limit: 1,
  });
  return customers.data[0] || null;
}

// Helper function to get subscription status
async (customerId) => {
  try {
    const subscriptions = await stripe.subscriptions.list({
      customer: customerId,
      status: 'active',
      limit: 1,
    });

    if (subscriptions.data.length > 0) {
      const subscription = subscriptions.data[0];
      return {
        status: 'active',
        plan: 'pro',
        currentPeriodEnd: new Date(subscription.current_period_end * 1000),
        cancelAtPeriodEnd: subscription.cancel_at_period_end,
      };
    }

    // Check for lifetime purchases (one-time payments)
    const payments = await stripe.paymentIntents.list({
      customer: customerId,
      limit: 10,
    });

    const lifetimePayment = payments.data.find(
      payment => payment.status === 'succeeded' && 
      payment.metadata?.productType === 'lifetime'
    );

    if (lifetimePayment) {
      return {
        status: 'active',
        plan: 'lifetime',
        currentPeriodEnd: null, // Lifetime doesn't expire
        cancelAtPeriodEnd: false,
      };
    }

    return {
      status: 'inactive',
      plan: 'free',
      currentPeriodEnd: null,
      cancelAtPeriodEnd: false,
    };
  } catch (error) {
    console.error('Error getting subscription status:', error);
    return {
      status: 'inactive',
      plan: 'free',
      currentPeriodEnd: null,
      cancelAtPeriodEnd: false,
    };
  }
}

// Check subscription status via API
async (email) => {
  if (!email) return null;

  try {
    const response = await fetch('/api/subscription-status', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email }),
    });

    if (!response.ok) {
      throw new Error('Failed to check subscription status');
    }

    const subscriptionData = await response.json();
    return subscriptionData;
  } catch (error) {
    console.error('Error checking Stripe subscription:', error);
    return null;
  }
}

// Enhanced user session with Stripe data
async () => {
  const localSession = getLocalUserSession();

  if (!localSession?.isLoggedIn || !localSession?.email) {
    return localSession;
  }

  // Check Stripe subscription status
  const stripeData = await checkStripeSubscriptionStatus(localSession.email);

  if (stripeData) {
    return {
      ...localSession,
      stripe: stripeData,
      subscriptionPlan: stripeData.plan,
      subscriptionStatus: stripeData.status,
      customerId: stripeData.customerId,
    };
  }

  return localSession;
}

// Enhanced subscription status with Stripe integration
async (email = null) => {
  const session = getLocalUserSession();
  const userEmail = email || session?.email;

  if (!userEmail) {
    // Return default free plan for non-authenticated users
    return {
      plan: 'free',
      status: 'inactive',
      usageCount: 0,
      maxUsage: 10,
      isStripeCustomer: false,
    };
  }

  // Check Stripe subscription
  const stripeData = await checkStripeSubscriptionStatus(userEmail);

  if (stripeData && stripeData.plan !== 'free') {
    return {
      plan: stripeData.plan,
      status: stripeData.status,
      currentPeriodEnd: stripeData.currentPeriodEnd,
      cancelAtPeriodEnd: stripeData.cancelAtPeriodEnd,
      usageCount: 0, // Pro/Lifetime users have unlimited usage
      maxUsage: Infinity,
      isStripeCustomer: true,
      customerId: stripeData.customerId,
    };
  }

  // Fall back to local storage for free users
  const localStorageKey = 'sorry_not_sorry_subscription';
  const localData = localStorage.getItem(localStorageKey);

  if (localData) {
    try {
      const parsed = JSON.parse(localData);
      return {
        ...parsed,
        isStripeCustomer: false,
      };
    } catch {
      // Handle corrupted data
    }
  }

  // Default free plan
  const defaultSubscription = {
    plan: 'free',
    status: 'inactive',
    usageCount: 0,
    maxUsage: 10,
    isStripeCustomer: false,
  };

  localStorage.setItem(localStorageKey, JSON.stringify(defaultSubscription));
  return defaultSubscription;
}

// Check if user can generate excuse (with Stripe integration)
async (email = null) => {
  const status = await getSubscriptionStatus(email);

  if (status.plan === 'pro' || status.plan === 'lifetime') {
    return true;
  }

  return status.usageCount < status.maxUsage;
}

// Increment usage count (only for free users)
async (email = null) => {
  const status = await getSubscriptionStatus(email);

  // Don't increment for paid users
  if (status.isStripeCustomer && status.plan !== 'free') {
    return status;
  }

  // Increment local storage counter for free users
  const updatedStatus = {
    ...status,
    usageCount: status.usageCount + 1,
  };

  const localStorageKey = 'sorry_not_sorry_subscription';
  localStorage.setItem(localStorageKey, JSON.stringify(updatedStatus));

  return updatedStatus;
}

// Get remaining usage count
async (email = null) => {
  const status = await getSubscriptionStatus(email);

  if (status.plan === 'pro' || status.plan === 'lifetime') {
    return 'unlimited';
  }

  return Math.max(0, status.maxUsage - status.usageCount);
}

// Create Stripe checkout session
async (plan, email) => {
  if (!plan || !email) {
    throw new Error('Plan and email are required');
  }

  const priceIds = {
    pro: process.env.NEXT_PUBLIC_STRIPE_PRO_PRICE_ID,
    lifetime: process.env.NEXT_PUBLIC_STRIPE_LIFETIME_PRICE_ID,
  };

  const priceId = priceIds[plan];
  if (!priceId) {
    throw new Error('Invalid plan selected');
  }

  try {
    const response = await fetch('/api/create-checkout-session', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        priceId,
        email,
        plan,
      }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || 'Failed to create checkout session');
    }

    const { url } = await response.json();
    return url;
  } catch (error) {
    console.error('Error creating checkout session:', error);
    throw error;
  }
}

