// Helper function to format milestones response
func formatMilestonesResponse(milestones []*github.Milestone) string {
	if len(milestones) == 0 {
		return "No milestones found."
	}

	result := fmt.Sprintf("Found %d milestones:\n\n", len(milestones))
	for _, milestone := range milestones {
		result += fmt.Sprintf("- **%s** (#%d)\n", milestone.GetTitle(), milestone.GetNumber())
		result += fmt.Sprintf("  - State: %s\n", milestone.GetState())
		result += fmt.Sprintf("  - Description: %s\n", milestone.GetDescription())
		result += fmt.Sprintf("  - Open Issues: %d\n", milestone.GetOpenIssues())
		result += fmt.Sprintf("  - Closed Issues: %d\n", milestone.GetClosedIssues())
		if milestone.DueOn != nil {
			result += fmt.Sprintf("  - Due: %s\n", milestone.DueOn.Format("2006-01-02 15:04:05"))
		}
		result += fmt.Sprintf("  - URL: %s\n\n", milestone.GetHTMLURL())
	}
	return result
}

// Helper function to format single milestone response
func formatMilestoneResponse(milestone *github.Milestone) string {
	result := fmt.Sprintf("Created milestone: **%s** (#%d)\n", milestone.GetTitle(), milestone.GetNumber())
	result += fmt.Sprintf("- State: %s\n", milestone.GetState())
	result += fmt.Sprintf("- Description: %s\n", milestone.GetDescription())
	if milestone.DueOn != nil {
		result += fmt.Sprintf("- Due: %s\n", milestone.DueOn.Format("2006-01-02 15:04:05"))
	}
	result += fmt.Sprintf("- URL: %s\n", milestone.GetHTMLURL())
	return result
}

func Test_ListMilestones(t *testing.T) {
	// Verify tool definition once
	mockClient := github.NewClient(nil)
	tool, _ := ListMilestones(stubGetClientFn(mockClient), translations.NullTranslationHelper)
	require.NoError(t, toolsnaps.Test(tool.Name, tool))

	assert.Equal(t, "list_milestones", tool.Name)
	assert.NotEmpty(t, tool.Description)
	assert.Contains(t, tool.InputSchema.Properties, "owner")
	assert.Contains(t, tool.InputSchema.Properties, "repo")
	assert.Contains(t, tool.InputSchema.Properties, "state")
	assert.ElementsMatch(t, tool.InputSchema.Required, []string{"owner", "repo"})

	// Setup mock milestones for success case
	mockMilestones := []*github.Milestone{
		{
			Number:      github.Ptr(1),
			Title:       github.Ptr("v1.0"),
			Description: github.Ptr("First release"),
			State:       github.Ptr("open"),
			OpenIssues:  github.Ptr(5),
			ClosedIssues: github.Ptr(10),
			HTMLURL:     github.Ptr("https://github.com/owner/repo/milestone/1"),
		},
	}

	tests := []struct {
		name             string
		mockedClient     *http.Client
		requestArgs      map[string]interface{}
		expectError      bool
		expectedMilestones []*github.Milestone
		expectedErrMsg   string
	}{
		{
			name: "successful milestone listing",
			mockedClient: mock.NewMockedHTTPClient(
				mock.WithRequestMatch(
					mock.GetReposMilestonesByOwnerByRepo,
					mockMilestones,
				),
			),
			requestArgs: map[string]interface{}{
				"owner": "owner",
				"repo":  "repo",
			},
			expectError:        false,
			expectedMilestones: mockMilestones,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var client *github.Client
			if tt.mockedClient != nil {
				client = github.NewClient(tt.mockedClient)
			} else {
				client = github.NewClient(nil)
			}

			_, handler := ListMilestones(stubGetClientFn(client), translations.NullTranslationHelper)

			result, err := handler(context.Background(), createMCPRequest(tt.requestArgs))

			if tt.expectError {
				require.Error(t, err)
				if tt.expectedErrMsg != "" {
					assert.Contains(t, err.Error(), tt.expectedErrMsg)
				}
			} else {
				require.NoError(t, err)
				assert.NotNil(t, result)
				textContent := getTextResult(t, result)
				assert.Contains(t, textContent.Text, "v1.0")
			}
		})
	}
}

func(t *testing.T) {
