  // Health check cho scraper
static async healthCheck(req, res) {
    try {
      // Test một URL đơn giản
      const testUrl = 'https://httpbin.org/html';
      const startTime = Date.now();

      await scraper.scrapeUrl(testUrl);

      const responseTime = Date.now() - startTime;

      res.json({
        success: true,
        message: 'Scraper hoạt động bình thường',
        data: {
          status: 'healthy',
          responseTime: `${responseTime}ms`,
          timestamp: new Date().toISOString()
        }
      });

    } catch (error) {
      res.status(500).json({
        success: false,
        message: 'Scraper có vấn đề',
        data: {
          status: 'unhealthy',
          error: error.message,
          timestamp: new Date().toISOString()
        }
      });
    }
  }

// Hàm helper để gọi API
async function callAPI(method, endpoint, data = null) {
  try {
    const config = {
      method,
      url: `${API_BASE_URL}${endpoint}`,
      headers: {
        'Content-Type': 'application/json',
      },
    };

    if (data) {
      config.data = data;
    }

    const response = await axios(config);
    return response.data;
  } catch (error) {
    console.error(`Lỗi khi gọi ${method} ${endpoint}:`, error.response?.data || error.message);
    throw error;
  }
}

