                "games_played": 100 - (i * 5)
            }
            leaderboard.append(leader)

        return {
            "success": True,
            "leaderboard": leaderboard
        }

    except Exception as e:
        logger.error(f"Leaderboard error: {e}")
        raise HTTPException(status_code=500, detail="Failed to get leaderboard")
